/**
 * Câu ví dụ từ vựng N4 — tra theo số thứ tự (no) của thẻ trong vocab.js.
 * Từ đang học được đánh dấu bằng **...** trong câu tiếng Nhật.
 */
tangoRegister('n4', 'examples', {
  "1": [{"jp":"熱があるので、医者に**診て**もらいました。","vi":"Vì bị sốt nên tôi đã được bác sĩ khám."},{"jp":"あの先生は子どもを**診る**のが上手です。","vi":"Bác sĩ đó khám cho trẻ em rất giỏi."}],
  "2": [{"jp":"駅の近くでアパートを**探して**います。","vi":"Tôi đang tìm căn hộ gần ga."},{"jp":"警察がいなくなった子どもを**捜して**います。","vi":"Cảnh sát đang tìm kiếm đứa trẻ bị mất tích."}],
  "3": [{"jp":"電車が止まって、会社に**遅れました**。","vi":"Tàu bị dừng nên tôi đã đến công ty muộn."},{"jp":"明日の会議に**遅れない**ようにしてください。","vi":"Hãy cố gắng đừng đến muộn cuộc họp ngày mai."}],
  "4": [{"jp":"タクシーで行ったので、飛行機に**間に合いました**。","vi":"Vì đi bằng taxi nên tôi đã kịp chuyến bay."},{"jp":"今出れば、9時の電車に**間に合う**よ。","vi":"Nếu đi bây giờ thì sẽ kịp chuyến tàu 9 giờ đấy."}],
  "5": [{"jp":"毎日宿題を**やって**から遊びます。","vi":"Mỗi ngày tôi làm bài tập xong rồi mới chơi."},{"jp":"週末は友だちとテニスを**やります**。","vi":"Cuối tuần tôi chơi tennis với bạn."}],
  "6": [{"jp":"来週のパーティーに**参加します**。","vi":"Tôi sẽ tham gia bữa tiệc tuần sau."},{"jp":"このボランティア活動には100人が**参加しました**。","vi":"100 người đã tham gia hoạt động tình nguyện này."}],
  "7": [{"jp":"インターネットで日本語の試験に**申し込みました**。","vi":"Tôi đã đăng ký kỳ thi tiếng Nhật qua internet."},{"jp":"料理教室に**申し込む**なら、今週中にしてください。","vi":"Nếu muốn đăng ký lớp nấu ăn thì hãy làm trong tuần này."}],
  "8": [{"jp":"明日の午後なら**都合がいい**です。","vi":"Nếu là chiều mai thì tôi thuận tiện."},{"jp":"皆の**都合がいい**日に会いましょう。","vi":"Hãy gặp nhau vào ngày mà mọi người đều tiện."}],
  "9": [{"jp":"すみません、土曜日は**都合が悪い**んです。","vi":"Xin lỗi, thứ Bảy tôi không tiện."},{"jp":"**都合が悪く**なったら、早めに連絡してください。","vi":"Nếu không còn tiện nữa thì hãy liên lạc sớm cho tôi."}],
  "10": [{"jp":"朝散歩をすると、**気分がいい**です。","vi":"Đi dạo buổi sáng thì cảm thấy dễ chịu."},{"jp":"窓を開けたら、風が入って**気分がよく**なりました。","vi":"Mở cửa sổ ra, gió lùa vào làm tôi thấy dễ chịu hơn."}],
  "11": [{"jp":"バスに酔って、**気分が悪く**なりました。","vi":"Tôi bị say xe buýt nên thấy khó chịu."},{"jp":"**気分が悪い**なら、少し休んだほうがいいですよ。","vi":"Nếu thấy khó chịu thì nên nghỉ một chút đi."}],
  "12": [{"jp":"兄は**新聞社**で記者として働いています。","vi":"Anh trai tôi làm phóng viên ở tòa soạn báo."},{"jp":"その事故のことを、すぐに**新聞社**に知らせました。","vi":"Tôi đã báo ngay chuyện vụ tai nạn đó cho tòa soạn báo."}],
  "13": [{"jp":"弟は毎週**柔道**を習っています。","vi":"Em trai tôi học nhu đạo mỗi tuần."},{"jp":"**柔道**は日本で生まれたスポーツです。","vi":"Nhu đạo là môn thể thao ra đời ở Nhật Bản."}],
  "14": [{"jp":"子どもの学校で**運動会**がありました。","vi":"Ở trường của con tôi đã có hội thao."},{"jp":"**運動会**で息子は一番速く走りました。","vi":"Trong hội thao, con trai tôi đã chạy nhanh nhất."}],
  "15": [{"jp":"パーティーの**場所**はどこですか。","vi":"Địa điểm bữa tiệc ở đâu vậy?"},{"jp":"ここは車を止める**場所**ではありません。","vi":"Đây không phải là chỗ để đỗ xe."}],
  "16": [{"jp":"田中さんは大阪の出身なので、**大阪弁**で話します。","vi":"Anh Tanaka quê ở Osaka nên nói giọng Osaka."},{"jp":"祖母の**東北弁**は、ときどき分かりません。","vi":"Giọng Tohoku của bà tôi đôi khi tôi không hiểu."}],
  "17": [{"jp":"**今度**の日曜日、一緒に映画を見に行きませんか。","vi":"Chủ nhật tới, cùng đi xem phim không?"},{"jp":"**今度**会ったときに、その本を返します。","vi":"Lần tới gặp nhau tôi sẽ trả cuốn sách đó."}],
  "18": [{"jp":"久しぶりに会ったら、弟は**ずいぶん**背が高くなっていました。","vi":"Lâu ngày gặp lại, em trai tôi đã cao lên khá nhiều."},{"jp":"この町は10年前と比べて**ずいぶん**変わりました。","vi":"Thị trấn này đã thay đổi khá nhiều so với 10 năm trước."}],
  "19": [{"jp":"大切なことなので、**直接**会って話したいです。","vi":"Vì là chuyện quan trọng nên tôi muốn gặp trực tiếp để nói."},{"jp":"この薬は**直接**肌に塗らないでください。","vi":"Đừng bôi thuốc này trực tiếp lên da."}],
  "20": [{"jp":"部屋がきれいに**片付きました**。","vi":"Căn phòng đã được dọn dẹp gọn gàng."},{"jp":"仕事が**片付いたら**、飲みに行きましょう。","vi":"Xong xuôi công việc thì đi uống nhé."}],
  "21": [{"jp":"**ごみ**は決められた日に出してください。","vi":"Hãy đổ rác vào ngày quy định."},{"jp":"公園に**ごみ**を捨てないでください。","vi":"Đừng vứt rác ở công viên."}],
  "22": [{"jp":"燃えるごみは火曜日の朝に**出します**。","vi":"Rác cháy được thì đổ vào sáng thứ Ba."},{"jp":"明日までに先生にレポートを**出して**ください。","vi":"Hãy nộp báo cáo cho thầy trước ngày mai."}],
  "23": [{"jp":"紙は**燃える**ごみの日に出してください。","vi":"Giấy thì hãy đổ vào ngày rác cháy được."},{"jp":"昨日の夜、近くの家が**燃えて**いました。","vi":"Tối qua, một ngôi nhà gần đây đã bị cháy."}],
  "24": [{"jp":"ごみは**月・水・金**に出します。","vi":"Rác được đổ vào thứ Hai, thứ Tư và thứ Sáu."},{"jp":"日本語の授業は**月・水・金**の午後です。","vi":"Giờ học tiếng Nhật là chiều thứ Hai, thứ Tư, thứ Sáu."}],
  "25": [{"jp":"ごみ**置き場**はマンションの裏にあります。","vi":"Chỗ để rác ở phía sau chung cư."},{"jp":"駅の自転車**置き場**はいつもいっぱいです。","vi":"Bãi để xe đạp ở ga lúc nào cũng kín chỗ."}],
  "26": [{"jp":"銀行は郵便局の**横**にあります。","vi":"Ngân hàng ở bên cạnh bưu điện."},{"jp":"電車で知らない人が私の**横**に座りました。","vi":"Trên tàu, một người lạ đã ngồi bên cạnh tôi."}],
  "27": [{"jp":"空いた**瓶**は水曜日に出してください。","vi":"Chai rỗng thì hãy đổ vào thứ Tư."},{"jp":"冷蔵庫にジャムの**瓶**が入っています。","vi":"Trong tủ lạnh có lọ mứt."}],
  "28": [{"jp":"自動販売機で**缶**コーヒーを買いました。","vi":"Tôi đã mua cà phê lon ở máy bán hàng tự động."},{"jp":"飲み終わった**缶**は、このごみ箱に入れてください。","vi":"Lon đã uống xong thì hãy bỏ vào thùng rác này."}],
  "29": [{"jp":"**お湯**を沸かして、お茶を入れます。","vi":"Tôi đun nước nóng rồi pha trà."},{"jp":"このシャワーは**お湯**が出ません。","vi":"Vòi sen này không ra nước nóng."}],
  "30": [{"jp":"遅れるときは、必ず会社に**連絡して**ください。","vi":"Khi đến muộn, nhất định phải liên lạc với công ty."},{"jp":"卒業してから、彼とは一度も**連絡して**いません。","vi":"Từ khi tốt nghiệp, tôi chưa liên lạc với anh ấy lần nào."}],
  "31": [{"jp":"**困ったなあ**。財布を家に忘れてきた。","vi":"Làm thế nào đây! Tôi để quên ví ở nhà rồi."},{"jp":"「電車が止まっているそうですよ。」「**困ったなあ**。会議に間に合わない。」","vi":"\"Nghe nói tàu đang dừng đấy.\" \"Làm thế nào đây! Không kịp cuộc họp mất.\""}],
  "32": [{"jp":"資料は**電子メール**で送ります。","vi":"Tôi sẽ gửi tài liệu bằng thư điện tử."},{"jp":"最近は手紙より**電子メール**を使う人が多いです。","vi":"Gần đây nhiều người dùng thư điện tử hơn là thư tay."}],
  "33": [{"jp":"いつか**宇宙**へ行ってみたいです。","vi":"Một ngày nào đó tôi muốn thử đi vào vũ trụ."},{"jp":"**宇宙**から見た地球は青くてきれいだそうです。","vi":"Nghe nói Trái Đất nhìn từ vũ trụ có màu xanh và rất đẹp."}],
  "34": [{"jp":"夜一人で歩くのは**怖い**です。","vi":"Đi bộ một mình vào ban đêm thật đáng sợ."},{"jp":"子どものころ、犬が**怖くて**近づけませんでした。","vi":"Hồi nhỏ tôi sợ chó nên không dám lại gần."}],
  "35": [{"jp":"**宇宙船**が無事に地球に戻りました。","vi":"Tàu vũ trụ đã trở về Trái Đất an toàn."},{"jp":"子どもたちは紙で**宇宙船**を作りました。","vi":"Bọn trẻ đã làm tàu vũ trụ bằng giấy."}],
  "36": [{"jp":"このシャツは小さいので、**別の**サイズはありますか。","vi":"Cái áo này nhỏ, có cỡ khác không?"},{"jp":"今日は忙しいので、**別の**日にしてください。","vi":"Hôm nay tôi bận, hãy để vào ngày khác."}],
  "37": [{"jp":"弟の夢は**宇宙飛行士**になることです。","vi":"Ước mơ của em trai tôi là trở thành nhà du hành vũ trụ."},{"jp":"**宇宙飛行士**は宇宙船の中で実験をします。","vi":"Phi hành gia làm thí nghiệm bên trong tàu vũ trụ."}],
  "38": [{"jp":"家で猫を2匹**飼って**います。","vi":"Tôi đang nuôi 2 con mèo ở nhà."},{"jp":"このアパートではペットを**飼って**はいけません。","vi":"Ở căn hộ này không được nuôi thú cưng."}],
  "39": [{"jp":"父は田舎に家を**建てました**。","vi":"Bố tôi đã xây nhà ở quê."},{"jp":"駅の前に新しいビルを**建てて**います。","vi":"Người ta đang xây tòa nhà mới trước ga."}],
  "40": [{"jp":"毎朝、公園を30分**走って**います。","vi":"Mỗi sáng tôi chạy 30 phút ở công viên."},{"jp":"この道はたくさんの車が**走って**います。","vi":"Trên con đường này có rất nhiều xe chạy."}],
  "41": [{"jp":"来週、休みを**取って**旅行に行きます。","vi":"Tuần sau tôi sẽ xin nghỉ để đi du lịch."},{"jp":"すみません、その塩を**取って**ください。","vi":"Xin lỗi, lấy giúp tôi lọ muối đó."}],
  "42": [{"jp":"晴れた日には、ここから富士山が**見えます**。","vi":"Vào ngày trời quang, từ đây có thể nhìn thấy núi Phú Sĩ."},{"jp":"眼鏡をかけないと、黒板の字がよく**見えません**。","vi":"Nếu không đeo kính thì tôi không nhìn rõ chữ trên bảng."}],
  "43": [{"jp":"隣の部屋からピアノの音が**聞こえます**。","vi":"Nghe thấy tiếng đàn piano từ phòng bên cạnh."},{"jp":"電話の声が小さくて、よく**聞こえません**。","vi":"Giọng trong điện thoại nhỏ quá, tôi không nghe rõ."}],
  "44": [{"jp":"駅の前に新しいスーパーが**できました**。","vi":"Trước ga đã mọc lên một siêu thị mới."},{"jp":"来年、この町に大きい病院が**できます**。","vi":"Năm sau, thị trấn này sẽ có một bệnh viện lớn được xây."}],
  "45": [{"jp":"毎週土曜日に料理教室を**開いて**います。","vi":"Thứ Bảy hằng tuần tôi mở lớp dạy nấu ăn."},{"jp":"会社で新しい社員のために歓迎会を**開きました**。","vi":"Công ty đã tổ chức tiệc chào mừng nhân viên mới."}],
  "46": [{"jp":"朝、窓の外で**鳥**が鳴いています。","vi":"Buổi sáng, chim đang hót ngoài cửa sổ."},{"jp":"空を白い**鳥**が飛んでいます。","vi":"Một con chim trắng đang bay trên bầu trời."}],
  "47": [{"jp":"電話で母の**声**を聞いて、安心しました。","vi":"Nghe giọng mẹ qua điện thoại, tôi thấy yên tâm."},{"jp":"秋の夜は虫の**声**がきれいです。","vi":"Đêm mùa thu, tiếng côn trùng kêu rất hay."}],
  "48": [{"jp":"今日は**波**が高いので、海で泳がないでください。","vi":"Hôm nay sóng cao nên đừng bơi ở biển."},{"jp":"海の近くのホテルで、**波**の音を聞きながら寝ました。","vi":"Tôi ngủ ở khách sạn gần biển, vừa ngủ vừa nghe tiếng sóng."}],
  "49": [{"jp":"夏になると、川で**花火**大会があります。","vi":"Đến mùa hè, có lễ hội pháo hoa bên sông."},{"jp":"友だちと公園で**花火**をしました。","vi":"Tôi đã đốt pháo hoa với bạn ở công viên."}],
  "50": [{"jp":"山の上から見た**景色**は本当にきれいでした。","vi":"Phong cảnh nhìn từ trên núi thật sự rất đẹp."},{"jp":"電車の窓から外の**景色**を楽しみました。","vi":"Tôi đã ngắm cảnh bên ngoài qua cửa sổ tàu."}],
  "51": [{"jp":"**昼間**は暖かいですが、夜は寒くなります。","vi":"Ban ngày thì ấm nhưng ban đêm trời trở lạnh."},{"jp":"父は**昼間**働いて、夜大学に通っています。","vi":"Bố tôi ban ngày đi làm, buổi tối đi học đại học."}],
  "52": [{"jp":"**昔**、ここには大きな池がありました。","vi":"Ngày xưa, ở đây có một cái ao lớn."},{"jp":"祖父はよく**昔**の話をしてくれます。","vi":"Ông tôi hay kể chuyện ngày xưa cho tôi nghe."}],
  "53": [{"jp":"料理の**道具**を台所に片付けました。","vi":"Tôi đã cất dụng cụ nấu ăn vào bếp."},{"jp":"この棚は、簡単な**道具**だけで作れます。","vi":"Cái kệ này có thể làm chỉ với những dụng cụ đơn giản."}],
  "54": [{"jp":"駅の**自動販売機**で飲み物を買いました。","vi":"Tôi đã mua đồ uống ở máy bán hàng tự động trong ga."},{"jp":"日本には町のあちこちに**自動販売機**があります。","vi":"Ở Nhật, khắp nơi trong thành phố đều có máy bán hàng tự động."}],
  "55": [{"jp":"最近は**通信販売**で服を買う人が多いです。","vi":"Gần đây nhiều người mua quần áo qua hình thức bán hàng từ xa."},{"jp":"この化粧品は**通信販売**でしか買えません。","vi":"Mỹ phẩm này chỉ mua được qua đặt hàng từ xa."}],
  "56": [{"jp":"母は**台所**で晩ご飯を作っています。","vi":"Mẹ đang nấu bữa tối trong bếp."},{"jp":"新しい家の**台所**は広くて明るいです。","vi":"Bếp của ngôi nhà mới rộng và sáng sủa."}],
  "57": [{"jp":"毎週水曜日に**料理教室**に通っています。","vi":"Thứ Tư hằng tuần tôi đi học lớp nấu ăn."},{"jp":"近所の**英語教室**は子どもに人気があります。","vi":"Lớp học tiếng Anh gần nhà được trẻ em yêu thích."}],
  "58": [{"jp":"卒業**後**は日本で働きたいです。","vi":"Sau khi tốt nghiệp tôi muốn làm việc ở Nhật."},{"jp":"三日**後**に試験の結果が分かります。","vi":"Ba ngày sau sẽ biết kết quả thi."}],
  "59": [{"jp":"財布に500円**しか**ありません。","vi":"Trong ví tôi chỉ có 500 yên."},{"jp":"昨日は3時間**しか**寝ませんでした。","vi":"Hôm qua tôi chỉ ngủ được 3 tiếng."}],
  "60": [{"jp":"この色はあまり好きじゃないので、**他の**色を見せてください。","vi":"Tôi không thích màu này lắm, cho tôi xem màu khác."},{"jp":"このことは**他の**人には言わないでください。","vi":"Đừng nói chuyện này với người khác."}],
  "61": [{"jp":"眼鏡をかけると、字が**はっきり**見えます。","vi":"Đeo kính vào thì nhìn chữ rõ ràng."},{"jp":"嫌なときは、**はっきり**「いいえ」と言ったほうがいいです。","vi":"Khi không thích thì nên nói rõ ràng là \"không\"."}],
  "62": [{"jp":"宿題は**ほとんど**終わりました。","vi":"Bài tập tôi đã làm gần xong hết."},{"jp":"彼はお酒を**ほとんど**飲みません。","vi":"Anh ấy hầu như không uống rượu."}],
  "63": [{"jp":"父の趣味は**日曜大工**です。","vi":"Sở thích của bố tôi là tự làm đồ mộc."},{"jp":"**日曜大工**で犬の家を作りました。","vi":"Tôi tự đóng chuồng chó vào ngày nghỉ."}],
  "64": [{"jp":"**本棚**に漫画がたくさん並んでいます。","vi":"Trên giá sách xếp rất nhiều truyện tranh."},{"jp":"父と一緒に**本棚**を作りました。","vi":"Tôi đã cùng bố đóng giá sách."}],
  "65": [{"jp":"昨日、怖い**夢**を見ました。","vi":"Hôm qua tôi đã mơ một giấc mơ đáng sợ."},{"jp":"私の**夢**は医者になることです。","vi":"Ước mơ của tôi là trở thành bác sĩ."}],
  "66": [{"jp":"**家**に帰って、すぐ寝ました。","vi":"Về đến nhà, tôi đi ngủ ngay."},{"jp":"今度、私の**家**に遊びに来てください。","vi":"Lần tới hãy đến nhà tôi chơi nhé."}],
  "67": [{"jp":"昨日のコンサートは**素晴らしかった**です。","vi":"Buổi hòa nhạc hôm qua thật tuyệt vời."},{"jp":"山の上から**素晴らしい**景色が見えました。","vi":"Từ trên núi có thể nhìn thấy phong cảnh tuyệt đẹp."}],
  "68": [{"jp":"**子供達**が公園で元気に遊んでいます。","vi":"Bọn trẻ đang chơi đùa vui vẻ ở công viên."},{"jp":"休みの日は**子供達**と一緒に料理をします。","vi":"Ngày nghỉ tôi nấu ăn cùng các con."}],
  "69": [{"jp":"私は甘いものが**大好き**です。","vi":"Tôi rất thích đồ ngọt."},{"jp":"**大好きな**歌手のコンサートに行きました。","vi":"Tôi đã đi xem buổi hòa nhạc của ca sĩ mình rất thích."}],
  "70": [{"jp":"弟は毎日**漫画**を読んでいます。","vi":"Em trai tôi ngày nào cũng đọc truyện tranh."},{"jp":"この**漫画**はアニメにもなりました。","vi":"Bộ truyện tranh này cũng đã được chuyển thể thành anime."}],
  "71": [{"jp":"この映画の**主人公**は高校生です。","vi":"Nhân vật chính của bộ phim này là một học sinh cấp ba."},{"jp":"小説の**主人公**は最後に夢をかなえました。","vi":"Nhân vật chính của cuốn tiểu thuyết cuối cùng đã thực hiện được ước mơ."}],
  "72": [{"jp":"このクッキーは星の**形**をしています。","vi":"Chiếc bánh quy này có hình ngôi sao."},{"jp":"雲の**形**が動物に見えます。","vi":"Hình dạng đám mây trông giống con vật."}],
  "73": [{"jp":"昨日、**不思議な**夢を見ました。","vi":"Hôm qua tôi đã mơ một giấc mơ kỳ lạ."},{"jp":"宇宙にはまだ**不思議な**ことがたくさんあります。","vi":"Trong vũ trụ vẫn còn rất nhiều điều bí ẩn."}],
  "74": [{"jp":"日本の料理、**例えば**寿司や天ぷらが好きです。","vi":"Tôi thích món Nhật, ví dụ như sushi hay tempura."},{"jp":"スポーツ、**例えば**サッカーやテニスをするのが好きです。","vi":"Tôi thích chơi thể thao, ví dụ như bóng đá hay tennis."}],
  "75": [{"jp":"自転車にかごを**付けました**。","vi":"Tôi đã lắp giỏ vào xe đạp."},{"jp":"部屋の壁に棚を**付けたい**です。","vi":"Tôi muốn gắn kệ lên tường phòng."}],
  "76": [{"jp":"ここにある本は**自由に**読んでもいいです。","vi":"Sách ở đây có thể đọc tự do."},{"jp":"鳥のように**自由に**空を飛びたいです。","vi":"Tôi muốn bay tự do trên trời như chim."}],
  "77": [{"jp":"今日は**空**がとても青いです。","vi":"Hôm nay bầu trời rất xanh."},{"jp":"夜の**空**にたくさんの星が見えます。","vi":"Có thể thấy rất nhiều sao trên bầu trời đêm."}],
  "78": [{"jp":"鳥が空を**飛んで**います。","vi":"Chim đang bay trên bầu trời."},{"jp":"強い風で帽子が**飛んで**しまいました。","vi":"Gió mạnh làm chiếc mũ bay mất."}],
  "79": [{"jp":"宿題は**自分**でやりなさい。","vi":"Bài tập thì tự mình làm đi."},{"jp":"**自分**の意見をはっきり言うことは大切です。","vi":"Nói rõ ý kiến của bản thân là điều quan trọng."}],
  "80": [{"jp":"**将来**、日本の会社で働きたいです。","vi":"Trong tương lai, tôi muốn làm việc ở công ty Nhật."},{"jp":"子どもの**将来**のために、お金をためています。","vi":"Tôi đang tiết kiệm tiền cho tương lai của con."}],
  "81": [{"jp":"この新しいゲームはとてもよく**売れて**います。","vi":"Trò chơi mới này đang bán rất chạy."},{"jp":"暑い日はアイスクリームがたくさん**売れます**。","vi":"Ngày nóng thì kem bán được rất nhiều."}],
  "82": [{"jp":"パーティーで友だちと**踊りました**。","vi":"Tôi đã nhảy cùng bạn bè ở bữa tiệc."},{"jp":"夏祭りでは、町の人たちが一緒に**踊ります**。","vi":"Ở lễ hội mùa hè, người dân trong thị trấn cùng nhau nhảy múa."}],
  "83": [{"jp":"ご飯はよく**噛んで**食べましょう。","vi":"Hãy nhai kỹ khi ăn cơm."},{"jp":"公園で犬に足を**噛まれました**。","vi":"Tôi bị chó cắn vào chân ở công viên."}],
  "84": [{"jp":"母の誕生日プレゼントを**選んで**います。","vi":"Tôi đang chọn quà sinh nhật cho mẹ."},{"jp":"好きな色を一つ**選んで**ください。","vi":"Hãy chọn một màu bạn thích."}],
  "85": [{"jp":"私と姉は性格が全然**違います**。","vi":"Tôi và chị gái có tính cách hoàn toàn khác nhau."},{"jp":"すみません、この電話番号は**違う**と思います。","vi":"Xin lỗi, tôi nghĩ số điện thoại này không đúng."}],
  "86": [{"jp":"毎日バスで学校に**通って**います。","vi":"Hằng ngày tôi đi học bằng xe buýt."},{"jp":"週に2回、ジムに**通って**います。","vi":"Tôi đi tập gym 2 lần một tuần."}],
  "87": [{"jp":"大切なことは、忘れないように**メモします**。","vi":"Những điều quan trọng thì tôi ghi chép lại để khỏi quên."},{"jp":"先生の話を**メモして**ください。","vi":"Hãy ghi chép lại lời thầy nói."}],
  "88": [{"jp":"彼はとても**真面目**な学生です。","vi":"Cậu ấy là một học sinh rất nghiêm túc."},{"jp":"**真面目**に勉強すれば、試験に合格できますよ。","vi":"Nếu học hành nghiêm túc thì sẽ thi đỗ đấy."}],
  "89": [{"jp":"学生たちは**熱心**に先生の話を聞いています。","vi":"Các học sinh đang chăm chú lắng nghe thầy giảng."},{"jp":"山田さんは仕事に**熱心**な人です。","vi":"Anh Yamada là người nhiệt tình với công việc."}],
  "90": [{"jp":"祖母はいつも**優しい**です。","vi":"Bà tôi lúc nào cũng hiền hậu."},{"jp":"困っていたら、知らない人が**優しく**道を教えてくれました。","vi":"Khi tôi đang lúng túng, một người lạ đã ân cần chỉ đường cho tôi."}],
  "91": [{"jp":"毎日一人で勉強して、**偉い**ね。","vi":"Ngày nào cũng tự học, giỏi quá nhỉ."},{"jp":"父は会社で**偉い**人らしいです。","vi":"Nghe nói bố tôi là người có chức vụ cao ở công ty."}],
  "92": [{"jp":"このくつはサイズが**丁度いい**です。","vi":"Đôi giày này vừa đúng cỡ."},{"jp":"お風呂のお湯が**丁度いい**温かさです。","vi":"Nước bồn tắm ấm vừa phải."}],
  "93": [{"jp":"毎朝ジョギングするのが私の**習慣**です。","vi":"Chạy bộ mỗi sáng là thói quen của tôi."},{"jp":"日本には、家に入るときくつを脱ぐ**習慣**があります。","vi":"Ở Nhật có tập quán cởi giày khi vào nhà."}],
  "94": [{"jp":"外国で働いた**経験**があります。","vi":"Tôi có kinh nghiệm làm việc ở nước ngoài."},{"jp":"この仕事は**経験**がなくても大丈夫です。","vi":"Công việc này không có kinh nghiệm cũng không sao."}],
  "95": [{"jp":"兄は**力**が強いです。","vi":"Anh trai tôi rất khỏe."},{"jp":"みんなで**力**を合わせて、重い荷物を運びました。","vi":"Mọi người hợp sức khiêng đồ đạc nặng."}],
  "96": [{"jp":"このラーメン屋は若い人に**人気**があります。","vi":"Quán ramen này được giới trẻ yêu thích."},{"jp":"**人気**のある店なので、いつも込んでいます。","vi":"Vì là quán được ưa chuộng nên lúc nào cũng đông."}],
  "97": [{"jp":"この花瓶は**形**がおもしろいです。","vi":"Cái bình hoa này có hình dáng thú vị."},{"jp":"色も**形**もいいので、このかばんを買いました。","vi":"Cả màu lẫn kiểu dáng đều đẹp nên tôi đã mua chiếc túi này."}],
  "98": [{"jp":"好きな**色**は青です。","vi":"Màu tôi thích là màu xanh."},{"jp":"秋になると、木の葉の**色**が変わります。","vi":"Đến mùa thu, màu lá cây thay đổi."}],
  "99": [{"jp":"このスープは**味**が薄いです。","vi":"Món súp này vị hơi nhạt."},{"jp":"母の料理の**味**が忘れられません。","vi":"Tôi không thể quên hương vị món ăn của mẹ."}],
  "100": [{"jp":"この店は**品物**がいいので、よく来ます。","vi":"Cửa hàng này hàng hóa tốt nên tôi hay đến."},{"jp":"注文した**品物**が今日届きました。","vi":"Món hàng tôi đặt đã đến hôm nay."}],
  "101": [{"jp":"この店は**値段**が安くておいしいです。","vi":"Quán này giá rẻ mà ngon."},{"jp":"野菜の**値段**が上がりました。","vi":"Giá rau đã tăng lên."}],
  "102": [{"jp":"今月は**給料**が少し上がりました。","vi":"Tháng này lương tăng một chút."},{"jp":"**給料**が出たら、新しい靴を買います。","vi":"Khi có lương tôi sẽ mua giày mới."}],
  "103": [{"jp":"毎晩、ニュース**番組**を見ます。","vi":"Tối nào tôi cũng xem chương trình thời sự."},{"jp":"この料理**番組**はとても人気があります。","vi":"Chương trình nấu ăn này rất được yêu thích."}],
  "104": [{"jp":"寝る前に**小説**を読みます。","vi":"Tôi đọc tiểu thuyết trước khi ngủ."},{"jp":"この**小説**は映画になりました。","vi":"Cuốn tiểu thuyết này đã được dựng thành phim."}],
  "105": [{"jp":"村上春樹は有名な**小説家**です。","vi":"Murakami Haruki là một tiểu thuyết gia nổi tiếng."},{"jp":"私は**小説家**になって、本を書きたいです。","vi":"Tôi muốn trở thành tiểu thuyết gia và viết sách."}],
  "106": [{"jp":"姉は**歌手**になるのが夢です。","vi":"Ước mơ của chị tôi là trở thành ca sĩ."},{"jp":"この**歌手**の歌は若い人に人気があります。","vi":"Bài hát của ca sĩ này được giới trẻ yêu thích."}],
  "107": [{"jp":"部屋の電気が壊れたので、**管理人**さんに連絡しました。","vi":"Đèn trong phòng bị hỏng nên tôi đã liên lạc với người quản lý."},{"jp":"このマンションの**管理人**はとても親切です。","vi":"Người quản lý chung cư này rất tốt bụng."}],
  "108": [{"jp":"**息子**は今年大学に入学しました。","vi":"Con trai tôi năm nay đã vào đại học."},{"jp":"私の**息子**はサッカーが大好きです。","vi":"Con trai tôi rất thích bóng đá."}],
  "109": [{"jp":"**息子さん**はおいくつですか。","vi":"Con trai anh/chị bao nhiêu tuổi rồi?"},{"jp":"田中さんの**息子さん**は医者だそうです。","vi":"Nghe nói con trai của anh Tanaka là bác sĩ."}],
  "110": [{"jp":"**娘**は来月結婚します。","vi":"Con gái tôi sẽ kết hôn vào tháng sau."},{"jp":"うちの**娘**はピアノを習っています。","vi":"Con gái nhà tôi đang học piano."}],
  "111": [{"jp":"**娘さん**は何歳ですか。","vi":"Con gái anh/chị mấy tuổi rồi?"},{"jp":"先生の**娘さん**はとてもかわいいですね。","vi":"Con gái của thầy dễ thương quá nhỉ."}],
  "112": [{"jp":"**自分**の荷物は、必ず持って帰ってください。","vi":"Hãy nhớ mang đồ của mình về."},{"jp":"失敗したのは**自分**のせいです。","vi":"Thất bại là do lỗi của chính tôi."}],
  "113": [{"jp":"**将来**の夢は何ですか。","vi":"Ước mơ tương lai của bạn là gì?"},{"jp":"近い**将来**、車は自動で走るようになるでしょう。","vi":"Trong tương lai gần, ô tô có lẽ sẽ tự lái."}],
  "114": [{"jp":"**しばらく**お待ちください。","vi":"Xin vui lòng đợi một lát."},{"jp":"仕事が忙しくて、**しばらく**国に帰っていません。","vi":"Công việc bận rộn nên một thời gian rồi tôi chưa về nước."}],
  "115": [{"jp":"日曜日は**大抵**家で本を読んでいます。","vi":"Chủ nhật tôi thường ở nhà đọc sách."},{"jp":"朝ご飯は**大抵**パンです。","vi":"Bữa sáng của tôi thường là bánh mì."}],
  "116": [{"jp":"この部屋は広いです。**それに**駅から近いです。","vi":"Căn phòng này rộng. Thêm vào đó lại gần ga."},{"jp":"今日は雨だし、**それに**寒いから、出かけたくない。","vi":"Hôm nay trời mưa, thêm nữa lại lạnh, nên tôi không muốn ra ngoài."}],
  "117": [{"jp":"昨日は熱がありました。**それで**、学校を休みました。","vi":"Hôm qua tôi bị sốt. Thế nên tôi đã nghỉ học."},{"jp":"「道が込んでいたんです。」「**それで**遅れたんですね。」","vi":"\"Đường bị tắc ạ.\" \"Thế nên anh đến muộn à.\""}],
  "118": [{"jp":"日本人と**会話**の練習をしています。","vi":"Tôi đang luyện hội thoại với người Nhật."},{"jp":"彼との**会話**はいつも楽しいです。","vi":"Nói chuyện với anh ấy lúc nào cũng vui."}],
  "119": [{"jp":"友だちとカフェで**おしゃべりしました**。","vi":"Tôi đã tán gẫu với bạn ở quán cà phê."},{"jp":"授業中に**おしゃべりして**はいけません。","vi":"Không được nói chuyện riêng trong giờ học."}],
  "120": [{"jp":"掲示板に新しい**お知らせ**が貼ってあります。","vi":"Trên bảng tin có dán thông báo mới."},{"jp":"会社から休みの**お知らせ**がメールで来ました。","vi":"Công ty đã gửi thông báo về kỳ nghỉ qua email."}],
  "121": [{"jp":"パーティーの**日にち**を決めましょう。","vi":"Chúng ta hãy quyết định ngày tổ chức tiệc."},{"jp":"試験の**日にち**と場所を確認してください。","vi":"Hãy kiểm tra ngày và địa điểm thi."}],
  "122": [{"jp":"図書館は**土**・日も開いています。","vi":"Thư viện mở cửa cả thứ Bảy và Chủ nhật."},{"jp":"営業時間は月～**土**の10時から19時までです。","vi":"Giờ mở cửa là từ thứ Hai đến thứ Bảy, từ 10 giờ đến 19 giờ."}],
  "123": [{"jp":"雨の日は**体育館**でバスケットボールをします。","vi":"Ngày mưa thì chơi bóng rổ trong nhà thể dục."},{"jp":"卒業式は学校の**体育館**で行われます。","vi":"Lễ tốt nghiệp được tổ chức ở nhà thể dục của trường."}],
  "124": [{"jp":"この美術館は子どもは**無料**です。","vi":"Bảo tàng mỹ thuật này miễn phí cho trẻ em."},{"jp":"駐車場は2時間まで**無料**です。","vi":"Bãi đỗ xe miễn phí trong 2 tiếng đầu."}],
  "125": [{"jp":"風でドアが**開きました**。","vi":"Cửa bị gió thổi mở ra."},{"jp":"この店は朝10時に**開きます**。","vi":"Cửa hàng này mở cửa lúc 10 giờ sáng."}],
  "126": [{"jp":"銀行は3時に**閉まります**。","vi":"Ngân hàng đóng cửa lúc 3 giờ."},{"jp":"強い風で、ドアが**閉まりました**。","vi":"Gió mạnh làm cửa đóng sập lại."}],
  "127": [{"jp":"部屋の電気が**ついて**います。","vi":"Đèn trong phòng đang bật."},{"jp":"暗くなると、自動的に街灯が**つきます**。","vi":"Trời tối thì đèn đường tự động sáng."}],
  "128": [{"jp":"急に電気が**消えて**、真っ暗になりました。","vi":"Đèn đột nhiên tắt, tối om."},{"jp":"パソコンのデータが**消えて**しまいました。","vi":"Dữ liệu trong máy tính đã bị mất."}],
  "129": [{"jp":"朝の電車はいつも**込んで**います。","vi":"Tàu buổi sáng lúc nào cũng đông."},{"jp":"連休は道が**込む**ので、早く出かけましょう。","vi":"Kỳ nghỉ dài đường hay tắc nên hãy đi sớm."}],
  "130": [{"jp":"平日の昼は電車が**すいて**います。","vi":"Buổi trưa ngày thường tàu vắng."},{"jp":"朝早く行けば、道が**すいて**いますよ。","vi":"Nếu đi sớm vào buổi sáng thì đường vắng đấy."}],
  "131": [{"jp":"パソコンが**壊れて**しまいました。","vi":"Máy tính bị hỏng mất rồi."},{"jp":"地震で古い家が**壊れました**。","vi":"Ngôi nhà cũ bị đổ vì động đất."}],
  "132": [{"jp":"コップを落として、**割れて**しまいました。","vi":"Tôi làm rơi cốc và nó bị vỡ."},{"jp":"ボールが当たって、窓ガラスが**割れました**。","vi":"Quả bóng đập vào làm vỡ kính cửa sổ."}],
  "133": [{"jp":"強い風で木の枝が**折れました**。","vi":"Gió mạnh làm gãy cành cây."},{"jp":"スキーで転んで、足の骨が**折れて**しまいました。","vi":"Tôi bị ngã khi trượt tuyết và gãy xương chân."}],
  "134": [{"jp":"古いズボンが**破れて**しまいました。","vi":"Chiếc quần cũ bị rách mất rồi."},{"jp":"雨で紙の袋が**破れました**。","vi":"Túi giấy bị rách vì mưa."}],
  "135": [{"jp":"雨の日に歩いたら、靴が**汚れました**。","vi":"Đi bộ vào ngày mưa nên giày bị bẩn."},{"jp":"カレーで白いシャツが**汚れて**しまいました。","vi":"Áo sơ mi trắng bị bẩn vì cà ri."}],
  "136": [{"jp":"シャツにコーヒーのしみが**付いて**います。","vi":"Áo sơ mi bị dính vết cà phê."},{"jp":"この部屋にはエアコンが**付いて**います。","vi":"Phòng này có gắn điều hòa."}],
  "137": [{"jp":"シャツのボタンが**外れて**います。","vi":"Cúc áo sơ mi bị bung ra."},{"jp":"強い風で窓の網戸が**外れました**。","vi":"Gió mạnh làm tấm lưới cửa sổ bị bung ra."}],
  "138": [{"jp":"大雪で電車が**止まりました**。","vi":"Tàu bị dừng vì tuyết rơi dày."},{"jp":"家の前に知らない車が**止まって**います。","vi":"Có một chiếc xe lạ đang đỗ trước nhà."}],
  "139": [{"jp":"名前の漢字を**間違えて**しまいました。","vi":"Tôi đã viết nhầm chữ Hán trong tên."},{"jp":"急いでいて、乗る電車を**間違えました**。","vi":"Vì vội nên tôi đã lên nhầm tàu."}],
  "140": [{"jp":"駅で財布を**落として**しまいました。","vi":"Tôi đã đánh rơi ví ở nhà ga."},{"jp":"コップを**落とさない**ように気をつけてください。","vi":"Hãy cẩn thận để không làm rơi cái cốc."}],
  "141": [{"jp":"ドアに鍵が**かかって**いますから、入れません。","vi":"Cửa đã khóa nên không vào được."},{"jp":"窓に鍵が**かかって**いるか、確かめてください。","vi":"Hãy kiểm tra xem cửa sổ đã được khóa chưa."}],
  "142": [{"jp":"料理を**皿**に並べました。","vi":"Tôi đã bày thức ăn lên đĩa."},{"jp":"食事の後で、母と**皿**を洗います。","vi":"Sau bữa ăn, tôi rửa đĩa cùng mẹ."}],
  "143": [{"jp":"日本人はご飯を**茶碗**で食べます。","vi":"Người Nhật ăn cơm bằng bát."},{"jp":"この**茶碗**は祖母にもらったものです。","vi":"Cái bát này là đồ bà tôi tặng."}],
  "144": [{"jp":"スーパーで**袋**をもらいました。","vi":"Tôi đã nhận túi ở siêu thị."},{"jp":"ゴミを**袋**に入れて出してください。","vi":"Hãy cho rác vào túi rồi đem đi đổ."}],
  "145": [{"jp":"**財布**にお金があまりありません。","vi":"Trong ví không có nhiều tiền."},{"jp":"誕生日に新しい**財布**をもらいました。","vi":"Tôi được tặng một chiếc ví mới vào ngày sinh nhật."}],
  "146": [{"jp":"木の**枝**に鳥が止まっています。","vi":"Có con chim đậu trên cành cây."},{"jp":"強い風で**枝**が折れました。","vi":"Cành cây bị gãy vì gió mạnh."}],
  "147": [{"jp":"忘れ物をしたので、**駅員**に聞きました。","vi":"Vì để quên đồ nên tôi đã hỏi nhân viên nhà ga."},{"jp":"**駅員**さんが道を教えてくれました。","vi":"Nhân viên nhà ga đã chỉ đường cho tôi."}],
  "148": [{"jp":"**この辺**に銀行はありますか。","vi":"Quanh đây có ngân hàng không?"},{"jp":"子どものころ、**この辺**でよく遊びました。","vi":"Hồi nhỏ tôi hay chơi ở quanh đây."}],
  "149": [{"jp":"駅の**辺**はいつもにぎやかです。","vi":"Khu vực quanh nhà ga lúc nào cũng nhộn nhịp."},{"jp":"学校の**辺**に本屋があります。","vi":"Ở khu quanh trường học có hiệu sách."}],
  "150": [{"jp":"**このくらい**の大きさの箱がほしいです。","vi":"Tôi muốn một cái hộp to cỡ chừng này."},{"jp":"ご飯は**このくらい**で十分です。","vi":"Cơm chừng này là đủ rồi."}],
  "151": [{"jp":"エレベーターの前で「**お先にどうぞ**。」と言いました。","vi":"Trước thang máy, tôi đã nói: \"Xin mời anh đi trước.\""},{"jp":"「すみません、急いでいるんです。」「じゃ、**お先にどうぞ**。」","vi":"\"Xin lỗi, tôi đang vội.\" \"Vậy xin mời anh đi trước.\""}],
  "152": [{"jp":"**今の電車**に傘を忘れてしまいました。","vi":"Tôi đã để quên ô trên đoàn tàu vừa rồi."},{"jp":"**今の電車**は東京行きでしたか。","vi":"Đoàn tàu vừa rồi đi Tokyo phải không?"}],
  "153": [{"jp":"電車を降りるときは、**忘れ物**に気をつけてください。","vi":"Khi xuống tàu, hãy chú ý đừng để quên đồ."},{"jp":"教室に**忘れ物**がありました。","vi":"Có đồ ai để quên trong lớp học."}],
  "154": [{"jp":"道の**右側**を歩いてください。","vi":"Hãy đi bộ ở phía bên phải đường."},{"jp":"窓の**外側**が汚れています。","vi":"Mặt ngoài cửa sổ bị bẩn."}],
  "155": [{"jp":"その人の名前はもう**覚えていない**んです。","vi":"Tôi không còn nhớ tên người đó nữa."},{"jp":"子どものころのことは、あまり**覚えていない**。","vi":"Chuyện hồi nhỏ tôi không nhớ mấy."}],
  "156": [{"jp":"かばんを**網棚**に乗せました。","vi":"Tôi đã để cặp lên giá hành lý."},{"jp":"**網棚**の上に傘を忘れてしまいました。","vi":"Tôi đã để quên ô trên giá hành lý."}],
  "157": [{"jp":"**確か**、会議は3時からだったと思います。","vi":"Nếu tôi không nhầm thì cuộc họp bắt đầu từ 3 giờ."},{"jp":"**確か**田中さんは大阪出身でしたよね。","vi":"Nếu không nhầm thì anh Tanaka quê ở Osaka nhỉ."}],
  "158": [{"jp":"昨日の夜、大きな**地震**がありました。","vi":"Đêm qua đã có một trận động đất lớn."},{"jp":"**地震**のときは、机の下に入ってください。","vi":"Khi có động đất, hãy chui xuống gầm bàn."}],
  "159": [{"jp":"**壁**にカレンダーを掛けました。","vi":"Tôi đã treo lịch lên tường."},{"jp":"この部屋の**壁**は白いです。","vi":"Tường của căn phòng này màu trắng."}],
  "160": [{"jp":"**針**と糸でボタンを付けました。","vi":"Tôi đã đính cúc bằng kim và chỉ."},{"jp":"時計の**針**が12時を指しています。","vi":"Kim đồng hồ đang chỉ 12 giờ."}],
  "161": [{"jp":"先生は地図の駅を**指して**説明しました。","vi":"Thầy giáo chỉ vào nhà ga trên bản đồ và giải thích."},{"jp":"時計の針は3時を**指して**います。","vi":"Kim đồng hồ đang chỉ 3 giờ."}],
  "162": [{"jp":"台風で木が**倒れました**。","vi":"Cây bị đổ vì bão."},{"jp":"地震で本棚が**倒れて**しまいました。","vi":"Giá sách bị đổ do động đất."}],
  "163": [{"jp":"太陽は**西**に沈みます。","vi":"Mặt trời lặn ở phía tây."},{"jp":"駅の**西**口で待っています。","vi":"Tôi đang đợi ở cửa tây nhà ga."}],
  "164": [{"jp":"駅はあちらの**方**です。","vi":"Nhà ga ở hướng đằng kia."},{"jp":"山の**方**から冷たい風が吹いてきます。","vi":"Gió lạnh thổi đến từ hướng núi."}],
  "165": [{"jp":"封筒に切手を**貼って**ください。","vi":"Hãy dán tem lên phong bì."},{"jp":"壁にポスターが**貼って**あります。","vi":"Trên tường có dán áp phích."}],
  "166": [{"jp":"壁に絵を**掛けました**。","vi":"Tôi đã treo tranh lên tường."},{"jp":"コートはハンガーに**掛けて**ください。","vi":"Hãy treo áo khoác lên móc."}],
  "167": [{"jp":"テーブルに花を**飾りました**。","vi":"Tôi đã trang trí hoa trên bàn."},{"jp":"クリスマスツリーをきれいに**飾り**ましょう。","vi":"Hãy trang trí cây thông Noel thật đẹp nào."}],
  "168": [{"jp":"机の上に本を**並べました**。","vi":"Tôi đã xếp sách lên bàn."},{"jp":"お皿をテーブルに**並べて**ください。","vi":"Hãy bày đĩa lên bàn."}],
  "169": [{"jp":"庭に桜の木を**植えました**。","vi":"Tôi đã trồng cây anh đào trong vườn."},{"jp":"春になったら、花を**植え**ましょう。","vi":"Sang xuân thì cùng trồng hoa nào."}],
  "170": [{"jp":"使った本は棚に**戻して**ください。","vi":"Sách đã dùng xong hãy để lại lên giá."},{"jp":"はさみを元の所に**戻しました**。","vi":"Tôi đã đặt cái kéo về chỗ cũ."}],
  "171": [{"jp":"今日の授業の**まとめ**をノートに書きました。","vi":"Tôi đã viết phần tóm tắt bài học hôm nay vào vở."},{"jp":"会議の最後に、部長が**まとめ**をしました。","vi":"Cuối cuộc họp, trưởng phòng đã tổng kết lại."}],
  "172": [{"jp":"遊んだ後は、おもちゃを**片付けて**ね。","vi":"Chơi xong thì dọn đồ chơi nhé."},{"jp":"お客さんが来る前に部屋を**片付けました**。","vi":"Tôi đã dọn dẹp phòng trước khi khách đến."}],
  "173": [{"jp":"大切な書類は引き出しに**しまって**ください。","vi":"Hãy cất giấy tờ quan trọng vào ngăn kéo."},{"jp":"冬の服を箱に**しまいました**。","vi":"Tôi đã cất quần áo mùa đông vào hộp."}],
  "174": [{"jp":"夏休みの旅行は北海道に**決めました**。","vi":"Chuyến du lịch hè tôi đã quyết định đi Hokkaido."},{"jp":"パーティーの日をまだ**決めて**いません。","vi":"Tôi vẫn chưa quyết định ngày tổ chức tiệc."}],
  "175": [{"jp":"試験の結果をメールで**知らせます**。","vi":"Tôi sẽ thông báo kết quả thi qua email."},{"jp":"住所が変わったら、すぐ**知らせて**ください。","vi":"Nếu đổi địa chỉ, hãy báo ngay cho tôi."}],
  "176": [{"jp":"進学のことを先生に**相談しました**。","vi":"Tôi đã trao đổi với thầy về chuyện học lên."},{"jp":"困ったことがあったら、いつでも**相談して**ください。","vi":"Nếu có chuyện gì khó khăn, hãy bàn với tôi bất cứ lúc nào."}],
  "177": [{"jp":"明日の授業の**予習**をしました。","vi":"Tôi đã chuẩn bị bài cho buổi học ngày mai."},{"jp":"新しい言葉を調べて、**予習して**おきます。","vi":"Tôi sẽ tra từ mới để chuẩn bị bài trước."}],
  "178": [{"jp":"家に帰ったら、今日習ったことを**復習します**。","vi":"Về nhà tôi sẽ ôn lại những gì đã học hôm nay."},{"jp":"試験の前に、ちゃんと**復習して**ください。","vi":"Trước kỳ thi, hãy ôn tập cẩn thận."}],
  "179": [{"jp":"窓は開けたまま、**そのままにして**ください。","vi":"Cửa sổ cứ để mở, hãy để nguyên như thế."},{"jp":"使ったコップを**そのままにしないで**、洗ってください。","vi":"Đừng để nguyên cốc đã dùng như thế, hãy rửa đi."}],
  "180": [{"jp":"日本語の**授業**は9時に始まります。","vi":"Giờ học tiếng Nhật bắt đầu lúc 9 giờ."},{"jp":"今日は午後に**授業**がありません。","vi":"Hôm nay buổi chiều không có giờ học."}],
  "181": [{"jp":"山田先生の**講義**はとても面白いです。","vi":"Bài giảng của thầy Yamada rất thú vị."},{"jp":"大学で経済の**講義**を受けています。","vi":"Tôi đang học bài giảng kinh tế ở đại học."}],
  "182": [{"jp":"今週の土曜日は何か**予定**がありますか。","vi":"Thứ bảy tuần này bạn có kế hoạch gì không?"},{"jp":"来月、国へ帰る**予定**です。","vi":"Tôi dự định tháng sau về nước."}],
  "183": [{"jp":"掲示板に**お知らせ**が貼ってあります。","vi":"Trên bảng tin có dán tờ thông báo."},{"jp":"学校から**お知らせ**をもらいました。","vi":"Tôi đã nhận được tờ thông báo từ trường."}],
  "184": [{"jp":"旅行の**案内書**を読みました。","vi":"Tôi đã đọc sách hướng dẫn du lịch."},{"jp":"大学の**案内書**を送ってもらいました。","vi":"Tôi đã được gửi cho cuốn sách hướng dẫn của trường đại học."}],
  "185": [{"jp":"紙くずは**ゴミ箱**に捨ててください。","vi":"Hãy vứt giấy vụn vào thùng rác."},{"jp":"部屋の**ゴミ箱**がいっぱいになりました。","vi":"Thùng rác trong phòng đã đầy."}],
  "186": [{"jp":"妹は**人形**で遊ぶのが好きです。","vi":"Em gái tôi thích chơi búp bê."},{"jp":"日本の**人形**をお土産に買いました。","vi":"Tôi đã mua búp bê Nhật làm quà."}],
  "187": [{"jp":"**花瓶**にバラを入れました。","vi":"Tôi đã cắm hoa hồng vào lọ hoa."},{"jp":"猫が**花瓶**を倒してしまいました。","vi":"Con mèo đã làm đổ lọ hoa."}],
  "188": [{"jp":"出かける前に**鏡**を見ます。","vi":"Trước khi ra ngoài tôi soi gương."},{"jp":"洗面所の**鏡**が割れてしまいました。","vi":"Gương ở bồn rửa mặt bị vỡ mất rồi."}],
  "189": [{"jp":"はさみは机の**引き出し**に入っています。","vi":"Cái kéo ở trong ngăn kéo bàn."},{"jp":"**引き出し**を開けたら、古い写真がありました。","vi":"Mở ngăn kéo ra thì thấy có tấm ảnh cũ."}],
  "190": [{"jp":"日本では**玄関**で靴を脱ぎます。","vi":"Ở Nhật, người ta cởi giày ở lối vào nhà."},{"jp":"**玄関**にお客さんが来ていますよ。","vi":"Có khách đến ở cửa vào nhà đấy."}],
  "191": [{"jp":"**廊下**を走ってはいけません。","vi":"Không được chạy trên hành lang."},{"jp":"トイレは**廊下**の突き当たりにあります。","vi":"Nhà vệ sinh ở cuối hành lang."}],
  "192": [{"jp":"この**壁**は薄くて、隣の音が聞こえます。","vi":"Bức tường này mỏng nên nghe được tiếng nhà bên cạnh."},{"jp":"子どもが**壁**に落書きをしました。","vi":"Đứa trẻ đã vẽ bậy lên tường."}],
  "193": [{"jp":"公園の**池**に魚がたくさんいます。","vi":"Trong ao ở công viên có nhiều cá."},{"jp":"**池**の周りを散歩しました。","vi":"Tôi đã đi dạo quanh cái ao."}],
  "194": [{"jp":"道がわからないときは、**交番**で聞いてください。","vi":"Khi không biết đường, hãy hỏi ở bốt cảnh sát."},{"jp":"拾った財布を**交番**に届けました。","vi":"Tôi đã nộp chiếc ví nhặt được cho bốt cảnh sát."}],
  "195": [{"jp":"使った物は**元の所**に戻してください。","vi":"Đồ đã dùng hãy để lại vị trí ban đầu."},{"jp":"椅子を**元の所**に並べました。","vi":"Tôi đã xếp ghế về vị trí ban đầu."}],
  "196": [{"jp":"家の**周り**に木がたくさんあります。","vi":"Xung quanh nhà có nhiều cây."},{"jp":"池の**周り**を一周走りました。","vi":"Tôi đã chạy một vòng quanh ao."}],
  "197": [{"jp":"部屋の**真ん中**にテーブルを置きました。","vi":"Tôi đã đặt cái bàn ở chính giữa phòng."},{"jp":"写真の**真ん中**にいるのが私です。","vi":"Người đứng chính giữa bức ảnh là tôi."}],
  "198": [{"jp":"部屋の**隅**に本棚があります。","vi":"Ở góc phòng có giá sách."},{"jp":"猫が部屋の**隅**で寝ています。","vi":"Con mèo đang ngủ ở góc phòng."}],
  "199": [{"jp":"駅まで歩いて10分**ほど**かかります。","vi":"Đi bộ đến ga mất khoảng 10 phút."},{"jp":"教室に学生が20人**ほど**います。","vi":"Trong lớp có khoảng 20 học sinh."}],
  "200": [{"jp":"今月の**予定表**を壁に貼りました。","vi":"Tôi đã dán lịch tháng này lên tường."},{"jp":"旅行の**予定表**を作りましょう。","vi":"Hãy lập lịch trình cho chuyến du lịch nào."}],
  "201": [{"jp":"「荷物を運んでおきました。」「**ご苦労様**。」","vi":"\"Tôi đã chuyển hành lý xong rồi.\" \"Vất vả cho cậu quá.\""},{"jp":"遅くまで**ご苦労様**でした。","vi":"Anh đã vất vả làm đến khuya rồi."}],
  "202": [{"jp":"第一**希望**の大学に合格しました。","vi":"Tôi đã đỗ vào trường đại học nguyện vọng một."},{"jp":"将来に**希望**を持って頑張ります。","vi":"Tôi sẽ cố gắng với niềm hi vọng vào tương lai."}],
  "203": [{"jp":"今夜は**丸い**月が見えます。","vi":"Đêm nay có thể thấy trăng tròn."},{"jp":"**丸い**テーブルを買いました。","vi":"Tôi đã mua một cái bàn tròn."}],
  "204": [{"jp":"今夜は**月**がきれいですね。","vi":"Tối nay trăng đẹp nhỉ."},{"jp":"人間が初めて**月**に行ったのは1969年です。","vi":"Con người lần đầu lên mặt trăng là vào năm 1969."}],
  "205": [{"jp":"**ある**日、森で大きな熊に会いました。","vi":"Một ngày nọ, tôi đã gặp một con gấu lớn trong rừng."},{"jp":"**ある**人から面白い話を聞きました。","vi":"Tôi đã nghe một câu chuyện thú vị từ một người nọ."}],
  "206": [{"jp":"**地球**は太陽の周りを回っています。","vi":"Trái đất quay quanh mặt trời."},{"jp":"**地球**を大切にしましょう。","vi":"Hãy bảo vệ trái đất."}],
  "207": [{"jp":"友達から手紙が来て、とても**嬉しかった**です。","vi":"Tôi rất vui khi nhận được thư của bạn."},{"jp":"また会えて**嬉しい**です。","vi":"Tôi rất vui vì được gặp lại bạn."}],
  "208": [{"jp":"雨の日は**嫌**ですね。","vi":"Ngày mưa thật khó chịu nhỉ."},{"jp":"満員電車に乗るのは**嫌な**ものです。","vi":"Đi tàu chật cứng người thật là khó chịu."}],
  "209": [{"jp":"ボタンを押しました。**すると**、ドアが開きました。","vi":"Tôi đã ấn nút. Thế là cửa mở ra."},{"jp":"窓を開けました。**すると**、涼しい風が入ってきました。","vi":"Tôi mở cửa sổ. Thế là gió mát thổi vào."}],
  "210": [{"jp":"今朝は5時に**目が覚めました**。","vi":"Sáng nay tôi tỉnh giấc lúc 5 giờ."},{"jp":"大きな音で**目が覚めて**しまいました。","vi":"Tôi bị tỉnh giấc vì tiếng động lớn."}],
  "211": [{"jp":"映画は7時に**始まります**。","vi":"Phim bắt đầu lúc 7 giờ."},{"jp":"新しい学期が**始まりました**。","vi":"Học kỳ mới đã bắt đầu."}],
  "212": [{"jp":"日本語の勉強を**続けて**います。","vi":"Tôi đang tiếp tục học tiếng Nhật."},{"jp":"疲れても、最後まで走り**続けました**。","vi":"Dù mệt nhưng tôi vẫn tiếp tục chạy đến cuối."}],
  "213": [{"jp":"なくした鍵を**見つけました**。","vi":"Tôi đã tìm thấy chiếc chìa khóa bị mất."},{"jp":"駅の近くでいいレストランを**見つけました**。","vi":"Tôi đã tìm được một nhà hàng ngon gần nhà ga."}],
  "214": [{"jp":"来月、日本語能力試験を**受けます**。","vi":"Tháng sau tôi sẽ dự thi năng lực tiếng Nhật."},{"jp":"会社の面接を**受けて**きました。","vi":"Tôi đã đi phỏng vấn ở công ty về."}],
  "215": [{"jp":"弟は今年小学校に**入学しました**。","vi":"Em trai tôi năm nay đã vào tiểu học."},{"jp":"4月に大学に**入学する**予定です。","vi":"Tôi dự định nhập học đại học vào tháng 4."}],
  "216": [{"jp":"兄は去年大学を**卒業しました**。","vi":"Anh trai tôi đã tốt nghiệp đại học năm ngoái."},{"jp":"**卒業した**ら、日本の会社で働きたいです。","vi":"Tốt nghiệp xong tôi muốn làm việc ở công ty Nhật."}],
  "217": [{"jp":"明日の会議に**出席します**。","vi":"Ngày mai tôi sẽ tham dự cuộc họp."},{"jp":"友達の結婚式に**出席しました**。","vi":"Tôi đã dự lễ cưới của bạn."}],
  "218": [{"jp":"少し**休憩しましょう**。","vi":"Chúng ta nghỉ giải lao một chút nào."},{"jp":"12時から1時まで**休憩します**。","vi":"Từ 12 giờ đến 1 giờ là nghỉ giải lao."}],
  "219": [{"jp":"5月の**連休**に旅行します。","vi":"Tôi sẽ đi du lịch vào kỳ nghỉ dài tháng 5."},{"jp":"**連休**は道が込みます。","vi":"Vào kỳ nghỉ dài đường sá đông đúc."}],
  "220": [{"jp":"「私の家族」という**作文**を書きました。","vi":"Tôi đã viết bài văn \"Gia đình tôi\"."},{"jp":"先生が私の**作文**を直してくれました。","vi":"Cô giáo đã sửa bài văn của tôi."}],
  "221": [{"jp":"美術館で写真の**展覧会**をやっています。","vi":"Ở bảo tàng mỹ thuật đang có triển lãm ảnh."},{"jp":"日曜日に**展覧会**を見に行きました。","vi":"Chủ nhật tôi đã đi xem triển lãm."}],
  "222": [{"jp":"来月、姉の**結婚式**があります。","vi":"Tháng sau có lễ cưới của chị gái tôi."},{"jp":"**結婚式**で歌を歌いました。","vi":"Tôi đã hát ở lễ cưới."}],
  "223": [{"jp":"祖父の**お葬式**に出ました。","vi":"Tôi đã dự lễ tang của ông."},{"jp":"**お葬式**には黒い服を着て行きます。","vi":"Người ta mặc đồ đen khi đi dự lễ tang."}],
  "224": [{"jp":"この会社の**本社**は東京にあります。","vi":"Trụ sở chính của công ty này ở Tokyo."},{"jp":"来月から**本社**で働くことになりました。","vi":"Từ tháng sau tôi sẽ làm việc ở trụ sở chính."}],
  "225": [{"jp":"銀行の**支店**が駅前にできました。","vi":"Một chi nhánh ngân hàng đã mở trước nhà ga."},{"jp":"父は大阪**支社**で働いています。","vi":"Bố tôi làm việc ở chi nhánh Osaka."}],
  "226": [{"jp":"日曜日に**教会**へ行きます。","vi":"Chủ nhật tôi đi nhà thờ."},{"jp":"あの古い**教会**で結婚式をしました。","vi":"Chúng tôi đã tổ chức lễ cưới ở nhà thờ cổ kia."}],
  "227": [{"jp":"大学を卒業したら、**大学院**に進みたいです。","vi":"Tốt nghiệp đại học xong tôi muốn học lên cao học."},{"jp":"姉は**大学院**で経済を研究しています。","vi":"Chị gái tôi đang nghiên cứu kinh tế ở cao học."}],
  "228": [{"jp":"子どもと**動物園**へパンダを見に行きました。","vi":"Tôi đã cùng con đến vườn bách thú xem gấu trúc."},{"jp":"この**動物園**にはゾウがいます。","vi":"Vườn bách thú này có voi."}],
  "229": [{"jp":"週末は家族で**温泉**に行きます。","vi":"Cuối tuần cả nhà tôi đi suối nước nóng."},{"jp":"寒い日に**温泉**に入ると、気持ちがいいです。","vi":"Ngày lạnh mà ngâm suối nước nóng thì rất dễ chịu."}],
  "230": [{"jp":"今日は**お客さん**がたくさん来ました。","vi":"Hôm nay có nhiều khách đến."},{"jp":"**お客さん**にお茶を出してください。","vi":"Hãy mời khách trà."}],
  "231": [{"jp":"**誰か**来たようです。","vi":"Hình như có ai đó đến."},{"jp":"**誰か**この漢字の読み方を知っていますか。","vi":"Có ai biết cách đọc chữ Hán này không?"}],
  "232": [{"jp":"駅の**方**から歩いてきました。","vi":"Tôi đi bộ đến từ phía nhà ga."},{"jp":"海の**方**へ行ってみましょう。","vi":"Hãy thử đi về phía biển xem."}],
  "233": [{"jp":"昨日は一日中**ずっと**雨でした。","vi":"Hôm qua mưa suốt cả ngày."},{"jp":"子どものころから**ずっと**この町に住んでいます。","vi":"Tôi sống ở thị trấn này suốt từ hồi nhỏ."}],
  "234": [{"jp":"みんな帰りましたが、私は会社に**残りました**。","vi":"Mọi người đã về nhưng tôi ở lại công ty."},{"jp":"料理がたくさん**残って**しまいました。","vi":"Thức ăn còn thừa lại rất nhiều."}],
  "235": [{"jp":"**月に**2回、映画を見に行きます。","vi":"Mỗi tháng tôi đi xem phim 2 lần."},{"jp":"国の両親には**月に**1回電話します。","vi":"Mỗi tháng tôi gọi điện cho bố mẹ ở quê một lần."}],
  "236": [{"jp":"**普通の**日は7時に起きます。","vi":"Ngày thường tôi dậy lúc 7 giờ."},{"jp":"私は**普通の**会社員です。","vi":"Tôi là một nhân viên công ty bình thường."}],
  "237": [{"jp":"祖父は山の中の**村**に住んでいます。","vi":"Ông tôi sống ở một ngôi làng trong núi."},{"jp":"この**村**には店が一軒しかありません。","vi":"Làng này chỉ có một cửa hàng."}],
  "238": [{"jp":"週末は**映画館**へ行きます。","vi":"Cuối tuần tôi đi rạp chiếu phim."},{"jp":"駅前に新しい**映画館**ができました。","vi":"Trước nhà ga đã mở một rạp chiếu phim mới."}],
  "239": [{"jp":"虫は**嫌**です。","vi":"Tôi ghét côn trùng."},{"jp":"同じ仕事ばかりで、もう**嫌に**なりました。","vi":"Toàn làm một việc như nhau, tôi chán lắm rồi."}],
  "240": [{"jp":"今日は**空**が青くてきれいです。","vi":"Hôm nay bầu trời xanh và đẹp."},{"jp":"**空**に鳥が飛んでいます。","vi":"Có chim đang bay trên bầu trời."}],
  "241": [{"jp":"目を**閉じて**、音楽を聞きました。","vi":"Tôi nhắm mắt lại và nghe nhạc."},{"jp":"本を**閉じて**ください。","vi":"Hãy gấp sách lại."}],
  "242": [{"jp":"**都会**の生活は便利ですが、忙しいです。","vi":"Cuộc sống ở thành phố tiện lợi nhưng bận rộn."},{"jp":"若い人は**都会**に住みたがります。","vi":"Người trẻ thường muốn sống ở thành phố."}],
  "243": [{"jp":"この部屋は**自由に**使ってもいいです。","vi":"Phòng này có thể dùng tự do."},{"jp":"休みの日は**自由に**過ごしたいです。","vi":"Ngày nghỉ tôi muốn sống thoải mái tự do."}],
  "244": [{"jp":"この歌は**世界中**で歌われています。","vi":"Bài hát này được hát khắp thế giới."},{"jp":"**世界中**を旅行するのが夢です。","vi":"Đi du lịch khắp thế giới là ước mơ của tôi."}],
  "245": [{"jp":"9時に駅の前に**集まって**ください。","vi":"Hãy tập trung trước nhà ga lúc 9 giờ."},{"jp":"祭りにたくさんの人が**集まりました**。","vi":"Rất nhiều người đã tụ tập ở lễ hội."}],
  "246": [{"jp":"山の上から見た景色は**美しかった**です。","vi":"Phong cảnh nhìn từ trên núi thật đẹp."},{"jp":"京都は**美しい**町です。","vi":"Kyoto là một thành phố đẹp."}],
  "247": [{"jp":"この町は**自然**が多くて、空気がきれいです。","vi":"Thị trấn này nhiều thiên nhiên nên không khí trong lành."},{"jp":"**自然**を守ることは大切です。","vi":"Bảo vệ thiên nhiên là điều quan trọng."}],
  "248": [{"jp":"この映画は友情の**素晴らしさ**を教えてくれます。","vi":"Bộ phim này cho ta thấy sự tuyệt vời của tình bạn."},{"jp":"旅行をして、自然の**素晴らしさ**を知りました。","vi":"Qua chuyến du lịch, tôi đã biết được sự tuyệt vời của thiên nhiên."}],
  "249": [{"jp":"家に帰ってから、財布がないことに**気が付きました**。","vi":"Về đến nhà tôi mới nhận ra là không có ví."},{"jp":"彼女が髪を切ったことに**気が付きました**か。","vi":"Bạn có để ý là cô ấy đã cắt tóc không?"}],
  "250": [{"jp":"健康のために、毎日**運動して**います。","vi":"Để giữ sức khỏe, ngày nào tôi cũng vận động."},{"jp":"食べた後すぐに**運動する**のはよくありません。","vi":"Vận động ngay sau khi ăn là không tốt."}],
  "251": [{"jp":"新しい計画は**成功しました**。","vi":"Kế hoạch mới đã thành công."},{"jp":"何度も練習して、やっと**成功しました**。","vi":"Luyện tập nhiều lần, cuối cùng tôi đã thành công."}],
  "252": [{"jp":"料理に**失敗して**、ケーキが焦げてしまいました。","vi":"Tôi nấu ăn thất bại, bánh bị cháy mất."},{"jp":"一度**失敗して**も、あきらめないでください。","vi":"Dù thất bại một lần cũng đừng bỏ cuộc."}],
  "253": [{"jp":"姉は大学の試験に**合格しました**。","vi":"Chị tôi đã đỗ kỳ thi đại học."},{"jp":"N4に**合格する**ために、毎日勉強しています。","vi":"Để đỗ N4, ngày nào tôi cũng học."}],
  "254": [{"jp":"忘れ物をしたので、家に**戻りました**。","vi":"Vì quên đồ nên tôi đã quay lại nhà."},{"jp":"部長は3時ごろ会社に**戻ります**。","vi":"Trưởng phòng sẽ quay lại công ty khoảng 3 giờ."}],
  "255": [{"jp":"雨が**やんだ**ら、出かけましょう。","vi":"Mưa tạnh thì chúng ta ra ngoài nhé."},{"jp":"夜になって、やっと雪が**やみました**。","vi":"Đến tối thì tuyết mới ngừng rơi."}],
  "256": [{"jp":"明日は**晴れる**でしょう。","vi":"Ngày mai có lẽ trời sẽ nắng."},{"jp":"空がよく**晴れて**、富士山が見えます。","vi":"Trời quang đãng nên có thể nhìn thấy núi Phú Sĩ."}],
  "257": [{"jp":"午後から空が**曇って**きました。","vi":"Từ chiều trời bắt đầu có mây."},{"jp":"**曇って**いるので、星が見えません。","vi":"Trời nhiều mây nên không thấy sao."}],
  "258": [{"jp":"今日は風が強く**吹いて**います。","vi":"Hôm nay gió thổi mạnh."},{"jp":"窓を開けると、涼しい風が**吹いて**きました。","vi":"Mở cửa sổ ra thì gió mát thổi vào."}],
  "259": [{"jp":"壊れたパソコンが**直りました**。","vi":"Máy tính bị hỏng đã được sửa xong."},{"jp":"薬を飲んだら、風邪が**治りました**。","vi":"Uống thuốc xong thì tôi khỏi cảm."}],
  "260": [{"jp":"雨の日が一週間**続いて**います。","vi":"Mưa kéo dài suốt một tuần."},{"jp":"熱が3日も**続いた**ので、病院へ行きました。","vi":"Sốt kéo dài tận 3 ngày nên tôi đã đi bệnh viện."}],
  "261": [{"jp":"寒かったので、**風邪を引いて**しまいました。","vi":"Vì trời lạnh nên tôi đã bị cảm."},{"jp":"ドアを**引いて**開けてください。","vi":"Hãy kéo cửa để mở."}],
  "262": [{"jp":"ビールを冷蔵庫で**冷やして**おきます。","vi":"Tôi để bia vào tủ lạnh cho lạnh."},{"jp":"頭を**冷やす**と、熱が下がります。","vi":"Chườm lạnh đầu thì sẽ hạ sốt."}],
  "263": [{"jp":"子どもが帰ってこないので、**心配**です。","vi":"Con vẫn chưa về nên tôi lo lắng."},{"jp":"母はいつも私の健康を**心配して**います。","vi":"Mẹ lúc nào cũng lo lắng cho sức khỏe của tôi."}],
  "264": [{"jp":"時間は**十分**ありますから、急がなくてもいいです。","vi":"Thời gian còn đủ nên không cần vội."},{"jp":"毎晩**十分な**睡眠をとることが大切です。","vi":"Ngủ đủ giấc mỗi đêm là điều quan trọng."}],
  "265": [{"jp":"その話は**おかしくて**、みんな笑いました。","vi":"Câu chuyện đó buồn cười quá nên mọi người đều cười."},{"jp":"このパソコンは少し**おかしい**です。動きません。","vi":"Cái máy tính này hơi lạ. Nó không chạy."}],
  "266": [{"jp":"隣の部屋の音楽が**うるさい**です。","vi":"Tiếng nhạc phòng bên cạnh ồn ào quá."},{"jp":"母は勉強しなさいと**うるさく**言います。","vi":"Mẹ cứ nói phiền phức bắt tôi học bài."}],
  "267": [{"jp":"熱いお茶で手に**やけど**をしました。","vi":"Tôi bị bỏng tay vì trà nóng."},{"jp":"アイロンで**やけど**しないように気をつけてください。","vi":"Hãy cẩn thận để không bị bỏng bàn là."}],
  "268": [{"jp":"転んで足に**けが**をしました。","vi":"Tôi bị ngã và bị thương ở chân."},{"jp":"サッカーの試合で**けが**をした選手がいます。","vi":"Có cầu thủ bị thương trong trận bóng đá."}],
  "269": [{"jp":"風邪で**せき**が止まりません。","vi":"Vì bị cảm nên tôi ho không dứt."},{"jp":"**せき**が出るときは、マスクをしてください。","vi":"Khi bị ho, hãy đeo khẩu trang."}],
  "270": [{"jp":"夕方の**空**が赤くなっています。","vi":"Bầu trời chiều đang chuyển sang màu đỏ."},{"jp":"飛行機が**空**を飛んでいます。","vi":"Máy bay đang bay trên bầu trời."}],
  "271": [{"jp":"**太陽**は東から昇ります。","vi":"Mặt trời mọc ở phía đông."},{"jp":"**太陽**の光は植物に大切です。","vi":"Ánh sáng mặt trời quan trọng đối với thực vật."}],
  "272": [{"jp":"田舎では**星**がたくさん見えます。","vi":"Ở quê có thể thấy rất nhiều sao."},{"jp":"夜空に**星**が光っています。","vi":"Những ngôi sao đang lấp lánh trên bầu trời đêm."}],
  "273": [{"jp":"秋の**月**はとてもきれいです。","vi":"Trăng mùa thu rất đẹp."},{"jp":"雲の間から**月**が見えました。","vi":"Mặt trăng ló ra từ giữa những đám mây."}],
  "274": [{"jp":"今日は**風**が冷たいです。","vi":"Hôm nay gió lạnh."},{"jp":"**風**で帽子が飛んでしまいました。","vi":"Mũ bị gió thổi bay mất."}],
  "275": [{"jp":"北海道は日本の**北**にあります。","vi":"Hokkaido nằm ở phía bắc Nhật Bản."},{"jp":"**北**から冷たい風が吹いてきます。","vi":"Gió lạnh thổi đến từ phía bắc."}],
  "276": [{"jp":"沖縄は日本の**南**にあります。","vi":"Okinawa nằm ở phía nam Nhật Bản."},{"jp":"冬は**南**の島へ旅行したいです。","vi":"Mùa đông tôi muốn đi du lịch đến hòn đảo phương nam."}],
  "277": [{"jp":"夕日が**西**の空に沈みます。","vi":"Mặt trời chiều lặn xuống bầu trời phía tây."},{"jp":"駅の**西**側に公園があります。","vi":"Phía tây nhà ga có công viên."}],
  "278": [{"jp":"太陽は**東**から昇ります。","vi":"Mặt trời mọc ở phía đông."},{"jp":"駅の**東**口で会いましょう。","vi":"Hẹn gặp ở cửa đông nhà ga nhé."}],
  "279": [{"jp":"この国では**水道**の水をそのまま飲んでもいいですか。","vi":"Ở nước này có thể uống trực tiếp nước máy không?"},{"jp":"寒い朝、**水道**が凍って水が出ませんでした。","vi":"Buổi sáng lạnh, ống nước máy bị đóng băng nên nước không chảy."}],
  "280": [{"jp":"**今夜**は雨が降るそうです。","vi":"Nghe nói đêm nay trời sẽ mưa."},{"jp":"**今夜**、いっしょに晩ご飯を食べませんか。","vi":"Đêm nay cùng đi ăn tối nhé?"}],
  "281": [{"jp":"**夕方**になると、空が赤くなります。","vi":"Khi chiều tối đến, bầu trời chuyển sang màu đỏ."},{"jp":"毎日**夕方**5時ごろ家に帰ります。","vi":"Hằng ngày tôi về nhà khoảng 5 giờ chiều."}],
  "282": [{"jp":"駅の**前**に本屋があります。","vi":"Trước nhà ga có hiệu sách."},{"jp":"食事の**前**に手を洗いましょう。","vi":"Hãy rửa tay trước bữa ăn."}],
  "283": [{"jp":"昨日は**遅く**まで仕事をしました。","vi":"Hôm qua tôi làm việc đến khuya."},{"jp":"夜**遅く**電話をかけて、すみません。","vi":"Xin lỗi vì đã gọi điện lúc đêm khuya."}],
  "284": [{"jp":"**もしかしたら**、明日は雪が降るかもしれません。","vi":"Biết đâu ngày mai trời sẽ có tuyết."},{"jp":"**もしかしたら**、彼はもう家に帰ったかもしれない。","vi":"Có lẽ anh ấy đã về nhà rồi."}],
  "285": [{"jp":"「風邪をひいたんです。」「**それはいけない**。早く寝なさい。」","vi":"\"Con bị cảm rồi.\" \"Thế thì không tốt. Đi ngủ sớm đi.\""},{"jp":"「足をけがしました。」「**それはいけない**ね。病院へ行った？」","vi":"\"Tôi bị thương ở chân.\" \"Thế thì không ổn rồi. Đã đi bệnh viện chưa?\""}],
  "286": [{"jp":"祖母は90歳ですが、とても**元気**です。","vi":"Bà tôi 90 tuổi nhưng rất khỏe mạnh."},{"jp":"**元気**な赤ちゃんが生まれました。","vi":"Một em bé khỏe mạnh đã chào đời."}],
  "287": [{"jp":"**胃**の調子が悪いので、病院へ行きます。","vi":"Dạ dày không được khỏe nên tôi đi bệnh viện."},{"jp":"辛い物を食べすぎると、**胃**に悪いですよ。","vi":"Ăn quá nhiều đồ cay sẽ không tốt cho dạ dày đâu."}],
  "288": [{"jp":"毎日12時間も仕事をするのは**働きすぎ**ですよ。","vi":"Ngày nào cũng làm 12 tiếng là làm việc quá sức đấy."},{"jp":"**働きすぎ**で体を壊してしまいました。","vi":"Vì làm việc quá sức nên tôi đã bị suy sụp sức khỏe."}],
  "289": [{"jp":"熱があるときは、**無理をしない**でください。","vi":"Khi bị sốt thì đừng cố quá sức."},{"jp":"父は**無理をして**、病気になってしまった。","vi":"Bố tôi cố quá sức nên đã đổ bệnh."}],
  "290": [{"jp":"日曜日は家で**ゆっくりします**。","vi":"Chủ nhật tôi thong thả nghỉ ngơi ở nhà."},{"jp":"どうぞ**ゆっくりして**いってください。","vi":"Xin cứ thong thả ở lại chơi nhé."}],
  "291": [{"jp":"毎朝、雑誌で**星占い**を読みます。","vi":"Sáng nào tôi cũng đọc mục bói sao trên tạp chí."},{"jp":"**星占い**によると、今日はいい日だそうです。","vi":"Theo bói sao thì hôm nay là một ngày tốt."}],
  "292": [{"jp":"わたしは5月生まれなので、**牡牛座**です。","vi":"Tôi sinh tháng 5 nên thuộc cung Kim Ngưu."},{"jp":"**牡牛座**の人は今月恋愛運がいいそうです。","vi":"Nghe nói tháng này người cung Kim Ngưu gặp may trong tình yêu."}],
  "293": [{"jp":"財布をなくして、**困って**います。","vi":"Tôi bị mất ví nên đang rất khó xử."},{"jp":"外国で言葉がわからなくて**困りました**。","vi":"Ở nước ngoài không hiểu ngôn ngữ nên tôi đã gặp rắc rối."}],
  "294": [{"jp":"**宝くじ**を10枚買いました。","vi":"Tôi đã mua 10 tờ xổ số."},{"jp":"**宝くじ**で1億円が当たったら、何をしますか。","vi":"Nếu trúng xổ số 100 triệu yên thì bạn sẽ làm gì?"}],
  "295": [{"jp":"宝くじが**当たりました**！","vi":"Tôi trúng xổ số rồi!"},{"jp":"抽選で旅行が**当たった**そうです。","vi":"Nghe nói anh ấy bốc thăm trúng một chuyến du lịch."}],
  "296": [{"jp":"**健康**のために、毎朝走っています。","vi":"Vì sức khỏe, sáng nào tôi cũng chạy bộ."},{"jp":"タバコは**健康**に悪いです。","vi":"Thuốc lá có hại cho sức khỏe."}],
  "297": [{"jp":"この映画は**恋愛**の話です。","vi":"Bộ phim này là câu chuyện tình yêu."},{"jp":"今は**恋愛**より仕事のほうが大切です。","vi":"Bây giờ công việc quan trọng hơn tình yêu."}],
  "298": [{"jp":"週末は**恋人**とデートします。","vi":"Cuối tuần tôi hẹn hò với người yêu."},{"jp":"彼には優しい**恋人**がいます。","vi":"Anh ấy có một người yêu dịu dàng."}],
  "299": [{"jp":"彼は**お金持ち**なので、大きい家に住んでいます。","vi":"Anh ấy giàu có nên sống trong một căn nhà lớn."},{"jp":"いつか**お金持ち**になりたいです。","vi":"Tôi muốn một ngày nào đó trở thành người giàu."}],
  "300": [{"jp":"泥棒は警察を見て**逃げました**。","vi":"Tên trộm thấy cảnh sát liền bỏ chạy."},{"jp":"火事だ！早く**逃げて**！","vi":"Cháy rồi! Chạy nhanh lên!"}],
  "301": [{"jp":"図書館で**騒いで**はいけません。","vi":"Không được làm ồn trong thư viện."},{"jp":"隣の部屋の学生たちが夜中まで**騒いで**いた。","vi":"Đám sinh viên phòng bên làm ồn đến tận nửa đêm."}],
  "302": [{"jp":"雨が強いので、山登りは**諦めました**。","vi":"Mưa to quá nên tôi đã từ bỏ việc leo núi."},{"jp":"最後まで**諦めないで**ください。","vi":"Đừng bỏ cuộc cho đến phút cuối."}],
  "303": [{"jp":"公園で子どもとボールを**投げて**遊びました。","vi":"Tôi chơi ném bóng với con ở công viên."},{"jp":"ゴミを川に**投げないで**ください。","vi":"Đừng ném rác xuống sông."}],
  "304": [{"jp":"約束は**守って**ください。","vi":"Hãy giữ lời hứa."},{"jp":"親は子どもを**守ります**。","vi":"Cha mẹ bảo vệ con cái."}],
  "305": [{"jp":"テレビの音が小さいので、ボリュームを**上げて**ください。","vi":"Tiếng tivi nhỏ quá, hãy tăng âm lượng lên."},{"jp":"来月から電車の料金を**上げる**そうです。","vi":"Nghe nói từ tháng sau sẽ tăng giá vé tàu."}],
  "306": [{"jp":"暑いので、エアコンの温度を**下げました**。","vi":"Vì nóng nên tôi đã hạ nhiệt độ điều hòa."},{"jp":"店長は客に頭を**下げて**謝った。","vi":"Cửa hàng trưởng cúi đầu xin lỗi khách."}],
  "307": [{"jp":"田中さんに、会議は3時からだと**伝えて**ください。","vi":"Hãy nhắn với anh Tanaka là cuộc họp bắt đầu từ 3 giờ."},{"jp":"自分の気持ちを日本語で**伝える**のは難しいです。","vi":"Truyền đạt cảm xúc của mình bằng tiếng Nhật thật khó."}],
  "308": [{"jp":"車に**注意して**道を渡ってください。","vi":"Hãy chú ý xe cộ khi qua đường."},{"jp":"先生は遅刻した学生に**注意しました**。","vi":"Thầy giáo đã nhắc nhở học sinh đi muộn."}],
  "309": [{"jp":"寝る前に眼鏡を**外します**。","vi":"Trước khi ngủ tôi tháo kính ra."},{"jp":"部長は今、席を**外して**おります。","vi":"Trưởng phòng hiện đang không có ở chỗ ngồi."}],
  "310": [{"jp":"ここでタバコを吸っては**駄目**です。","vi":"Không được hút thuốc ở đây."},{"jp":"一生懸命練習したが、試合は**駄目**だった。","vi":"Đã luyện tập chăm chỉ nhưng trận đấu vẫn không thành."}],
  "311": [{"jp":"すみません、この**席**は空いていますか。","vi":"Xin lỗi, chỗ ngồi này còn trống không?"},{"jp":"電車でお年寄りに**席**を譲りました。","vi":"Tôi đã nhường ghế cho người già trên tàu."}],
  "312": [{"jp":"**洗濯機**が壊れたので、手で洗いました。","vi":"Máy giặt hỏng nên tôi đã giặt tay."},{"jp":"汚れた服を**洗濯機**に入れてください。","vi":"Hãy cho quần áo bẩn vào máy giặt."}],
  "313": [{"jp":"学校の**規則**を守りましょう。","vi":"Hãy tuân thủ nội quy của trường."},{"jp":"この寮には夜11時までに帰るという**規則**があります。","vi":"Ký túc xá này có quy định phải về trước 11 giờ đêm."}],
  "314": [{"jp":"このトイレは今**使用禁止**です。","vi":"Nhà vệ sinh này hiện đang cấm sử dụng."},{"jp":"試験中、辞書は**使用禁止**です。","vi":"Trong giờ thi cấm sử dụng từ điển."}],
  "315": [{"jp":"工事中なので、ここは**立入禁止**です。","vi":"Đang thi công nên ở đây cấm vào."},{"jp":"「**立入禁止**」と書いてある場所に入ってはいけません。","vi":"Không được vào những nơi có ghi \"Cấm vào\"."}],
  "316": [{"jp":"駅の**入り口**で待っています。","vi":"Tôi đang đợi ở cửa vào nhà ga."},{"jp":"美術館の**入り口**はどこですか。","vi":"Cửa vào bảo tàng mỹ thuật ở đâu ạ?"}],
  "317": [{"jp":"駅の東**出口**で会いましょう。","vi":"Hẹn gặp nhau ở cửa ra phía đông nhà ga nhé."},{"jp":"**出口**はあちらです。","vi":"Cửa ra ở đằng kia."}],
  "318": [{"jp":"火事のときは、**非常口**から逃げてください。","vi":"Khi có hỏa hoạn, hãy thoát ra bằng cửa thoát hiểm."},{"jp":"ホテルに着いたら、まず**非常口**の場所を確認します。","vi":"Đến khách sạn, việc đầu tiên tôi làm là kiểm tra vị trí cửa thoát hiểm."}],
  "319": [{"jp":"この博物館は**無料**で入れます。","vi":"Bảo tàng này vào cửa miễn phí."},{"jp":"6歳以下の子どもは**無料**です。","vi":"Trẻ em từ 6 tuổi trở xuống được miễn phí."}],
  "320": [{"jp":"店の前に「**本日休業**」と書いてありました。","vi":"Trước cửa hàng có ghi \"Hôm nay nghỉ bán\"."},{"jp":"**本日休業**なので、明日また来てください。","vi":"Hôm nay nghỉ bán, xin mời ngày mai quay lại."}],
  "321": [{"jp":"ドアに「**営業中**」の札がかかっています。","vi":"Trên cửa có treo biển \"Đang mở cửa\"."},{"jp":"まだ**営業中**ですから、入れますよ。","vi":"Vẫn đang mở cửa nên vào được đấy."}],
  "322": [{"jp":"トイレは今**使用中**です。","vi":"Nhà vệ sinh hiện đang có người sử dụng."},{"jp":"この会議室は3時まで**使用中**です。","vi":"Phòng họp này đang được sử dụng đến 3 giờ."}],
  "323": [{"jp":"ここに車を止めると**駐車違反**になります。","vi":"Đỗ xe ở đây sẽ bị coi là đỗ xe trái phép."},{"jp":"**駐車違反**で罰金を払いました。","vi":"Tôi đã nộp phạt vì đỗ xe trái phép."}],
  "324": [{"jp":"1時間**以内**に戻ります。","vi":"Tôi sẽ quay lại trong vòng 1 tiếng."},{"jp":"作文は800字**以内**で書いてください。","vi":"Hãy viết bài văn trong vòng 800 chữ."}],
  "325": [{"jp":"財布を落としたので、**警察**に行きました。","vi":"Vì đánh rơi ví nên tôi đã đến đồn cảnh sát."},{"jp":"**警察**が泥棒を捕まえました。","vi":"Cảnh sát đã bắt được tên trộm."}],
  "326": [{"jp":"スピード違反で**罰金**を払いました。","vi":"Tôi đã nộp tiền phạt vì chạy quá tốc độ."},{"jp":"ここでゴミを捨てると、**罰金**を取られます。","vi":"Vứt rác ở đây sẽ bị phạt tiền."}],
  "327": [{"jp":"友達の結婚式にお祝いの**電報**を送りました。","vi":"Tôi đã gửi điện báo chúc mừng đến đám cưới của bạn."},{"jp":"昔は急ぐとき、**電報**を打ちました。","vi":"Ngày xưa khi có việc gấp, người ta gửi điện báo."}],
  "328": [{"jp":"駅の前には大勢の**人々**が集まっていました。","vi":"Trước nhà ga có rất nhiều người tụ tập."},{"jp":"この町の**人々**はとても親切です。","vi":"Người dân thị trấn này rất tốt bụng."}],
  "329": [{"jp":"**急用**ができたので、先に帰ります。","vi":"Tôi có việc gấp nên xin về trước."},{"jp":"父は**急用**で大阪へ行きました。","vi":"Bố tôi đi Osaka vì có việc gấp."}],
  "330": [{"jp":"母が病気なので、兄に電報を**打ちました**。","vi":"Mẹ bị ốm nên tôi đã gửi điện báo cho anh trai."},{"jp":"転んで頭を**打って**しまった。","vi":"Tôi bị ngã và đập đầu."}],
  "331": [{"jp":"**電報代**はいくらですか。","vi":"Tiền điện báo là bao nhiêu?"},{"jp":"字が多いと、**電報代**が高くなります。","vi":"Nhiều chữ thì tiền điện báo sẽ đắt hơn."}],
  "332": [{"jp":"**できるだけ**早く来てください。","vi":"Hãy đến càng sớm càng tốt."},{"jp":"毎日**できるだけ**野菜を食べるようにしています。","vi":"Hằng ngày tôi cố gắng ăn rau nhiều nhất có thể."}],
  "333": [{"jp":"髪を**短く**切りました。","vi":"Tôi đã cắt tóc ngắn."},{"jp":"電報の文は**短く**書いてください。","vi":"Hãy viết nội dung điện báo thật ngắn gọn."}],
  "334": [{"jp":"私は果物が好きです。**例えば**、りんごやみかんです。","vi":"Tôi thích trái cây. Ví dụ như táo và quýt."},{"jp":"スポーツ、**例えば**テニスやサッカーをするのが好きです。","vi":"Tôi thích chơi thể thao, ví dụ như tennis hay bóng đá."}],
  "335": [{"jp":"祖父が**危篤**だと聞いて、すぐ病院へ行きました。","vi":"Nghe tin ông nguy kịch, tôi lập tức đến bệnh viện."},{"jp":"母が**危篤**なので、国へ帰らなければなりません。","vi":"Mẹ tôi đang nguy kịch nên tôi phải về nước."}],
  "336": [{"jp":"彼は**重い病気**で入院しています。","vi":"Anh ấy đang nằm viện vì bệnh nặng."},{"jp":"**重い病気**になる前に、検査を受けましょう。","vi":"Hãy đi kiểm tra trước khi mắc bệnh nặng."}],
  "337": [{"jp":"**明日**の天気は晴れでしょう。","vi":"Thời tiết ngày mai có lẽ sẽ nắng."},{"jp":"会議は**明日**の午前10時からです。","vi":"Cuộc họp bắt đầu lúc 10 giờ sáng ngày mai."}],
  "338": [{"jp":"友達の家に行きましたが、**留守**でした。","vi":"Tôi đến nhà bạn nhưng bạn vắng nhà."},{"jp":"**留守**の間に荷物が届いていました。","vi":"Trong lúc tôi vắng nhà thì có bưu kiện được gửi đến."}],
  "339": [{"jp":"両親が出かけたので、私が**留守番**をしました。","vi":"Bố mẹ đi ra ngoài nên tôi ở nhà trông nhà."},{"jp":"子どもに**留守番**を頼んで、買い物に行きました。","vi":"Tôi nhờ con trông nhà rồi đi mua sắm."}],
  "340": [{"jp":"友達の結婚の**お祝い**に時計をあげました。","vi":"Tôi tặng đồng hồ làm quà mừng đám cưới của bạn."},{"jp":"合格の**お祝い**に、みんなで食事をしました。","vi":"Để mừng thi đỗ, mọi người cùng nhau đi ăn."}],
  "341": [{"jp":"祖父は去年**亡くなりました**。","vi":"Ông tôi đã mất vào năm ngoái."},{"jp":"有名な歌手が**亡くなった**というニュースを見た。","vi":"Tôi đã xem tin một ca sĩ nổi tiếng qua đời."}],
  "342": [{"jp":"母が亡くなって、深い**悲しみ**を感じた。","vi":"Mẹ mất, tôi cảm thấy nỗi đau buồn sâu sắc."},{"jp":"音楽は人の**悲しみ**を少し軽くしてくれます。","vi":"Âm nhạc giúp vơi bớt nỗi buồn của con người."}],
  "343": [{"jp":"毎日会社へ行くのに地下鉄を**利用して**います。","vi":"Hằng ngày tôi dùng tàu điện ngầm để đi làm."},{"jp":"夏休みを**利用して**、運転免許を取りました。","vi":"Tôi tận dụng kỳ nghỉ hè để lấy bằng lái xe."}],
  "344": [{"jp":"毎晩寝る前に歯を**磨きます**。","vi":"Tối nào trước khi ngủ tôi cũng đánh răng."},{"jp":"父は日曜日に靴を**磨いて**います。","vi":"Bố tôi đánh giày vào ngày Chủ nhật."}],
  "345": [{"jp":"買ってきた本棚を自分で**組み立てました**。","vi":"Tôi tự lắp ráp cái giá sách mới mua về."},{"jp":"説明書を見ながら、おもちゃを**組み立てて**ください。","vi":"Hãy vừa xem sách hướng dẫn vừa lắp ráp đồ chơi."}],
  "346": [{"jp":"紙を半分に**折って**ください。","vi":"Hãy gấp tờ giấy làm đôi."},{"jp":"スキーで転んで、足の骨を**折りました**。","vi":"Tôi ngã khi trượt tuyết và bị gãy xương chân."}],
  "347": [{"jp":"お刺身にしょうゆを**つけて**食べます。","vi":"Tôi chấm sashimi với xì dầu rồi ăn."},{"jp":"パンにジャムを**つけて**食べるのが好きです。","vi":"Tôi thích phết mứt lên bánh mì để ăn."}],
  "348": [{"jp":"なくした鍵が**見つかりました**。","vi":"Chiếc chìa khóa bị mất đã được tìm thấy."},{"jp":"新しいアパートがなかなか**見つからない**。","vi":"Mãi mà không tìm được căn hộ mới."}],
  "349": [{"jp":"わからないことがあったら、先生に**質問して**ください。","vi":"Nếu có điều gì không hiểu, hãy hỏi thầy cô."},{"jp":"会議で新製品について**質問しました**。","vi":"Tôi đã đặt câu hỏi về sản phẩm mới trong cuộc họp."}],
  "350": [{"jp":"この**細い**道をまっすぐ行くと駅です。","vi":"Đi thẳng con đường hẹp này là đến ga."},{"jp":"彼女は指が**細くて**長いです。","vi":"Cô ấy có ngón tay thon dài."}],
  "351": [{"jp":"この**太い**ペンで名前を書いてください。","vi":"Hãy viết tên bằng cây bút nét to này."},{"jp":"公園に**太い**木があります。","vi":"Trong công viên có một cái cây to."}],
  "352": [{"jp":"夏になると、町で**盆踊り**があります。","vi":"Đến mùa hè, trong thị trấn có lễ múa Obon."},{"jp":"浴衣を着て**盆踊り**に参加しました。","vi":"Tôi mặc yukata tham gia múa Obon."}],
  "353": [{"jp":"新しい部屋のために**家具**を買いました。","vi":"Tôi đã mua đồ nội thất cho căn phòng mới."},{"jp":"この部屋には**家具**が付いています。","vi":"Phòng này có sẵn đồ nội thất."}],
  "354": [{"jp":"使う前に、**説明書**をよく読んでください。","vi":"Trước khi dùng, hãy đọc kỹ sách hướng dẫn."},{"jp":"この**説明書**は英語で書いてあります。","vi":"Sách hướng dẫn này được viết bằng tiếng Anh."}],
  "355": [{"jp":"この**図**を見てください。","vi":"Hãy nhìn sơ đồ này."},{"jp":"先生は**図**を描いて説明しました。","vi":"Thầy giáo vẽ hình để giải thích."}],
  "356": [{"jp":"大切なところに**線**を引いてください。","vi":"Hãy gạch dưới những chỗ quan trọng."},{"jp":"電車が来ますから、黄色い**線**の内側に下がってください。","vi":"Tàu sắp đến, xin lùi vào phía trong vạch vàng."}],
  "357": [{"jp":"**矢印**の方向に進んでください。","vi":"Hãy đi theo hướng mũi tên."},{"jp":"地図に赤い**矢印**が書いてあります。","vi":"Trên bản đồ có vẽ mũi tên màu đỏ."}],
  "358": [{"jp":"父は**黒**の背広を着ています。","vi":"Bố tôi mặc bộ com-lê màu đen."},{"jp":"書類は**黒**のペンで書いてください。","vi":"Hãy viết hồ sơ bằng bút màu đen."}],
  "359": [{"jp":"**白**のシャツを買いました。","vi":"Tôi đã mua một chiếc áo sơ mi trắng."},{"jp":"部屋の壁を**白**に塗りました。","vi":"Tôi đã sơn tường phòng màu trắng."}],
  "360": [{"jp":"信号が**赤**のときは止まってください。","vi":"Khi đèn tín hiệu màu đỏ thì hãy dừng lại."},{"jp":"大切なところは**赤**で書きましょう。","vi":"Những chỗ quan trọng hãy viết bằng màu đỏ."}],
  "361": [{"jp":"信号が**青**になったら渡りましょう。","vi":"Khi đèn chuyển xanh thì hãy qua đường."},{"jp":"**青**のセーターと赤のセーターと、どちらがいいですか。","vi":"Áo len xanh và áo len đỏ, cái nào đẹp hơn?"}],
  "362": [{"jp":"学校の制服は**紺**です。","vi":"Đồng phục của trường màu xanh tím than."},{"jp":"**紺**のスーツを着て面接に行きました。","vi":"Tôi mặc bộ vest xanh tím than đi phỏng vấn."}],
  "363": [{"jp":"庭に**黄色**の花が咲いています。","vi":"Trong vườn có hoa màu vàng đang nở."},{"jp":"バナナは**黄色**です。","vi":"Chuối có màu vàng."}],
  "364": [{"jp":"**茶色**の靴を買いました。","vi":"Tôi đã mua đôi giày màu nâu."},{"jp":"秋の終わりには、葉が**茶色**になって落ちます。","vi":"Cuối thu, lá chuyển sang màu nâu rồi rụng."}],
  "365": [{"jp":"**昨夜**は遅くまで勉強しました。","vi":"Đêm qua tôi học đến khuya."},{"jp":"**昨夜**、大きな地震がありました。","vi":"Đêm qua có một trận động đất lớn."}],
  "366": [{"jp":"**さっき**田中さんから電話がありました。","vi":"Vừa rồi có điện thoại của anh Tanaka."},{"jp":"**さっき**食べたばかりなので、まだおなかがいっぱいです。","vi":"Vừa mới ăn xong nên tôi vẫn còn no."}],
  "367": [{"jp":"日本の**茶道**に興味があります。","vi":"Tôi có hứng thú với trà đạo Nhật Bản."},{"jp":"母は週に1回**茶道**を習っています。","vi":"Mẹ tôi học trà đạo mỗi tuần một lần."}],
  "368": [{"jp":"先生が**お茶を点てて**くださいました。","vi":"Cô giáo đã pha trà cho chúng tôi."},{"jp":"茶道の教室で、**お茶を点てる**練習をしました。","vi":"Ở lớp trà đạo, tôi đã luyện tập pha trà."}],
  "369": [{"jp":"すみませんが、私は**先に**帰ります。","vi":"Xin lỗi, tôi xin về trước."},{"jp":"**先に**手を洗ってから、ご飯を食べましょう。","vi":"Hãy rửa tay trước rồi mới ăn cơm."}],
  "370": [{"jp":"棚の上に荷物を**載せて**ください。","vi":"Hãy đặt hành lý lên trên giá."},{"jp":"ご飯の上に卵を**載せて**食べます。","vi":"Tôi đặt trứng lên trên cơm rồi ăn."}],
  "371": [{"jp":"この薬はとても**苦い**です。","vi":"Thuốc này rất đắng."},{"jp":"砂糖を入れないコーヒーは**苦くて**飲めません。","vi":"Cà phê không đường đắng quá, tôi không uống được."}],
  "372": [{"jp":"昼ご飯に**おやこどんぶり**を作りました。","vi":"Tôi đã làm món oyakodon cho bữa trưa."},{"jp":"この店の**おやこどんぶり**は安くておいしいです。","vi":"Món oyakodon của quán này rẻ mà ngon."}],
  "373": [{"jp":"カレーの**材料**を買いに行きます。","vi":"Tôi đi mua nguyên liệu nấu cà ri."},{"jp":"この料理の**材料**は何ですか。","vi":"Nguyên liệu của món ăn này là gì?"}],
  "374": [{"jp":"4人**分**の材料を用意してください。","vi":"Hãy chuẩn bị nguyên liệu cho 4 người."},{"jp":"台風が来るので、三日**分**の食べ物を買っておきました。","vi":"Vì bão sắp đến nên tôi đã mua sẵn đồ ăn đủ cho 3 ngày."}],
  "375": [{"jp":"**鳥肉**と野菜を一緒に炒めます。","vi":"Xào thịt gà cùng với rau."},{"jp":"私は牛肉より**鳥肉**のほうが好きです。","vi":"Tôi thích thịt gà hơn thịt bò."}],
  "376": [{"jp":"スーパーでりんごを3**個**買いました。","vi":"Tôi đã mua 3 quả táo ở siêu thị."},{"jp":"この料理には卵を2**個**使います。","vi":"Món này dùng 2 quả trứng."}],
  "377": [{"jp":"**たまねぎ**を細く切ってください。","vi":"Hãy thái hành tây thành sợi nhỏ."},{"jp":"カレーに**たまねぎ**とにんじんを入れます。","vi":"Cho hành tây và cà rốt vào cà ri."}],
  "378": [{"jp":"しょうゆやみそは日本の**調味料**です。","vi":"Xì dầu và miso là gia vị của Nhật Bản."},{"jp":"最後に**調味料**を入れて、味を見ます。","vi":"Cuối cùng cho gia vị vào rồi nếm thử."}],
  "379": [{"jp":"**鍋**にお湯を沸かしてください。","vi":"Hãy đun sôi nước trong nồi."},{"jp":"冬は家族で**鍋**を囲んで食べます。","vi":"Mùa đông cả nhà quây quần ăn lẩu."}],
  "380": [{"jp":"鍋に水を入れて、**火にかけます**。","vi":"Cho nước vào nồi rồi bắc lên bếp."},{"jp":"やかんを**火にかけた**まま出かけてはいけません。","vi":"Không được để ấm nước trên bếp mà ra ngoài."}],
  "381": [{"jp":"野菜を**煮て**スープを作ります。","vi":"Ninh rau để nấu súp."},{"jp":"魚をしょうゆと砂糖で**煮ました**。","vi":"Tôi đã kho cá với xì dầu và đường."}],
  "382": [{"jp":"じゃがいもが**煮えたら**、火を止めてください。","vi":"Khi khoai tây chín thì hãy tắt bếp."},{"jp":"肉がまだ**煮えて**いません。","vi":"Thịt vẫn chưa chín."}],
  "383": [{"jp":"大きな**丼**にご飯をたくさん入れます。","vi":"Cho thật nhiều cơm vào bát tô lớn."},{"jp":"この店の**丼**はご飯の量が多いです。","vi":"Món cơm tô của quán này nhiều cơm."}],
  "384": [{"jp":"春になると、桜が**咲きます**。","vi":"Đến mùa xuân, hoa anh đào nở."},{"jp":"庭に赤い花が**咲いて**います。","vi":"Trong vườn có hoa đỏ đang nở."}],
  "385": [{"jp":"秋になって、葉の色が**変わりました**。","vi":"Mùa thu đến, màu lá đã thay đổi."},{"jp":"信号が赤に**変わった**ので、止まりました。","vi":"Đèn tín hiệu đổi sang đỏ nên tôi dừng lại."}],
  "386": [{"jp":"急に雨が降ってきて、傘がなくて**困りました**。","vi":"Trời đột nhiên mưa mà không có ô nên tôi rất khó xử."},{"jp":"隣の人がうるさくて**困って**います。","vi":"Người hàng xóm ồn ào làm tôi rất phiền."}],
  "387": [{"jp":"地図の駅に赤いペンで印を**付けました**。","vi":"Tôi đánh dấu nhà ga trên bản đồ bằng bút đỏ."},{"jp":"参加する人は、名前の横にチェックを**付けて**ください。","vi":"Ai tham gia thì hãy đánh dấu cạnh tên mình."}],
  "388": [{"jp":"道で財布を**拾いました**。","vi":"Tôi nhặt được một cái ví trên đường."},{"jp":"みんなで公園のゴミを**拾い**ましょう。","vi":"Mọi người cùng nhặt rác trong công viên nào."}],
  "389": [{"jp":"夜中に電話が**かかって**きました。","vi":"Nửa đêm có điện thoại gọi đến."},{"jp":"会議中に母から電話が**かかった**。","vi":"Trong lúc họp thì mẹ gọi điện đến."}],
  "390": [{"jp":"新しい仕事は前の仕事より**楽**です。","vi":"Công việc mới nhàn hơn công việc cũ."},{"jp":"薬を飲んだら、体が**楽**になりました。","vi":"Uống thuốc xong, người thấy dễ chịu hơn."}],
  "391": [{"jp":"**正しい**答えを選んでください。","vi":"Hãy chọn câu trả lời đúng."},{"jp":"彼の言ったことは**正しかった**。","vi":"Điều anh ấy nói là chính xác."}],
  "392": [{"jp":"沖縄で雪が降るのは**珍しい**です。","vi":"Tuyết rơi ở Okinawa là chuyện hiếm."},{"jp":"動物園で**珍しい**鳥を見ました。","vi":"Tôi đã thấy một loài chim hiếm ở sở thú."}],
  "393": [{"jp":"川の**向こう**に小さな村があります。","vi":"Bên kia sông có một ngôi làng nhỏ."},{"jp":"道の**向こう**から友達が手を振っていました。","vi":"Bạn tôi vẫy tay từ phía bên kia đường."}],
  "394": [{"jp":"沖縄にはたくさんの**島**があります。","vi":"Okinawa có rất nhiều đảo."},{"jp":"船で**島**へ渡りました。","vi":"Tôi đi thuyền sang đảo."}],
  "395": [{"jp":"祖父母は山の中の**村**に住んでいます。","vi":"Ông bà tôi sống ở một ngôi làng trong núi."},{"jp":"この**村**には店が1軒しかありません。","vi":"Làng này chỉ có một cửa hàng."}],
  "396": [{"jp":"**港**にたくさんの船が止まっています。","vi":"Có rất nhiều tàu thuyền đang đậu ở cảng."},{"jp":"横浜は大きな**港**がある町です。","vi":"Yokohama là thành phố có cảng lớn."}],
  "397": [{"jp":"**近所**に大きなスーパーができました。","vi":"Gần nhà mới mở một siêu thị lớn."},{"jp":"引っ越したら、**近所**の人にあいさつしましょう。","vi":"Chuyển nhà xong hãy chào hỏi hàng xóm."}],
  "398": [{"jp":"デパートの**屋上**から花火を見ました。","vi":"Tôi đã xem pháo hoa từ sân thượng của trung tâm thương mại."},{"jp":"**屋上**に上がると、町がよく見えます。","vi":"Lên sân thượng thì có thể nhìn rõ thành phố."}],
  "399": [{"jp":"夏休みに**海外**旅行に行きたいです。","vi":"Kỳ nghỉ hè tôi muốn đi du lịch nước ngoài."},{"jp":"兄は**海外**で働いています。","vi":"Anh trai tôi đang làm việc ở nước ngoài."}],
  "400": [{"jp":"週末は友達と**山登り**に行きます。","vi":"Cuối tuần tôi đi leo núi với bạn."},{"jp":"**山登り**のときは、水をたくさん持って行きましょう。","vi":"Khi leo núi hãy mang theo nhiều nước."}],
  "401": [{"jp":"日本人と話す**機会**があまりありません。","vi":"Tôi ít có cơ hội nói chuyện với người Nhật."},{"jp":"いい**機会**ですから、一緒に行きましょう。","vi":"Đây là cơ hội tốt, cùng đi nhé."}],
  "402": [{"jp":"ここで写真を撮るには**許可**が必要です。","vi":"Muốn chụp ảnh ở đây cần phải có giấy phép."},{"jp":"先生の**許可**をもらって、早く帰りました。","vi":"Được thầy cho phép, tôi về sớm."}],
  "403": [{"jp":"正しい答えに**丸**をつけてください。","vi":"Hãy khoanh tròn câu trả lời đúng."},{"jp":"紙に大きな**丸**を描きました。","vi":"Tôi đã vẽ một vòng tròn lớn lên giấy."}],
  "404": [{"jp":"この機械の**操作**は簡単です。","vi":"Thao tác của máy này rất đơn giản."},{"jp":"パソコンの**操作**を間違えて、データが消えてしまった。","vi":"Tôi thao tác nhầm trên máy tính nên dữ liệu bị mất."}],
  "405": [{"jp":"日本語が上手になるいい**方法**を教えてください。","vi":"Hãy chỉ cho tôi phương pháp tốt để giỏi tiếng Nhật."},{"jp":"この**方法**なら、早くできます。","vi":"Nếu dùng phương pháp này thì sẽ làm xong nhanh."}],
  "406": [{"jp":"このホテルは**設備**がいいです。","vi":"Khách sạn này có thiết bị tốt."},{"jp":"新しい病院には最新の**設備**があります。","vi":"Bệnh viện mới có thiết bị hiện đại nhất."}],
  "407": [{"jp":"靴の**紐**がほどけていますよ。","vi":"Dây giày của bạn bị tuột kìa."},{"jp":"古い新聞を**紐**で縛って出します。","vi":"Buộc báo cũ bằng dây rồi đem bỏ."}],
  "408": [{"jp":"鍋に**蓋**をして、10分煮ます。","vi":"Đậy nắp nồi lại và ninh 10 phút."},{"jp":"このびんの**蓋**が固くて開きません。","vi":"Nắp chai này chặt quá, không mở được."}],
  "409": [{"jp":"秋になると、木の**葉**が赤くなります。","vi":"Đến mùa thu, lá cây chuyển sang màu đỏ."},{"jp":"庭に落ちた**葉**を集めました。","vi":"Tôi đã gom lá rụng trong vườn."}],
  "410": [{"jp":"この**曲**を聞くと、元気になります。","vi":"Nghe bản nhạc này tôi thấy phấn chấn."},{"jp":"彼はピアノで好きな**曲**を弾いてくれた。","vi":"Anh ấy đã chơi bản nhạc tôi thích bằng đàn piano."}],
  "411": [{"jp":"来週の旅行がとても**楽しみ**です。","vi":"Tôi rất mong đợi chuyến du lịch tuần sau."},{"jp":"寝る前に本を読むのが私の**楽しみ**です。","vi":"Đọc sách trước khi ngủ là niềm vui của tôi."}],
  "412": [{"jp":"**もっと**ゆっくり話してください。","vi":"Hãy nói chậm hơn nữa."},{"jp":"日本語を**もっと**勉強したいです。","vi":"Tôi muốn học tiếng Nhật nhiều hơn nữa."}],
  "413": [{"jp":"**初めに**、自己紹介をしてください。","vi":"Trước hết, hãy tự giới thiệu."},{"jp":"**初めに**材料を切って、それから炒めます。","vi":"Đầu tiên thái nguyên liệu, sau đó xào."}],
  "414": [{"jp":"「明日は忙しいんです。」「**それなら**、明後日はどうですか。」","vi":"\"Mai tôi bận.\" \"Vậy thì ngày kia thì sao?\""},{"jp":"「頭が痛いんです。」「**それなら**、早く帰ったほうがいいですよ。」","vi":"\"Tôi bị đau đầu.\" \"Vậy thì bạn nên về sớm đi.\""}],
  "415": [{"jp":"**夜行バス**で東京から大阪へ行きました。","vi":"Tôi đi từ Tokyo đến Osaka bằng xe buýt đêm."},{"jp":"**夜行バス**は安いですが、よく眠れません。","vi":"Xe buýt đêm rẻ nhưng không ngủ ngon được."}],
  "416": [{"jp":"**旅行社**で飛行機の切符を予約しました。","vi":"Tôi đã đặt vé máy bay ở công ty du lịch."},{"jp":"姉は**旅行社**で働いています。","vi":"Chị tôi làm việc ở công ty du lịch."}],
  "417": [{"jp":"もっと**詳しく**説明してください。","vi":"Hãy giải thích chi tiết hơn nữa."},{"jp":"彼は日本の歴史に**詳しい**です。","vi":"Anh ấy am hiểu tường tận lịch sử Nhật Bản."}],
  "418": [{"jp":"冬休みに家族で**スキー場**へ行きました。","vi":"Kỳ nghỉ đông tôi đã cùng gia đình đi đến bãi trượt tuyết."},{"jp":"この**スキー場**は雪が多くて、とても人気があります。","vi":"Bãi trượt tuyết này nhiều tuyết nên rất được ưa chuộng."}],
  "419": [{"jp":"「**朱**に交われば赤くなる」という言葉があります。","vi":"Có câu “gần mực thì đen” (hòa vào màu đỏ son thì sẽ thành đỏ)."},{"jp":"神社の鳥居は**朱**色に塗られています。","vi":"Cổng torii của đền thần đạo được sơn màu đỏ son."}],
  "420": [{"jp":"悪い友達と**交わる**と、自分も悪くなりますよ。","vi":"Giao du với bạn xấu thì bản thân cũng sẽ trở nên xấu đấy."},{"jp":"留学して、いろいろな国の人と**交わる**ことができました。","vi":"Đi du học, tôi đã có thể giao lưu với người từ nhiều nước."}],
  "421": [{"jp":"「猿も木から落ちる」は日本の**諺**です。","vi":"“Khỉ cũng có lúc rơi từ trên cây” là một câu tục ngữ của Nhật."},{"jp":"祖母はよく**諺**を使って話します。","vi":"Bà tôi hay dùng tục ngữ khi nói chuyện."}],
  "422": [{"jp":"兄弟は**仲良くしなさい**と母に言われました。","vi":"Mẹ bảo anh em phải hòa thuận với nhau."},{"jp":"新しいクラスの友達と**仲良くして**います。","vi":"Tôi đang chơi thân với các bạn trong lớp mới."}],
  "423": [{"jp":"旅行にはパスポートが**必要**です。","vi":"Đi du lịch thì cần hộ chiếu."},{"jp":"これは仕事に**必要な**書類です。","vi":"Đây là giấy tờ cần thiết cho công việc."}],
  "424": [{"jp":"昨日注文した本が**届きました**。","vi":"Cuốn sách tôi đặt hôm qua đã được giao đến."},{"jp":"母からの手紙がまだ**届いて**いません。","vi":"Thư của mẹ vẫn chưa đến."}],
  "425": [{"jp":"来週、友達の結婚式に**出ます**。","vi":"Tuần sau tôi sẽ dự đám cưới của bạn."},{"jp":"弟はサッカーの試合に**出る**ために毎日練習しています。","vi":"Em trai tôi luyện tập mỗi ngày để được tham gia trận đấu bóng đá."}],
  "426": [{"jp":"毎日パソコンで文章を**打って**います。","vi":"Hằng ngày tôi đánh văn bản trên máy tính."},{"jp":"彼はキーボードを**打つ**のがとても速いです。","vi":"Anh ấy gõ bàn phím rất nhanh."}],
  "427": [{"jp":"旅行のために、毎月1万円ずつ**貯金して**います。","vi":"Để đi du lịch, mỗi tháng tôi tiết kiệm 10.000 yên."},{"jp":"**貯金した**お金で車を買いました。","vi":"Tôi đã mua ô tô bằng số tiền tiết kiệm được."}],
  "428": [{"jp":"最近甘いものを食べすぎて、3キロ**太りました**。","vi":"Gần đây ăn đồ ngọt quá nhiều nên tôi đã tăng 3 cân."},{"jp":"夜遅く食べると**太り**やすいです。","vi":"Ăn khuya thì dễ béo."}],
  "429": [{"jp":"毎朝ジョギングをして、5キロ**痩せました**。","vi":"Chạy bộ mỗi sáng nên tôi đã giảm 5 cân."},{"jp":"病気で父はずいぶん**痩せて**しまいました。","vi":"Vì bệnh mà bố tôi đã gầy đi nhiều."}],
  "430": [{"jp":"もう12時を**過ぎました**から、寝ましょう。","vi":"Đã quá 12 giờ rồi, đi ngủ thôi."},{"jp":"電車で寝ていて、降りる駅を**過ぎて**しまいました。","vi":"Ngủ quên trên tàu nên tôi đã đi quá ga cần xuống."}],
  "431": [{"jp":"日本の生活に**慣れました**か。","vi":"Bạn đã quen với cuộc sống ở Nhật chưa?"},{"jp":"新しい仕事にまだ**慣れて**いません。","vi":"Tôi vẫn chưa quen với công việc mới."}],
  "432": [{"jp":"このパンは**硬くて**食べにくいです。","vi":"Cái bánh mì này cứng nên khó ăn."},{"jp":"石のように**硬い**ベッドではよく眠れません。","vi":"Trên chiếc giường cứng như đá thì tôi không ngủ ngon được."}],
  "433": [{"jp":"この肉はとても**軟らかい**です。","vi":"Thịt này rất mềm."},{"jp":"赤ちゃんには**軟らかく**煮た野菜をあげます。","vi":"Cho em bé ăn rau được ninh mềm."}],
  "434": [{"jp":"**電子レンジ**でお弁当を温めます。","vi":"Tôi hâm nóng cơm hộp bằng lò vi sóng."},{"jp":"授業で**電子辞書**を使ってもいいですか。","vi":"Trong giờ học có được dùng từ điển điện tử không?"}],
  "435": [{"jp":"**携帯電話**の番号を教えてください。","vi":"Hãy cho tôi số điện thoại di động của bạn."},{"jp":"地震に備えて、**携帯ラジオ**を買っておきました。","vi":"Để phòng động đất, tôi đã mua sẵn một chiếc radio cầm tay."}],
  "436": [{"jp":"父は車の**工場**で働いています。","vi":"Bố tôi làm việc ở nhà máy ô tô."},{"jp":"来週、ビールの**工場**を見学します。","vi":"Tuần sau tôi sẽ đi tham quan nhà máy bia."}],
  "437": [{"jp":"毎日歩くのは**健康**にいいです。","vi":"Đi bộ mỗi ngày tốt cho sức khỏe."},{"jp":"タバコは**健康**に悪いですよ。","vi":"Thuốc lá có hại cho sức khỏe đấy."}],
  "438": [{"jp":"兄は高校で**剣道**を習っています。","vi":"Anh trai tôi đang học kiếm đạo ở trường cấp ba."},{"jp":"**剣道**は日本の伝統的なスポーツです。","vi":"Kiếm đạo là môn thể thao truyền thống của Nhật Bản."}],
  "439": [{"jp":"**毎週**日曜日にテニスをします。","vi":"Tôi chơi tennis vào Chủ nhật hằng tuần."},{"jp":"この番組は**毎週**見ています。","vi":"Chương trình này tuần nào tôi cũng xem."}],
  "440": [{"jp":"**毎月**25日に給料をもらいます。","vi":"Tôi nhận lương vào ngày 25 hằng tháng."},{"jp":"家賃は**毎月**払わなければなりません。","vi":"Tiền nhà phải trả hằng tháng."}],
  "441": [{"jp":"**毎年**夏に家族で海へ行きます。","vi":"Hằng năm vào mùa hè cả nhà tôi đi biển."},{"jp":"この祭りは**毎年**8月に行われます。","vi":"Lễ hội này được tổ chức vào tháng 8 hằng năm."}],
  "442": [{"jp":"3時間待って、**やっと**バスが来ました。","vi":"Đợi 3 tiếng, cuối cùng xe buýt cũng đến."},{"jp":"何回も練習して、**やっと**自転車に乗れるようになりました。","vi":"Tập rất nhiều lần, cuối cùng tôi đã đi được xe đạp."}],
  "443": [{"jp":"今日は**かなり**寒いですね。","vi":"Hôm nay khá lạnh nhỉ."},{"jp":"日本語が**かなり**上手になりました。","vi":"Tiếng Nhật của tôi đã tiến bộ khá nhiều."}],
  "444": [{"jp":"明日は**必ず**来てください。","vi":"Ngày mai nhất định hãy đến nhé."},{"jp":"寝る前に**必ず**歯を磨きます。","vi":"Trước khi ngủ tôi nhất định đánh răng."}],
  "445": [{"jp":"この秘密は**絶対に**誰にも言わないでください。","vi":"Bí mật này tuyệt đối đừng nói với ai."},{"jp":"次の試合は**絶対に**勝ちたいです。","vi":"Trận tới tôi nhất định muốn thắng."}],
  "446": [{"jp":"彼女はピアノを**上手に**弾きます。","vi":"Cô ấy chơi piano giỏi."},{"jp":"箸を**上手に**使えるようになりました。","vi":"Tôi đã dùng đũa khéo rồi."}],
  "447": [{"jp":"**できるだけ**早く来てください。","vi":"Hãy đến sớm nhất có thể."},{"jp":"健康のために、**できるだけ**階段を使っています。","vi":"Vì sức khỏe, tôi cố gắng đi cầu thang bộ nhiều nhất có thể."}],
  "448": [{"jp":"**この頃**、朝が寒くなりましたね。","vi":"Dạo này buổi sáng trở lạnh rồi nhỉ."},{"jp":"**この頃**忙しくて、家族に電話していません。","vi":"Dạo này bận nên tôi không gọi điện cho gia đình."}],
  "449": [{"jp":"子どもたちにお菓子を2つ**ずつ**あげました。","vi":"Tôi đã cho mỗi đứa trẻ 2 cái kẹo."},{"jp":"毎日少し**ずつ**日本語が分かるようになりました。","vi":"Mỗi ngày tôi hiểu tiếng Nhật thêm từng chút một."}],
  "450": [{"jp":"A「バスで行きましょうか。」B「いいえ、電車にしましょう。**そのほうが**早いですよ。」","vi":"A: “Mình đi xe buýt nhé?” B: “Không, đi tàu đi. Như thế nhanh hơn đấy.”"},{"jp":"毎日少しずつ勉強したらどうですか。**そのほうが**覚えやすいですよ。","vi":"Sao bạn không học từng chút mỗi ngày? Như thế dễ nhớ hơn đấy."}],
  "451": [{"jp":"**お客様**、こちらへどうぞ。","vi":"Thưa quý khách, xin mời đi lối này."},{"jp":"店員は**お客様**に丁寧に説明しました。","vi":"Nhân viên đã giải thích lịch sự cho quý khách."}],
  "452": [{"jp":"今日は私にとって**特別な**日です。","vi":"Hôm nay là một ngày đặc biệt đối với tôi."},{"jp":"誕生日なので、**特別に**ケーキを作りました。","vi":"Vì là sinh nhật nên tôi đã đặc biệt làm bánh ngọt."}],
  "453": [{"jp":"社長は今、会議を**していらっしゃいます**。","vi":"Giám đốc bây giờ đang họp."},{"jp":"先生は毎朝ジョギングを**していらっしゃいます**。","vi":"Thầy giáo sáng nào cũng chạy bộ."}],
  "454": [{"jp":"私の趣味は**水泳**です。","vi":"Sở thích của tôi là bơi lội."},{"jp":"夏休みに**水泳**教室に通いました。","vi":"Kỳ nghỉ hè tôi đã theo học lớp bơi."}],
  "455": [{"jp":"週末は掃除**とか**洗濯とかで忙しいです。","vi":"Cuối tuần tôi bận dọn dẹp, giặt giũ, v.v."},{"jp":"野菜、たとえばにんじん**とか**トマトとかを毎日食べましょう。","vi":"Hãy ăn rau mỗi ngày, ví dụ như cà rốt, cà chua, v.v."}],
  "456": [{"jp":"彼の**気持ち**がよく分かります。","vi":"Tôi hiểu rõ cảm giác của anh ấy."},{"jp":"感謝の**気持ち**を込めて、手紙を書きました。","vi":"Tôi đã viết thư với tất cả lòng biết ơn."}],
  "457": [{"jp":"子どもは**乗り物**が大好きです。","vi":"Trẻ con rất thích các loại xe cộ, phương tiện."},{"jp":"私は**乗り物**に酔いやすいです。","vi":"Tôi dễ bị say khi đi tàu xe."}],
  "458": [{"jp":"京都は**歴史**のある町です。","vi":"Kyoto là thành phố có bề dày lịch sử."},{"jp":"私は日本の**歴史**に興味があります。","vi":"Tôi quan tâm đến lịch sử Nhật Bản."}],
  "459": [{"jp":"これは15**世紀**に建てられたお城です。","vi":"Đây là lâu đài được xây dựng vào thế kỷ 15."},{"jp":"21**世紀**はコンピューターの時代です。","vi":"Thế kỷ 21 là thời đại của máy tính."}],
  "460": [{"jp":"**遠く**に富士山が見えます。","vi":"Ở đằng xa có thể nhìn thấy núi Phú Sĩ."},{"jp":"あまり**遠く**へ行かないでね。","vi":"Đừng đi xa quá nhé."}],
  "461": [{"jp":"昔は**汽車**で旅行をしました。","vi":"Ngày xưa người ta đi du lịch bằng tàu hỏa hơi nước."},{"jp":"博物館に古い**汽車**が展示されています。","vi":"Ở bảo tàng có trưng bày một chiếc tàu hỏa hơi nước cũ."}],
  "462": [{"jp":"昔、祖父は**汽船**で外国へ行きました。","vi":"Ngày xưa ông tôi đã đi nước ngoài bằng tàu thủy hơi nước."},{"jp":"**汽船**が港に着きました。","vi":"Con tàu hơi nước đã cập cảng."}],
  "463": [{"jp":"駅に**大勢の**人が集まっています。","vi":"Rất nhiều người đang tập trung ở ga."},{"jp":"コンサートには**大勢の**ファンが来ました。","vi":"Rất nhiều người hâm mộ đã đến buổi hòa nhạc."}],
  "464": [{"jp":"この荷物を2階まで**運んで**ください。","vi":"Hãy mang hành lý này lên tầng 2."},{"jp":"トラックで野菜を東京へ**運びます**。","vi":"Rau được vận chuyển đến Tokyo bằng xe tải."}],
  "465": [{"jp":"空を鳥が**飛んで**います。","vi":"Chim đang bay trên bầu trời."},{"jp":"風で帽子が**飛んで**しまいました。","vi":"Mũ bị gió thổi bay mất."}],
  "466": [{"jp":"この町は**安全**で住みやすいです。","vi":"Thành phố này an toàn và dễ sống."},{"jp":"子どもが**安全に**遊べる公園ができました。","vi":"Một công viên nơi trẻ em có thể chơi an toàn đã được xây xong."}],
  "467": [{"jp":"いつか**宇宙**へ行ってみたいです。","vi":"Một ngày nào đó tôi muốn thử đi vào vũ trụ."},{"jp":"**宇宙**から見た地球はとてもきれいだそうです。","vi":"Nghe nói Trái đất nhìn từ vũ trụ rất đẹp."}],
  "468": [{"jp":"**地球**は太陽の周りを回っています。","vi":"Trái đất quay quanh Mặt trời."},{"jp":"**地球**の環境を守りましょう。","vi":"Hãy bảo vệ môi trường Trái đất."}],
  "469": [{"jp":"テストで100点を取って、先生に**褒められました**。","vi":"Được 100 điểm bài kiểm tra nên tôi được thầy khen."},{"jp":"子どもは**褒める**と、もっと頑張ります。","vi":"Trẻ con khi được khen sẽ càng cố gắng hơn."}],
  "470": [{"jp":"宿題を忘れて、先生に**しかられました**。","vi":"Quên làm bài tập nên tôi bị thầy mắng."},{"jp":"父は弟を大きな声で**しかりました**。","vi":"Bố đã mắng em trai tôi rất to."}],
  "471": [{"jp":"友達を映画に**誘いました**。","vi":"Tôi đã rủ bạn đi xem phim."},{"jp":"田中さんに食事に**誘われました**。","vi":"Tôi được anh Tanaka mời đi ăn."}],
  "472": [{"jp":"明日は6時に**起こして**ください。","vi":"Ngày mai hãy đánh thức tôi lúc 6 giờ."},{"jp":"運転中に携帯電話を使って、事故を**起こして**しまいました。","vi":"Dùng điện thoại khi lái xe nên tôi đã gây ra tai nạn."}],
  "473": [{"jp":"結婚式に友達を50人**招待しました**。","vi":"Tôi đã mời 50 người bạn đến dự đám cưới."},{"jp":"先生を家に**招待して**、日本料理を作りました。","vi":"Tôi mời thầy đến nhà và nấu món Nhật."}],
  "474": [{"jp":"友達に引っ越しの手伝いを**頼みました**。","vi":"Tôi đã nhờ bạn giúp chuyển nhà."},{"jp":"忙しいので、弟に買い物を**頼んだ**。","vi":"Vì bận nên tôi nhờ em trai đi mua đồ."}],
  "475": [{"jp":"車に**注意して**道を渡りましょう。","vi":"Hãy chú ý xe cộ khi qua đường."},{"jp":"健康に**注意して**、無理をしないでください。","vi":"Hãy chú ý sức khỏe, đừng làm quá sức."}],
  "476": [{"jp":"電車の中で財布を**盗られました**。","vi":"Tôi bị trộm ví trên tàu."},{"jp":"人の物を**盗って**はいけません。","vi":"Không được lấy trộm đồ của người khác."}],
  "477": [{"jp":"電車で隣の人に足を**踏まれました**。","vi":"Trên tàu tôi bị người bên cạnh giẫm vào chân."},{"jp":"芝生を**踏まない**でください。","vi":"Xin đừng giẫm lên cỏ."}],
  "478": [{"jp":"弟が私のカメラを**壊しました**。","vi":"Em trai tôi đã làm hỏng máy ảnh của tôi."},{"jp":"冷たいものを飲みすぎて、お腹を**壊して**しまいました。","vi":"Uống đồ lạnh quá nhiều nên tôi bị đau bụng."}],
  "479": [{"jp":"カレーで白いシャツを**汚して**しまいました。","vi":"Tôi đã làm bẩn áo sơ mi trắng vì cà ri."},{"jp":"図書館の本を**汚さない**でください。","vi":"Xin đừng làm bẩn sách của thư viện."}],
  "480": [{"jp":"入学式は4月に**行われます**。","vi":"Lễ nhập học được tổ chức vào tháng 4."},{"jp":"来週、避難訓練を**行います**。","vi":"Tuần sau sẽ tiến hành diễn tập sơ tán."}],
  "481": [{"jp":"日本は車をたくさん**輸出して**います。","vi":"Nhật Bản xuất khẩu rất nhiều ô tô."},{"jp":"ベトナムはコーヒーを世界中に**輸出して**います。","vi":"Việt Nam xuất khẩu cà phê đi khắp thế giới."}],
  "482": [{"jp":"日本は石油を外国から**輸入して**います。","vi":"Nhật Bản nhập khẩu dầu mỏ từ nước ngoài."},{"jp":"この店では**輸入した**ワインを売っています。","vi":"Cửa hàng này bán rượu vang nhập khẩu."}],
  "483": [{"jp":"この小説を日本語からベトナム語に**翻訳しました**。","vi":"Tôi đã dịch cuốn tiểu thuyết này từ tiếng Nhật sang tiếng Việt."},{"jp":"英語のメールを**翻訳して**もらえませんか。","vi":"Bạn có thể dịch giúp tôi email tiếng Anh này không?"}],
  "484": [{"jp":"エジソンは電球を**発明しました**。","vi":"Edison đã phát minh ra bóng đèn."},{"jp":"便利な道具を**発明する**のが夢です。","vi":"Ước mơ của tôi là phát minh ra dụng cụ tiện lợi."}],
  "485": [{"jp":"新しい星を**発見しました**。","vi":"Đã phát hiện ra một ngôi sao mới."},{"jp":"コロンブスはアメリカ大陸を**発見した**と言われています。","vi":"Người ta nói Columbus đã phát hiện ra châu Mỹ."}],
  "486": [{"jp":"この家は有名な建築家が**設計しました**。","vi":"Ngôi nhà này do một kiến trúc sư nổi tiếng thiết kế."},{"jp":"父は橋を**設計する**仕事をしています。","vi":"Bố tôi làm công việc thiết kế cầu."}],
  "487": [{"jp":"日本人は**米**をよく食べます。","vi":"Người Nhật hay ăn gạo (cơm)."},{"jp":"この地方ではおいしい**米**が作られています。","vi":"Ở vùng này người ta trồng ra gạo ngon."}],
  "488": [{"jp":"ビールは**麦**から作られます。","vi":"Bia được làm từ lúa mạch."},{"jp":"畑で**麦**を育てています。","vi":"Người ta đang trồng lúa mạch trên ruộng."}],
  "489": [{"jp":"プラスチックは**石油**から作られます。","vi":"Nhựa được làm từ dầu mỏ."},{"jp":"日本は**石油**をほとんど外国から輸入しています。","vi":"Nhật Bản nhập khẩu gần như toàn bộ dầu mỏ từ nước ngoài."}],
  "490": [{"jp":"パンの**原料**は小麦粉です。","vi":"Nguyên liệu làm bánh mì là bột mì."},{"jp":"紙の**原料**は木です。","vi":"Nguyên liệu làm giấy là gỗ."}],
  "491": [{"jp":"昨夜、隣の家に**泥棒**が入りました。","vi":"Đêm qua kẻ trộm đã đột nhập vào nhà bên cạnh."},{"jp":"**泥棒**に財布を盗られました。","vi":"Tôi bị kẻ trộm lấy mất ví."}],
  "492": [{"jp":"道が分からなかったので、**警官**に聞きました。","vi":"Vì không biết đường nên tôi đã hỏi cảnh sát."},{"jp":"**警官**が泥棒を捕まえました。","vi":"Cảnh sát đã bắt được tên trộm."}],
  "493": [{"jp":"兄は**建築家**として働いています。","vi":"Anh trai tôi làm kiến trúc sư."},{"jp":"この美術館は有名な**建築家**が設計しました。","vi":"Bảo tàng mỹ thuật này do một kiến trúc sư nổi tiếng thiết kế."}],
  "494": [{"jp":"子どもの頃、**科学者**になりたかったです。","vi":"Hồi nhỏ tôi muốn trở thành nhà khoa học."},{"jp":"多くの**科学者**が新しい薬を研究しています。","vi":"Nhiều nhà khoa học đang nghiên cứu thuốc mới."}],
  "495": [{"jp":"弟は**漫画**を読むのが好きです。","vi":"Em trai tôi thích đọc truyện tranh."},{"jp":"日本の**漫画**は世界中で人気があります。","vi":"Truyện tranh Nhật Bản được yêu thích trên khắp thế giới."}],
  "496": [{"jp":"この歌は**世界中**で歌われています。","vi":"Bài hát này được hát trên khắp thế giới."},{"jp":"**世界中**から観光客が京都に来ます。","vi":"Khách du lịch từ khắp thế giới đến Kyoto."}],
  "497": [{"jp":"電話はベル**によって**発明されました。","vi":"Điện thoại được phát minh bởi Bell."},{"jp":"国**によって**習慣が違います。","vi":"Tùy theo quốc gia mà phong tục khác nhau."}],
  "498": [{"jp":"この空港は海を**埋め立てて**造られました。","vi":"Sân bay này được xây dựng bằng cách san lấp biển."},{"jp":"昔、この辺りの池は**埋め立てられて**、公園になりました。","vi":"Ngày xưa cái ao quanh đây đã bị san lấp và trở thành công viên."}],
  "499": [{"jp":"日本の**技術**は世界で有名です。","vi":"Kỹ thuật của Nhật Bản nổi tiếng thế giới."},{"jp":"新しい**技術**を学ぶために、留学しました。","vi":"Tôi đi du học để học kỹ thuật mới."}],
  "500": [{"jp":"家を建てるために**土地**を買いました。","vi":"Tôi đã mua đất để xây nhà."},{"jp":"東京は**土地**の値段がとても高いです。","vi":"Ở Tokyo giá đất rất cao."}],
  "501": [{"jp":"工事の**騒音**で眠れませんでした。","vi":"Vì tiếng ồn công trình mà tôi không ngủ được."},{"jp":"空港の近くでは**騒音**が問題になっています。","vi":"Ở khu vực gần sân bay, tiếng ồn đang trở thành vấn đề."}],
  "502": [{"jp":"図書館は誰でも**利用できます**。","vi":"Thư viện thì ai cũng có thể sử dụng."},{"jp":"毎日電車を**利用して**通勤しています。","vi":"Hằng ngày tôi đi làm bằng tàu điện."}],
  "503": [{"jp":"今は21**世紀**です。","vi":"Bây giờ là thế kỷ 21."},{"jp":"日本では16**世紀**に多くの城が建てられました。","vi":"Ở Nhật, vào thế kỷ 16 nhiều lâu đài đã được xây dựng."}],
  "504": [{"jp":"友達の結婚式はとても**豪華**でした。","vi":"Đám cưới của bạn tôi rất sang trọng."},{"jp":"誕生日に**豪華な**料理を食べました。","vi":"Vào sinh nhật tôi đã ăn những món ăn thịnh soạn."}],
  "505": [{"jp":"美術館で有名な**彫刻**を見ました。","vi":"Tôi đã xem một tác phẩm điêu khắc nổi tiếng ở bảo tàng mỹ thuật."},{"jp":"父の趣味は木の**彫刻**です。","vi":"Sở thích của bố tôi là điêu khắc gỗ."}],
  "506": [{"jp":"赤ちゃんがぐっすり**眠って**います。","vi":"Em bé đang ngủ say."},{"jp":"昨夜はうるさくて、よく**眠れません**でした。","vi":"Đêm qua ồn ào nên tôi không ngủ ngon được."}],
  "507": [{"jp":"木の板に名前を**彫りました**。","vi":"Tôi đã khắc tên lên tấm gỗ."},{"jp":"この仏像は1本の木から**彫られた**そうです。","vi":"Nghe nói bức tượng Phật này được khắc từ một khúc gỗ."}],
  "508": [{"jp":"仕事の**仲間**と飲みに行きました。","vi":"Tôi đã đi uống với đồng nghiệp."},{"jp":"サッカーチームの**仲間**はみんな仲がいいです。","vi":"Các bạn trong đội bóng ai cũng thân với nhau."}],
  "509": [{"jp":"朝ご飯を食べました。**そのあと**、散歩に行きました。","vi":"Tôi ăn sáng. Sau đó, tôi đi dạo."},{"jp":"午前は会議があります。**そのあと**、昼ご飯を食べに行きましょう。","vi":"Buổi sáng có cuộc họp. Sau đó chúng ta đi ăn trưa nhé."}],
  "510": [{"jp":"試験に合格するために、**一生懸命**勉強しました。","vi":"Tôi đã học chăm chỉ để đỗ kỳ thi."},{"jp":"父は家族のために**一生懸命**働いています。","vi":"Bố tôi làm việc miệt mài vì gia đình."}],
  "511": [{"jp":"台所に**鼠**が出ました。","vi":"Có chuột xuất hiện trong bếp."},{"jp":"猫が**鼠**を追いかけています。","vi":"Con mèo đang đuổi theo con chuột."}],
  "512": [{"jp":"この池には魚が**一匹もいない**そうです。","vi":"Nghe nói ở cái ao này không có lấy một con cá nào."},{"jp":"猫を飼ってから、家に鼠が**一匹もいなく**なりました。","vi":"Từ khi nuôi mèo, trong nhà không còn con chuột nào nữa."}],
  "513": [{"jp":"母は一人で三人の子どもを**育てました**。","vi":"Mẹ tôi đã một mình nuôi ba đứa con."},{"jp":"ベランダでトマトを**育てて**います。","vi":"Tôi đang trồng cà chua ở ban công."}],
  "514": [{"jp":"重い机を二人で**運びました**。","vi":"Hai người đã cùng khiêng cái bàn nặng."},{"jp":"店員が料理をテーブルに**運んで**きました。","vi":"Nhân viên đã mang món ăn đến bàn."}],
  "515": [{"jp":"祖父は去年病気で**亡くなりました**。","vi":"Ông tôi đã qua đời năm ngoái vì bệnh."},{"jp":"有名な作家が90歳で**亡くなった**そうです。","vi":"Nghe nói một nhà văn nổi tiếng đã qua đời ở tuổi 90."}],
  "516": [{"jp":"父は手術のために1週間**入院しました**。","vi":"Bố tôi đã nhập viện một tuần để phẫu thuật."},{"jp":"**入院して**いる友達のお見舞いに行きました。","vi":"Tôi đã đi thăm người bạn đang nằm viện."}],
  "517": [{"jp":"母は来週**退院できる**そうです。","vi":"Nghe nói tuần sau mẹ tôi có thể xuất viện."},{"jp":"**退院した**後も、しばらく家で休んでください。","vi":"Sau khi xuất viện, hãy nghỉ ngơi ở nhà một thời gian."}],
  "518": [{"jp":"寒いので、ストーブのスイッチを**入れて**ください。","vi":"Lạnh quá, hãy bật công tắc lò sưởi lên."},{"jp":"コーヒーに砂糖を**入れます**か。","vi":"Bạn có cho đường vào cà phê không?"}],
  "519": [{"jp":"出かける前に、エアコンのスイッチを**切って**ください。","vi":"Trước khi ra ngoài hãy tắt công tắc điều hòa."},{"jp":"はさみで紙を**切りました**。","vi":"Tôi đã cắt giấy bằng kéo."}],
  "520": [{"jp":"出かけるときは、ドアにかぎを**掛けて**ください。","vi":"Khi ra ngoài hãy khóa cửa."},{"jp":"寝る前に玄関のかぎを**掛けました**か。","vi":"Trước khi ngủ bạn đã khóa cửa ra vào chưa?"}],
  "521": [{"jp":"朝の散歩は**気持ちがいい**ですね。","vi":"Đi dạo buổi sáng thật dễ chịu nhỉ."},{"jp":"お風呂に入ると、とても**気持ちがいい**です。","vi":"Tắm bồn thì thấy rất dễ chịu."}],
  "522": [{"jp":"バスに酔って、**気持ちが悪く**なりました。","vi":"Tôi bị say xe buýt nên thấy khó chịu."},{"jp":"汗でシャツが濡れて、**気持ちが悪い**です。","vi":"Áo ướt mồ hôi nên thấy khó chịu."}],
  "523": [{"jp":"公園に**大きな**木があります。","vi":"Trong công viên có một cái cây to."},{"jp":"彼は**大きな**声で歌いました。","vi":"Anh ấy đã hát bằng giọng to."}],
  "524": [{"jp":"庭に**小さな**花が咲いています。","vi":"Trong vườn có những bông hoa nhỏ đang nở."},{"jp":"私は**小さな**町で生まれました。","vi":"Tôi sinh ra ở một thị trấn nhỏ."}],
  "525": [{"jp":"**赤ちゃん**が泣いています。","vi":"Em bé đang khóc."},{"jp":"姉に**赤ちゃん**が生まれました。","vi":"Chị gái tôi đã sinh em bé."}],
  "526": [{"jp":"弟は**小学校**の3年生です。","vi":"Em trai tôi học lớp 3 tiểu học."},{"jp":"**小学校**の時の先生に会いました。","vi":"Tôi đã gặp lại thầy giáo hồi tiểu học."}],
  "527": [{"jp":"妹は今年**中学校**に入りました。","vi":"Em gái tôi năm nay đã vào trường trung học cơ sở."},{"jp":"**中学校**ではテニス部に入っていました。","vi":"Hồi trung học cơ sở tôi tham gia câu lạc bộ tennis."}],
  "528": [{"jp":"**駅前**に新しいスーパーができました。","vi":"Một siêu thị mới đã mở ở trước ga."},{"jp":"明日10時に**駅前**で会いましょう。","vi":"Ngày mai 10 giờ gặp nhau trước ga nhé."}],
  "529": [{"jp":"**海岸**を散歩するのが好きです。","vi":"Tôi thích đi dạo dọc bờ biển."},{"jp":"**海岸**にきれいな貝がたくさん落ちていました。","vi":"Trên bờ biển có rất nhiều vỏ sò đẹp."}],
  "530": [{"jp":"彼は**嘘**をついたことがありません。","vi":"Anh ấy chưa bao giờ nói dối."},{"jp":"その話は**嘘**だと思います。","vi":"Tôi nghĩ câu chuyện đó là bịa đặt."}],
  "531": [{"jp":"この**書類**にサインしてください。","vi":"Hãy ký vào giấy tờ này."},{"jp":"机の上に**書類**がたくさんあります。","vi":"Trên bàn có rất nhiều giấy tờ."}],
  "532": [{"jp":"パソコンの**電源**を入れてください。","vi":"Hãy bật nguồn máy tính."},{"jp":"飛行機の中では、携帯電話の**電源**を切ってください。","vi":"Trên máy bay hãy tắt nguồn điện thoại di động."}],
  "533": [{"jp":"この時計は**スイス製**です。","vi":"Chiếc đồng hồ này là hàng sản xuất tại Thụy Sĩ."},{"jp":"**木製**のいすは温かい感じがします。","vi":"Ghế làm bằng gỗ cho cảm giác ấm áp."}],
  "534": [{"jp":"町内会のお知らせを**回覧**します。","vi":"Thông báo của tổ dân phố sẽ được chuyền tay nhau đọc."},{"jp":"**回覧板**を隣の家に持って行きました。","vi":"Tôi đã mang bảng thông báo chuyền tay sang nhà bên cạnh."}],
  "535": [{"jp":"先生は今、**研究室**にいらっしゃいます。","vi":"Thầy giáo bây giờ đang ở phòng nghiên cứu."},{"jp":"大学院では**研究室**で実験をしています。","vi":"Ở cao học tôi làm thí nghiệm trong phòng nghiên cứu."}],
  "536": [{"jp":"部屋を**きちんと**片付けなさい。","vi":"Hãy dọn phòng cho gọn gàng."},{"jp":"毎日**きちんと**薬を飲んでください。","vi":"Hãy uống thuốc đều đặn, đúng cách mỗi ngày."}],
  "537": [{"jp":"引き出しの中を**整理しました**。","vi":"Tôi đã sắp xếp lại bên trong ngăn kéo."},{"jp":"書類を日付順に**整理して**ください。","vi":"Hãy sắp xếp giấy tờ theo thứ tự ngày tháng."}],
  "538": [{"jp":"図書館で本を3**冊**借りました。","vi":"Tôi đã mượn 3 cuốn sách ở thư viện."},{"jp":"毎月本を5**冊**ぐらい読みます。","vi":"Mỗi tháng tôi đọc khoảng 5 cuốn sách."}],
  "539": [{"jp":"ここに**判子**を押してください。","vi":"Hãy đóng dấu vào đây."},{"jp":"銀行で口座を作るとき、**判子**が必要です。","vi":"Khi mở tài khoản ngân hàng cần có con dấu."}],
  "540": [{"jp":"書類にはんこを**押しました**。","vi":"Tôi đã đóng dấu vào giấy tờ."},{"jp":"このボタンを**押す**と、水が出ます。","vi":"Bấm nút này thì nước sẽ chảy ra."}],
  "541": [{"jp":"私と兄は**双子**です。","vi":"Tôi và anh trai là anh em sinh đôi."},{"jp":"**双子**の赤ちゃんが生まれました。","vi":"Một cặp em bé sinh đôi đã ra đời."}],
  "542": [{"jp":"私は三人**姉妹**の長女です。","vi":"Tôi là con gái cả trong ba chị em gái."},{"jp":"あの**姉妹**はとても仲がいいです。","vi":"Hai chị em gái kia rất thân nhau."}],
  "543": [{"jp":"娘は母親によく**似ています**。","vi":"Con gái rất giống mẹ."},{"jp":"この二つの漢字は**似ている**ので、間違えやすいです。","vi":"Hai chữ Hán này giống nhau nên dễ nhầm."}],
  "544": [{"jp":"彼女は明るい**性格**です。","vi":"Cô ấy có tính cách vui vẻ."},{"jp":"兄と私は**性格**が全然違います。","vi":"Anh trai và tôi tính cách hoàn toàn khác nhau."}],
  "545": [{"jp":"兄は元気ですが、弟は**大人しい**です。","vi":"Anh trai thì hiếu động nhưng em trai thì hiền lành, trầm tính."},{"jp":"この犬は**大人しくて**、全然吠えません。","vi":"Con chó này hiền lành, hoàn toàn không sủa."}],
  "546": [{"jp":"毎日犬の**世話をして**います。","vi":"Hằng ngày tôi chăm sóc con chó."},{"jp":"入院している祖母の**世話をしました**。","vi":"Tôi đã chăm sóc bà đang nằm viện."}],
  "547": [{"jp":"友達と話していると、すぐ**時間が経ちます**。","vi":"Nói chuyện với bạn bè thì thời gian trôi qua thật nhanh."},{"jp":"**時間が経つ**のは早いですね。もう12月です。","vi":"Thời gian trôi nhanh thật nhỉ. Đã tháng 12 rồi."}],
  "548": [{"jp":"私はチョコレートが**大好き**です。","vi":"Tôi rất thích sô cô la."},{"jp":"**大好きな**歌手のコンサートに行きました。","vi":"Tôi đã đi xem concert của ca sĩ mà tôi rất thích."}],
  "549": [{"jp":"数学のテストで90**点**を取りました。","vi":"Tôi được 90 điểm bài kiểm tra toán."},{"jp":"サッカーの試合で2**点**入れました。","vi":"Tôi đã ghi 2 bàn (điểm) trong trận bóng đá."}],
  "550": [{"jp":"子どもの頃、よく兄と**喧嘩しました**。","vi":"Hồi nhỏ tôi hay cãi nhau với anh trai."},{"jp":"友達と**喧嘩して**、まだ話していません。","vi":"Tôi cãi nhau với bạn và vẫn chưa nói chuyện lại."}],
  "551": [{"jp":"昨夜、**不思議な**夢を見ました。","vi":"Đêm qua tôi đã mơ một giấc mơ kỳ lạ."},{"jp":"鍵をかけたのにドアが開いていた。**不思議**ですね。","vi":"Đã khóa rồi mà cửa lại mở. Kỳ lạ thật nhỉ."}],
  "552": [{"jp":"先生の質問に**答えました**。","vi":"Tôi đã trả lời câu hỏi của thầy."},{"jp":"アンケートに**答えて**ください。","vi":"Hãy trả lời bảng khảo sát."}],
  "553": [{"jp":"台風で木が**倒れました**。","vi":"Cây bị đổ vì bão."},{"jp":"父が会社で急に**倒れて**、病院に運ばれました。","vi":"Bố tôi đột nhiên ngã quỵ ở công ty và được đưa vào bệnh viện."}],
  "554": [{"jp":"火事で家が**焼けて**しまいました。","vi":"Ngôi nhà đã bị cháy rụi do hỏa hoạn."},{"jp":"パンがおいしそうに**焼けました**。","vi":"Bánh mì đã được nướng chín trông thật ngon."}],
  "555": [{"jp":"毎朝、この道を**通って**学校へ行きます。","vi":"Mỗi sáng tôi đi qua con đường này để đến trường."},{"jp":"兄は大学の試験に**通りました**。","vi":"Anh trai tôi đã đỗ kỳ thi đại học."}],
  "556": [{"jp":"飼っていた金魚が**死んで**しまいました。","vi":"Con cá vàng tôi nuôi đã chết mất."},{"jp":"**死ぬ**までに一度富士山に登りたいです。","vi":"Trước khi chết tôi muốn leo núi Phú Sĩ một lần."}],
  "557": [{"jp":"急に大きな音がして、**びっくりしました**。","vi":"Đột nhiên có tiếng động lớn nên tôi đã giật mình."},{"jp":"友達が急に来たので、**びっくりしました**。","vi":"Bạn tôi đột nhiên đến nên tôi đã ngạc nhiên."}],
  "558": [{"jp":"試験に落ちて、**がっかりしました**。","vi":"Tôi trượt kỳ thi nên rất thất vọng."},{"jp":"雨で旅行が中止になって、子どもたちは**がっかりして**いる。","vi":"Chuyến du lịch bị hủy vì mưa nên bọn trẻ đang thất vọng."}],
  "559": [{"jp":"息子から電話が来て、**安心しました**。","vi":"Con trai gọi điện đến nên tôi yên tâm."},{"jp":"医者に「大丈夫ですよ」と言われて、**安心した**。","vi":"Được bác sĩ nói \"Không sao đâu\" nên tôi yên tâm."}],
  "560": [{"jp":"寝坊して、会社に**遅刻しました**。","vi":"Tôi ngủ quên nên đã đến công ty muộn."},{"jp":"明日は大切な会議ですから、**遅刻しないで**ください。","vi":"Ngày mai có cuộc họp quan trọng nên đừng đến muộn nhé."}],
  "561": [{"jp":"熱があったので、学校を**早退しました**。","vi":"Vì bị sốt nên tôi đã về sớm khỏi trường."},{"jp":"子どもが病気なので、今日は会社を**早退します**。","vi":"Con tôi bị ốm nên hôm nay tôi xin về sớm."}],
  "562": [{"jp":"子どものころ、よく弟と**喧嘩しました**。","vi":"Hồi nhỏ tôi hay cãi nhau với em trai."},{"jp":"昨日彼女と**喧嘩して**、まだ話していません。","vi":"Hôm qua tôi cãi nhau với bạn gái, đến giờ vẫn chưa nói chuyện."}],
  "563": [{"jp":"両親は私が10歳のときに**離婚しました**。","vi":"Bố mẹ tôi ly hôn khi tôi 10 tuổi."},{"jp":"最近、結婚してすぐ**離婚する**人が増えています。","vi":"Gần đây số người kết hôn xong ly hôn ngay đang tăng lên."}],
  "564": [{"jp":"この機械の使い方は**複雑**です。","vi":"Cách sử dụng cái máy này phức tạp."},{"jp":"駅までの道が**複雑な**ので、地図を書きましょう。","vi":"Đường đến ga phức tạp nên để tôi vẽ bản đồ nhé."}],
  "565": [{"jp":"道に自転車を止めると、歩く人の**邪魔**になります。","vi":"Đỗ xe đạp trên đường sẽ gây cản trở người đi bộ."},{"jp":"この箱は**邪魔な**ので、外に出してください。","vi":"Cái hộp này vướng víu nên hãy mang ra ngoài."}],
  "566": [{"jp":"手が**汚い**ですから、洗ってから食べなさい。","vi":"Tay bẩn đấy, rửa rồi hãy ăn."},{"jp":"弟の部屋はいつも**汚い**です。","vi":"Phòng của em trai tôi lúc nào cũng bẩn."}],
  "567": [{"jp":"誕生日にプレゼントをもらって、とても**嬉しかった**です。","vi":"Được tặng quà sinh nhật, tôi rất vui."},{"jp":"また会えて**嬉しい**です。","vi":"Tôi rất vui vì được gặp lại bạn."}],
  "568": [{"jp":"飼っていた犬が死んで、とても**悲しかった**。","vi":"Con chó tôi nuôi chết, tôi rất buồn."},{"jp":"この映画は**悲しい**話なので、泣いてしまいました。","vi":"Bộ phim này là câu chuyện buồn nên tôi đã khóc."}],
  "569": [{"jp":"みんなの前で転んで、**恥ずかしかった**です。","vi":"Bị ngã trước mặt mọi người, tôi xấu hổ quá."},{"jp":"日本語を間違えるのは**恥ずかしい**ことではありません。","vi":"Nói sai tiếng Nhật không phải là điều đáng xấu hổ."}],
  "570": [{"jp":"日本は**地震**が多い国です。","vi":"Nhật Bản là nước có nhiều động đất."},{"jp":"昨夜大きな**地震**があって、本棚が倒れました。","vi":"Đêm qua có trận động đất lớn, giá sách đã bị đổ."}],
  "571": [{"jp":"**台風**で電車が止まりました。","vi":"Tàu điện đã dừng vì bão."},{"jp":"明日、**台風**が来るそうです。","vi":"Nghe nói ngày mai bão sẽ đến."}],
  "572": [{"jp":"近くの家で**火事**がありました。","vi":"Đã xảy ra hỏa hoạn ở một ngôi nhà gần đây."},{"jp":"**火事**のときは、エレベーターを使わないでください。","vi":"Khi có hỏa hoạn, xin đừng dùng thang máy."}],
  "573": [{"jp":"交差点で**事故**がありました。","vi":"Có tai nạn ở ngã tư."},{"jp":"**事故**で道が込んでいます。","vi":"Đường đang tắc vì tai nạn."}],
  "574": [{"jp":"日曜日に**お見合い**をします。","vi":"Chủ nhật tôi sẽ đi xem mặt."},{"jp":"両親は**お見合い**で結婚しました。","vi":"Bố mẹ tôi kết hôn qua mai mối xem mặt."}],
  "575": [{"jp":"今月は**電話代**が高かったです。","vi":"Tháng này tiền điện thoại cao."},{"jp":"**電話代**はコンビニで払えます。","vi":"Tiền điện thoại có thể trả ở cửa hàng tiện lợi."}],
  "576": [{"jp":"私の部屋は305**号室**です。","vi":"Phòng của tôi là phòng số 305."},{"jp":"田中さんは何**号室**に住んでいますか。","vi":"Anh Tanaka sống ở phòng số mấy?"}],
  "577": [{"jp":"走ったので、**汗**をたくさんかきました。","vi":"Vì chạy nên tôi đổ rất nhiều mồ hôi."},{"jp":"暑くて、**汗**が止まりません。","vi":"Nóng quá, mồ hôi cứ chảy mãi."}],
  "578": [{"jp":"食事の前に、**石鹸**で手を洗いましょう。","vi":"Trước bữa ăn hãy rửa tay bằng xà phòng."},{"jp":"お風呂の**石鹸**がなくなりました。","vi":"Xà phòng trong nhà tắm hết rồi."}],
  "579": [{"jp":"駅の前に人が**大勢**集まっています。","vi":"Có rất đông người đang tập trung trước nhà ga."},{"jp":"日曜日の公園には**大勢**の家族が来ます。","vi":"Vào chủ nhật có rất nhiều gia đình đến công viên."}],
  "580": [{"jp":"仕事が終わって、部長に「**お疲れ様でした**」と言いました。","vi":"Xong việc, tôi nói với trưởng phòng: \"Anh đã vất vả rồi\"."},{"jp":"「では、今日はこれで帰ります。」「**お疲れ様でした**。」","vi":"\"Vậy hôm nay tôi về trước nhé.\" \"Anh vất vả rồi.\""}],
  "581": [{"jp":"明日の午後、事務所に**伺います**。","vi":"Chiều mai tôi xin phép đến văn phòng."},{"jp":"先生のお宅に**伺って**もよろしいですか。","vi":"Em đến thăm nhà thầy có được không ạ?"}],
  "582": [{"jp":"学校へ行く**途中で**、雨が降ってきました。","vi":"Đang trên đường đến trường thì trời đổ mưa."},{"jp":"映画がつまらなかったので、**途中で**帰りました。","vi":"Phim chán quá nên tôi về giữa chừng."}],
  "583": [{"jp":"自転車が車に**ぶつかりました**。","vi":"Xe đạp đã đâm vào ô tô."},{"jp":"前を見ないで歩いていたら、人に**ぶつかって**しまった。","vi":"Đi không nhìn phía trước nên tôi đã va vào người khác."}],
  "584": [{"jp":"人気のラーメン屋の前に、人がたくさん**並んで**います。","vi":"Có rất nhiều người đang xếp hàng trước quán ramen nổi tiếng."},{"jp":"子どもたちは背の順に**並びました**。","vi":"Bọn trẻ đã xếp hàng theo thứ tự chiều cao."}],
  "585": [{"jp":"**大人**は1,000円、子どもは500円です。","vi":"Người lớn 1.000 yên, trẻ em 500 yên."},{"jp":"早く**大人**になりたいです。","vi":"Tôi muốn nhanh chóng trở thành người lớn."}],
  "586": [{"jp":"昔の日本人は**洋服**ではなく、着物を着ていました。","vi":"Người Nhật ngày xưa không mặc âu phục mà mặc kimono."},{"jp":"デパートで**洋服**を買いました。","vi":"Tôi đã mua quần áo ở trung tâm thương mại."}],
  "587": [{"jp":"明治時代に日本は急に**西洋化しました**。","vi":"Vào thời Minh Trị, Nhật Bản đã Tây Âu hóa nhanh chóng."},{"jp":"食生活が**西洋化して**、パンを食べる人が増えた。","vi":"Thói quen ăn uống Tây Âu hóa nên số người ăn bánh mì tăng lên."}],
  "588": [{"jp":"この靴はサイズが**合いません**。","vi":"Đôi giày này không vừa cỡ."},{"jp":"白いシャツには青いネクタイが**合う**と思います。","vi":"Tôi nghĩ áo sơ mi trắng hợp với cà vạt xanh."}],
  "589": [{"jp":"昔はここは海でしたが、**今では**大きな町です。","vi":"Ngày xưa nơi đây là biển, nhưng bây giờ thì là một thành phố lớn."},{"jp":"最初は日本の食べ物が苦手でしたが、**今では**大好きです。","vi":"Lúc đầu tôi không ăn được đồ Nhật, nhưng bây giờ thì rất thích."}],
  "590": [{"jp":"1月に**成人式**に出ました。","vi":"Tháng 1 tôi đã dự lễ trưởng thành."},{"jp":"**成人式**の日、女の人はきれいな着物を着ます。","vi":"Vào ngày lễ trưởng thành, phụ nữ mặc kimono đẹp."}],
  "591": [{"jp":"教室にいる学生の数を**数えて**ください。","vi":"Hãy đếm số học sinh trong lớp."},{"jp":"眠れないとき、羊を**数えます**。","vi":"Khi không ngủ được, tôi đếm cừu."}],
  "592": [{"jp":"熱があるかもしれないので、体温を**測りました**。","vi":"Có thể bị sốt nên tôi đã đo nhiệt độ cơ thể."},{"jp":"荷物の重さを**量って**ください。","vi":"Hãy cân trọng lượng hành lý."}],
  "593": [{"jp":"出かける前に、窓が閉まっているか**確かめました**。","vi":"Trước khi ra ngoài, tôi đã kiểm tra xem cửa sổ đã đóng chưa."},{"jp":"電車の時間をインターネットで**確かめて**ください。","vi":"Hãy kiểm tra giờ tàu trên mạng."}],
  "594": [{"jp":"二人は趣味が**合う**ので、すぐ仲良くなりました。","vi":"Hai người hợp sở thích nên đã nhanh chóng thân nhau."},{"jp":"この料理は日本のお酒によく**合います**。","vi":"Món ăn này rất hợp với rượu Nhật."}],
  "595": [{"jp":"明日の朝7時に**出発します**。","vi":"Sáng mai chúng ta xuất phát lúc 7 giờ."},{"jp":"バスはもう**出発して**しまいました。","vi":"Xe buýt đã xuất phát mất rồi."}],
  "596": [{"jp":"飛行機は予定通り空港に**到着しました**。","vi":"Máy bay đã đến sân bay đúng theo dự định."},{"jp":"駅に**到着したら**、電話してください。","vi":"Khi đến ga thì hãy gọi điện cho tôi."}],
  "597": [{"jp":"昨日はお酒を飲みすぎて、**酔って**しまいました。","vi":"Hôm qua tôi uống quá nhiều rượu nên đã say."},{"jp":"車に乗ると、すぐ**酔います**。","vi":"Hễ lên ô tô là tôi say xe ngay."}],
  "598": [{"jp":"この川は深くて**危険**ですから、泳がないでください。","vi":"Con sông này sâu và nguy hiểm nên đừng bơi."},{"jp":"**危険な**場所に子どもを行かせてはいけません。","vi":"Không được để trẻ con đi đến nơi nguy hiểm."}],
  "599": [{"jp":"海外に行くとき、パスポートが**必要**です。","vi":"Khi đi nước ngoài cần có hộ chiếu."},{"jp":"**必要な**ものをメモしてから買い物に行きます。","vi":"Tôi ghi lại những thứ cần thiết rồi mới đi mua sắm."}],
  "600": [{"jp":"いつか**宇宙**へ行ってみたいです。","vi":"Một ngày nào đó tôi muốn thử bay vào vũ trụ."},{"jp":"子どものころ、**宇宙**の本をよく読みました。","vi":"Hồi nhỏ tôi hay đọc sách về vũ trụ."}],
  "601": [{"jp":"**地球**は太陽の周りを回っています。","vi":"Trái đất quay quanh Mặt trời."},{"jp":"**地球**を大切にしましょう。","vi":"Hãy cùng bảo vệ Trái đất."}],
  "602": [{"jp":"12月に会社の**忘年会**があります。","vi":"Tháng 12 có tiệc tất niên của công ty."},{"jp":"**忘年会**で一年の苦労を忘れましょう。","vi":"Hãy quên đi những vất vả của một năm trong tiệc tất niên nhé."}],
  "603": [{"jp":"1月10日に**新年会**をします。","vi":"Ngày 10 tháng 1 chúng ta sẽ tổ chức tiệc tân niên."},{"jp":"**新年会**で今年の目標を話しました。","vi":"Ở tiệc tân niên tôi đã nói về mục tiêu năm nay."}],
  "604": [{"jp":"パーティーの後、**二次会**でカラオケに行きました。","vi":"Sau bữa tiệc, chúng tôi đi tăng hai hát karaoke."},{"jp":"明日は早いので、**二次会**には行きません。","vi":"Mai tôi phải dậy sớm nên không đi tăng hai."}],
  "605": [{"jp":"来月、テニスの**大会**に出ます。","vi":"Tháng sau tôi sẽ tham gia giải quần vợt."},{"jp":"日本語のスピーチ**大会**で優勝しました。","vi":"Tôi đã vô địch cuộc thi hùng biện tiếng Nhật."}],
  "606": [{"jp":"封筒の**表**に住所を書いてください。","vi":"Hãy viết địa chỉ ở mặt trước phong bì."},{"jp":"この紙は**表**と裏の色が違います。","vi":"Tờ giấy này mặt trước và mặt sau khác màu."}],
  "607": [{"jp":"家の**裏**に小さい庭があります。","vi":"Phía sau nhà có một khu vườn nhỏ."},{"jp":"紙の**裏**にも名前を書いてください。","vi":"Hãy viết tên cả ở mặt sau tờ giấy."}],
  "608": [{"jp":"友達にメールを送りましたが、まだ**返事**が来ません。","vi":"Tôi đã gửi email cho bạn nhưng vẫn chưa có hồi âm."},{"jp":"名前を呼ばれたら、大きい声で**返事**をしてください。","vi":"Khi được gọi tên thì hãy trả lời to lên."}],
  "609": [{"jp":"その話は**本当**ですか。","vi":"Câu chuyện đó có thật không?"},{"jp":"**本当**にありがとうございました。","vi":"Thật sự cảm ơn anh rất nhiều."}],
  "610": [{"jp":"この文には**間違い**が三つあります。","vi":"Câu này có ba lỗi sai."},{"jp":"電話番号に**間違い**がないか、もう一度見てください。","vi":"Hãy xem lại một lần nữa xem số điện thoại có sai không."}],
  "611": [{"jp":"転んで、足に**傷**ができました。","vi":"Tôi bị ngã nên chân bị thương."},{"jp":"新しい車に**傷**をつけてしまいました。","vi":"Tôi đã làm xước chiếc ô tô mới."}],
  "612": [{"jp":"この川の**長さ**は何キロですか。","vi":"Con sông này dài bao nhiêu km?"},{"jp":"スカートの**長さ**を少し短くしてください。","vi":"Hãy làm chiều dài váy ngắn bớt một chút."}],
  "613": [{"jp":"この荷物の**重さ**は5キロです。","vi":"Hành lý này nặng 5 kg."},{"jp":"飛行機に乗る前に、スーツケースの**重さ**を量ります。","vi":"Trước khi lên máy bay, người ta cân trọng lượng va li."}],
  "614": [{"jp":"富士山の**高さ**は3,776メートルです。","vi":"Núi Phú Sĩ cao 3.776 mét."},{"jp":"この机は**高さ**がちょうどいいです。","vi":"Cái bàn này có chiều cao vừa phải."}],
  "615": [{"jp":"箱の**大きさ**はどのくらいですか。","vi":"Cái hộp to cỡ nào?"},{"jp":"同じ**大きさ**の紙を10枚ください。","vi":"Cho tôi 10 tờ giấy cùng kích thước."}],
  "616": [{"jp":"私はJAL123**便**で東京へ行きます。","vi":"Tôi đi Tokyo bằng chuyến bay JAL123."},{"jp":"大阪行きの5時の**便**は満席です。","vi":"Chuyến bay 5 giờ đi Osaka đã kín chỗ."}],
  "617": [{"jp":"台風5**号**が九州に近づいています。","vi":"Cơn bão số 5 đang tiến gần đến Kyushu."},{"jp":"新幹線のぞみ20**号**で京都へ行きます。","vi":"Tôi đi Kyoto bằng tàu Shinkansen Nozomi số 20."}],
  "618": [{"jp":"りんごを3**個**買いました。","vi":"Tôi đã mua 3 quả táo."},{"jp":"卵を2**個**使って、ケーキを作ります。","vi":"Tôi dùng 2 quả trứng để làm bánh."}],
  "619": [{"jp":"鉛筆を5**本**ください。","vi":"Cho tôi 5 cây bút chì."},{"jp":"ビールを2**本**買ってきてください。","vi":"Hãy mua giúp tôi 2 chai bia."}],
  "620": [{"jp":"毎朝コーヒーを1**杯**飲みます。","vi":"Mỗi sáng tôi uống 1 cốc cà phê."},{"jp":"ご飯をもう1**杯**ください。","vi":"Cho tôi thêm 1 bát cơm nữa."}],
  "621": [{"jp":"駅から家まで2**キロ**ぐらいです。","vi":"Từ ga đến nhà khoảng 2 km."},{"jp":"米を5**キロ**買いました。","vi":"Tôi đã mua 5 kg gạo."}],
  "622": [{"jp":"砂糖を100**グラム**入れてください。","vi":"Hãy cho vào 100 gam đường."},{"jp":"この手紙は50**グラム**あります。","vi":"Lá thư này nặng 50 gam."}],
  "623": [{"jp":"私の身長は165**センチ**です。","vi":"Chiều cao của tôi là 165 cm."},{"jp":"髪を5**センチ**切ってください。","vi":"Hãy cắt tóc giúp tôi 5 cm."}],
  "624": [{"jp":"昨日は雨が50**ミリ**降りました。","vi":"Hôm qua mưa 50 mm."},{"jp":"この紙の厚さは1**ミリ**もありません。","vi":"Độ dày của tờ giấy này còn chưa đến 1 mm."}],
  "625": [{"jp":"18歳**以上**の人は車の免許が取れます。","vi":"Người từ 18 tuổi trở lên có thể lấy bằng lái ô tô."},{"jp":"このテストは60点**以上**で合格です。","vi":"Bài kiểm tra này từ 60 điểm trở lên là đỗ."}],
  "626": [{"jp":"6歳**以下**の子どもは無料です。","vi":"Trẻ em từ 6 tuổi trở xuống được miễn phí."},{"jp":"明日の気温は0度**以下**になるでしょう。","vi":"Nhiệt độ ngày mai có lẽ sẽ xuống dưới 0 độ."}],
  "627": [{"jp":"「明日の会議は3時から**どうでしょうか**。」「いいですよ。」","vi":"\"Cuộc họp ngày mai bắt đầu từ 3 giờ thì thế nào ạ?\" \"Được đấy.\""},{"jp":"この色は**どうでしょうか**。お客様によく似合いますよ。","vi":"Màu này thì thế nào ạ? Rất hợp với quý khách đấy."}],
  "628": [{"jp":"今学期は**成績**が上がりました。","vi":"Học kỳ này thành tích của tôi đã tăng lên."},{"jp":"兄は学校の**成績**がとてもいいです。","vi":"Anh tôi có thành tích học tập ở trường rất tốt."}],
  "629": [{"jp":"**ところで**、来週の旅行はどうなりましたか。","vi":"À này, chuyến du lịch tuần sau thế nào rồi?"},{"jp":"いい天気ですね。**ところで**、田中さんは元気ですか。","vi":"Trời đẹp nhỉ. Nhân tiện, anh Tanaka có khỏe không?"}],
  "630": [{"jp":"社長は何時に**いらっしゃいます**か。","vi":"Giám đốc mấy giờ sẽ đến ạ?"},{"jp":"先生は今、教室に**いらっしゃいます**。","vi":"Thầy giáo bây giờ đang ở trong lớp học."}],
  "631": [{"jp":"部屋の**様子**を見てきてください。","vi":"Hãy đi xem tình hình trong phòng."},{"jp":"母は元気がない**様子**でした。","vi":"Mẹ tôi có vẻ không khỏe."}],
  "632": [{"jp":"昨日、この町で大きな**事件**がありました。","vi":"Hôm qua ở thị trấn này đã xảy ra một vụ án lớn."},{"jp":"警察は**事件**について調べています。","vi":"Cảnh sát đang điều tra về vụ án."}],
  "633": [{"jp":"戦争で**爆弾**が落とされました。","vi":"Trong chiến tranh bom đã được thả xuống."},{"jp":"空港に**爆弾**があるという電話がありました。","vi":"Có cuộc điện thoại báo rằng có bom ở sân bay."}],
  "634": [{"jp":"トラックに荷物を**積みました**。","vi":"Tôi đã chất hành lý lên xe tải."},{"jp":"机の上に本がたくさん**積んで**あります。","vi":"Trên bàn có rất nhiều sách chất chồng lên."}],
  "635": [{"jp":"**運転者**はシートベルトをしなければなりません。","vi":"Người lái xe phải thắt dây an toàn."},{"jp":"事故の**運転者**はけがをしませんでした。","vi":"Người lái xe trong vụ tai nạn không bị thương."}],
  "636": [{"jp":"私は家族と**離れた**町で働いています。","vi":"Tôi làm việc ở một thành phố xa gia đình."},{"jp":"駅から**離れた**ところに住んでいます。","vi":"Tôi sống ở nơi cách xa nhà ga."}],
  "637": [{"jp":"**急に**雨が降り出しました。","vi":"Đột nhiên trời đổ mưa."},{"jp":"前の車が**急に**止まったので、びっくりしました。","vi":"Xe phía trước đột ngột dừng lại nên tôi giật mình."}],
  "638": [{"jp":"机を窓の近くに**動かして**ください。","vi":"Hãy di chuyển cái bàn đến gần cửa sổ."},{"jp":"毎朝体を**動かす**と、元気になります。","vi":"Mỗi sáng vận động cơ thể thì sẽ khỏe khoắn."}],
  "639": [{"jp":"試験のために**一生懸命**勉強しています。","vi":"Tôi đang học hết sức vì kỳ thi."},{"jp":"父は家族のために**一生懸命**働いています。","vi":"Bố tôi làm việc hết sức vì gia đình."}],
  "640": [{"jp":"警察が**犯人**を捕まえました。","vi":"Cảnh sát đã bắt được thủ phạm."},{"jp":"**犯人**はまだ見つかっていません。","vi":"Thủ phạm vẫn chưa được tìm thấy."}],
  "641": [{"jp":"やっとコンサートのチケットを**手に入れました**。","vi":"Cuối cùng tôi cũng có được vé buổi hòa nhạc."},{"jp":"欲しかった本を古本屋で**手に入れた**。","vi":"Tôi đã có được cuốn sách mình muốn ở tiệm sách cũ."}],
  "642": [{"jp":"10年前に会った人の顔を**今でも**覚えています。","vi":"Đến giờ tôi vẫn nhớ khuôn mặt của người tôi gặp 10 năm trước."},{"jp":"祖父は80歳ですが、**今でも**毎日散歩しています。","vi":"Ông tôi 80 tuổi nhưng đến giờ vẫn đi dạo mỗi ngày."}],
  "643": [{"jp":"田中さんが結婚するという**噂**を聞きました。","vi":"Tôi nghe tin đồn rằng anh Tanaka sắp kết hôn."},{"jp":"**噂**を簡単に信じてはいけません。","vi":"Không được dễ dàng tin vào tin đồn."}],
  "644": [{"jp":"先生に辞書を**頂きました**。","vi":"Tôi đã được thầy giáo tặng cuốn từ điển."},{"jp":"部長からお土産を**頂きました**。","vi":"Tôi đã nhận được quà lưu niệm từ trưởng phòng."}],
  "645": [{"jp":"先生が私に本を**くださいました**。","vi":"Thầy giáo đã tặng tôi một cuốn sách."},{"jp":"社長が結婚のお祝いを**くださいました**。","vi":"Giám đốc đã tặng quà mừng cưới cho tôi."}],
  "646": [{"jp":"毎朝、花に水を**やります**。","vi":"Mỗi sáng tôi tưới nước cho hoa."},{"jp":"弟にお菓子を**やりました**。","vi":"Tôi đã cho em trai bánh kẹo."}],
  "647": [{"jp":"名前を**呼ばれたら**、前に来てください。","vi":"Khi được gọi tên thì hãy lên phía trước."},{"jp":"誕生日パーティーに友達を**呼びました**。","vi":"Tôi đã mời bạn bè đến tiệc sinh nhật."}],
  "648": [{"jp":"電池を**取り替えて**ください。","vi":"Hãy thay pin đi."},{"jp":"このシャツは小さいので、大きいのと**取り替えて**もらいました。","vi":"Chiếc áo này nhỏ nên tôi đã được đổi sang cái lớn hơn."}],
  "649": [{"jp":"山田さんはいつも私に**親切にして**くれます。","vi":"Anh Yamada lúc nào cũng đối xử tốt với tôi."},{"jp":"お年寄りには**親切にしましょう**。","vi":"Hãy đối xử tử tế với người già."}],
  "650": [{"jp":"赤ちゃんの笑顔はとても**可愛い**です。","vi":"Nụ cười của em bé rất đáng yêu."},{"jp":"**可愛い**犬を飼っています。","vi":"Tôi đang nuôi một chú chó đáng yêu."}],
  "651": [{"jp":"友達の結婚の**お祝い**に時計を贈りました。","vi":"Tôi đã tặng đồng hồ làm quà mừng đám cưới của bạn."},{"jp":"合格の**お祝い**に、みんなで食事をしました。","vi":"Chúng tôi cùng nhau đi ăn để mừng thi đỗ."}],
  "652": [{"jp":"お正月に祖父から**お年玉**をもらいました。","vi":"Ngày Tết tôi được ông cho tiền mừng tuổi."},{"jp":"**お年玉**で新しいゲームを買いました。","vi":"Tôi đã mua trò chơi mới bằng tiền mừng tuổi."}],
  "653": [{"jp":"入院している友達の**お見舞い**に行きました。","vi":"Tôi đã đi thăm người bạn đang nằm viện."},{"jp":"**お見舞い**に果物を持っていきました。","vi":"Tôi đã mang hoa quả đi làm quà thăm bệnh."}],
  "654": [{"jp":"私は日本の歴史に**興味があります**。","vi":"Tôi có hứng thú với lịch sử Nhật Bản."},{"jp":"弟はスポーツに**興味がありません**。","vi":"Em trai tôi không quan tâm đến thể thao."}],
  "655": [{"jp":"インターネットで**情報**を集めます。","vi":"Tôi thu thập thông tin trên mạng."},{"jp":"旅行の**情報**はこの雑誌に載っています。","vi":"Thông tin du lịch có đăng trên tạp chí này."}],
  "656": [{"jp":"日本語の**文法**は難しいです。","vi":"Ngữ pháp tiếng Nhật khó."},{"jp":"毎日新しい**文法**を一つ覚えています。","vi":"Mỗi ngày tôi học thuộc một mẫu ngữ pháp mới."}],
  "657": [{"jp":"日本語の**発音**を練習しています。","vi":"Tôi đang luyện phát âm tiếng Nhật."},{"jp":"リンさんは**発音**がとてもきれいですね。","vi":"Chị Linh phát âm rất chuẩn nhỉ."}],
  "658": [{"jp":"動物園で**猿**を見ました。","vi":"Tôi đã xem khỉ ở sở thú."},{"jp":"**猿**はバナナが好きです。","vi":"Khỉ thích chuối."}],
  "659": [{"jp":"寝る前に、子どもに**絵本**を読んであげます。","vi":"Trước khi ngủ, tôi đọc sách tranh cho con."},{"jp":"この**絵本**は絵がとてもきれいです。","vi":"Cuốn sách tranh này có tranh vẽ rất đẹp."}],
  "660": [{"jp":"旅行先から家族に**絵はがき**を送りました。","vi":"Tôi đã gửi bưu ảnh cho gia đình từ nơi du lịch."},{"jp":"京都のお寺の**絵はがき**を買いました。","vi":"Tôi đã mua bưu ảnh chùa ở Kyoto."}],
  "661": [{"jp":"寒いので、**靴下**を2枚はいています。","vi":"Trời lạnh nên tôi đi 2 đôi tất."},{"jp":"日本の家では、**靴下**で上がることが多いです。","vi":"Ở nhà người Nhật, thường người ta đi tất bước vào nhà."}],
  "662": [{"jp":"冬は**手袋**をしないと、手が冷たくなります。","vi":"Mùa đông không đeo găng tay thì tay sẽ lạnh cóng."},{"jp":"電車に**手袋**を忘れてしまいました。","vi":"Tôi để quên găng tay trên tàu điện mất rồi."}],
  "663": [{"jp":"彼から**指輪**をもらいました。","vi":"Tôi đã được anh ấy tặng nhẫn."},{"jp":"結婚**指輪**をなくしてしまいました。","vi":"Tôi đã làm mất nhẫn cưới."}],
  "664": [{"jp":"**祖父**は今年85歳になります。","vi":"Ông tôi năm nay 85 tuổi."},{"jp":"**祖父**は昔、先生をしていました。","vi":"Ông tôi ngày xưa làm giáo viên."}],
  "665": [{"jp":"**祖母**は料理がとても上手です。","vi":"Bà tôi nấu ăn rất giỏi."},{"jp":"夏休みに、田舎の**祖母**の家へ行きます。","vi":"Kỳ nghỉ hè tôi về nhà bà ở quê."}],
  "666": [{"jp":"祖父は**孫**と遊ぶのが好きです。","vi":"Ông tôi thích chơi với cháu."},{"jp":"田中さんには**孫**が5人います。","vi":"Bà Tanaka có 5 người cháu."}],
  "667": [{"jp":"**叔父**は東京で医者をしています。","vi":"Chú tôi làm bác sĩ ở Tokyo."},{"jp":"夏休みに**叔父**の家に泊まりました。","vi":"Kỳ nghỉ hè tôi đã ở lại nhà chú."}],
  "668": [{"jp":"田中さんの**叔父さん**は有名な画家だそうです。","vi":"Nghe nói chú của anh Tanaka là họa sĩ nổi tiếng."},{"jp":"近所の**叔父さん**がいつも挨拶してくれます。","vi":"Chú hàng xóm lúc nào cũng chào hỏi tôi."}],
  "669": [{"jp":"**叔母**は毎年誕生日にプレゼントをくれます。","vi":"Năm nào dì tôi cũng tặng quà sinh nhật cho tôi."},{"jp":"母の妹、つまり**叔母**は看護師です。","vi":"Em gái của mẹ, tức là dì tôi, là y tá."}],
  "670": [{"jp":"鈴木さんの**叔母さん**はパン屋をしています。","vi":"Cô của anh Suzuki mở tiệm bánh mì."},{"jp":"店の**叔母さん**がりんごを一つおまけしてくれました。","vi":"Cô bán hàng đã cho tôi thêm một quả táo."}],
  "671": [{"jp":"**一昨年**、日本に来ました。","vi":"Năm kia tôi đến Nhật."},{"jp":"**一昨年**の夏に北海道を旅行しました。","vi":"Mùa hè năm kia tôi đã đi du lịch Hokkaido."}],
  "672": [{"jp":"遅れてしまって、**申し訳ありません**。","vi":"Tôi đến muộn, thành thật xin lỗi."},{"jp":"何度も手伝ってもらって、**申し訳ない**です。","vi":"Được anh giúp nhiều lần, tôi thấy thật áy náy."}],
  "673": [{"jp":"旅行の間、隣の人に猫を**預かって**もらいました。","vi":"Trong lúc đi du lịch, tôi nhờ hàng xóm trông giúp con mèo."},{"jp":"ホテルのフロントで荷物を**預かって**くれます。","vi":"Quầy lễ tân khách sạn sẽ giữ hành lý giúp."}],
  "674": [{"jp":"**先日**はありがとうございました。","vi":"Cảm ơn anh về hôm trước."},{"jp":"**先日**、駅で昔の友達に会いました。","vi":"Hôm trước tôi đã gặp lại người bạn cũ ở ga."}],
  "675": [{"jp":"手伝ってくれて、本当に**助かりました**。","vi":"Cảm ơn anh đã giúp, đỡ cho tôi quá."},{"jp":"事故にあったが、運転者は**助かった**そうです。","vi":"Nghe nói gặp tai nạn nhưng người lái xe đã được cứu sống."}],
  "676": [{"jp":"祖母はよく**昔話**をしてくれました。","vi":"Bà tôi thường kể truyện cổ tích cho tôi."},{"jp":"「桃太郎」は有名な**昔話**です。","vi":"\"Momotaro\" là một truyện cổ tích nổi tiếng."}],
  "677": [{"jp":"**ある**日、男は海へ行きました。","vi":"Một ngày nọ, người đàn ông đi ra biển."},{"jp":"**ある**人から面白い話を聞きました。","vi":"Tôi đã nghe một câu chuyện thú vị từ một người nọ."}],
  "678": [{"jp":"店の前に知らない**男**が立っています。","vi":"Có một người đàn ông lạ đang đứng trước cửa hàng."},{"jp":"その**男**は黒い帽子をかぶっていました。","vi":"Người đàn ông đó đội mũ màu đen."}],
  "679": [{"jp":"弱い子を**虐めて**はいけません。","vi":"Không được bắt nạt đứa trẻ yếu."},{"jp":"子どもたちが亀を**虐めて**いました。","vi":"Bọn trẻ đang bắt nạt con rùa."}],
  "680": [{"jp":"**亀**はゆっくり歩きます。","vi":"Rùa đi chậm rãi."},{"jp":"浜で大きな**亀**を見ました。","vi":"Tôi đã thấy một con rùa lớn trên bãi biển."}],
  "681": [{"jp":"困っている人を**助けましょう**。","vi":"Hãy giúp đỡ người đang gặp khó khăn."},{"jp":"川に落ちた子どもを**助けました**。","vi":"Tôi đã cứu đứa trẻ bị rơi xuống sông."}],
  "682": [{"jp":"週末、姫路の**お城**を見に行きました。","vi":"Cuối tuần tôi đã đi xem lâu đài Himeji."},{"jp":"昔、この**お城**には王様が住んでいました。","vi":"Ngày xưa, có một vị vua sống trong lâu đài này."}],
  "683": [{"jp":"**お姫様**は王子様と結婚しました。","vi":"Công chúa đã kết hôn với hoàng tử."},{"jp":"娘は**お姫様**のドレスを着て喜んでいます。","vi":"Con gái tôi mặc váy công chúa và rất vui sướng."}],
  "684": [{"jp":"子どもたちは公園で**楽しく**遊んでいます。","vi":"Bọn trẻ đang chơi vui vẻ trong công viên."},{"jp":"昨日のパーティーでは、みんなと**楽しく**話しました。","vi":"Ở bữa tiệc hôm qua tôi đã nói chuyện vui vẻ với mọi người."}],
  "685": [{"jp":"私は家族と一緒に東京で**暮らして**います。","vi":"Tôi đang sống cùng gia đình ở Tokyo."},{"jp":"二人は結婚して、幸せに**暮らしました**。","vi":"Hai người kết hôn và sống hạnh phúc."}],
  "686": [{"jp":"船から**陸**が見えてきました。","vi":"Từ trên thuyền đã bắt đầu nhìn thấy đất liền."},{"jp":"カエルは水の中でも**陸**の上でも生活できます。","vi":"Ếch có thể sống cả dưới nước lẫn trên cạn."}],
  "687": [{"jp":"ボタンを押しました。**すると**、ドアが開きました。","vi":"Tôi nhấn nút. Thế rồi cánh cửa mở ra."},{"jp":"箱を開けました。**すると**、白い煙が出てきました。","vi":"Tôi mở chiếc hộp. Thế rồi khói trắng bốc ra."}],
  "688": [{"jp":"台所から**煙**が出ています。","vi":"Khói đang bốc ra từ nhà bếp."},{"jp":"タバコの**煙**が嫌いです。","vi":"Tôi ghét khói thuốc lá."}],
  "689": [{"jp":"雪が降って、町が**真っ白**になりました。","vi":"Tuyết rơi khiến cả thị trấn trắng xóa."},{"jp":"**真っ白な**シャツを着て、面接に行きました。","vi":"Tôi mặc áo sơ mi trắng tinh đi phỏng vấn."}],
  "690": [{"jp":"この箱の**中身**は何ですか。","vi":"Bên trong cái hộp này là gì?"},{"jp":"財布の**中身**を全部出してください。","vi":"Hãy lấy hết đồ bên trong ví ra."}],
  "691": [{"jp":"プレゼントをきれいな紙で**包みました**。","vi":"Tôi đã gói món quà bằng giấy đẹp."},{"jp":"お弁当をハンカチで**包んで**持っていきます。","vi":"Tôi gói hộp cơm bằng khăn tay rồi mang đi."}],
  "692": [{"jp":"お茶を入れるので、お湯を**沸かします**。","vi":"Tôi đun nước sôi để pha trà."},{"jp":"お風呂を**沸かして**おきました。","vi":"Tôi đã đun sẵn nước tắm."}],
  "693": [{"jp":"卵と砂糖をよく**混ぜて**ください。","vi":"Hãy trộn đều trứng và đường."},{"jp":"赤と青の絵の具を**混ぜる**と、紫になります。","vi":"Trộn màu đỏ và màu xanh dương thì sẽ thành màu tím."}],
  "694": [{"jp":"電卓で旅行の費用を**計算しました**。","vi":"Tôi đã tính chi phí chuyến du lịch bằng máy tính bỏ túi."},{"jp":"小学生の息子は**計算**が速いです。","vi":"Con trai tôi học tiểu học tính toán rất nhanh."}],
  "695": [{"jp":"この辞書はとても**厚い**です。","vi":"Cuốn từ điển này rất dày."},{"jp":"寒いので、**厚い**コートを着て出かけました。","vi":"Trời lạnh nên tôi mặc áo khoác dày ra ngoài."}],
  "696": [{"jp":"この本はとても**薄い**です。","vi":"Cuốn sách này rất mỏng."},{"jp":"寒いので、**薄い**シャツでは外に出られません。","vi":"Trời lạnh nên không thể ra ngoài với chiếc áo sơ mi mỏng."}],
  "697": [{"jp":"兄は**弁護士**として働いています。","vi":"Anh trai tôi làm việc với tư cách luật sư."},{"jp":"困ったときは、**弁護士**に相談したほうがいいです。","vi":"Khi gặp rắc rối thì nên hỏi ý kiến luật sư."}],
  "698": [{"jp":"モーツァルトは有名な**音楽家**です。","vi":"Mozart là một nhạc sĩ nổi tiếng."},{"jp":"将来、ピアノを弾く**音楽家**になりたいです。","vi":"Trong tương lai, tôi muốn trở thành nhạc sĩ chơi piano."}],
  "699": [{"jp":"日本の**教育**について調べています。","vi":"Tôi đang tìm hiểu về giáo dục Nhật Bản."},{"jp":"子どもの**教育**にはお金がかかります。","vi":"Việc giáo dục con cái tốn nhiều tiền."}],
  "700": [{"jp":"京都は**歴史**の古い町です。","vi":"Kyoto là thành phố có lịch sử lâu đời."},{"jp":"わたしは日本の**歴史**に興味があります。","vi":"Tôi có hứng thú với lịch sử Nhật Bản."}],
  "701": [{"jp":"外国の**文化**を知るのは楽しいです。","vi":"Tìm hiểu văn hóa nước ngoài thật thú vị."},{"jp":"お茶は日本の大切な**文化**の一つです。","vi":"Trà là một trong những nét văn hóa quan trọng của Nhật Bản."}],
  "702": [{"jp":"大学を出たら、**社会**に出て働きます。","vi":"Ra trường đại học xong, tôi sẽ bước vào xã hội và đi làm."},{"jp":"授業で**社会**の問題について話し合いました。","vi":"Trong giờ học, chúng tôi đã thảo luận về các vấn đề xã hội."}],
  "703": [{"jp":"お酒を飲んで運転するのは**法律**で禁止されています。","vi":"Uống rượu rồi lái xe bị pháp luật cấm."},{"jp":"弁護士は**法律**をよく知っています。","vi":"Luật sư hiểu rõ pháp luật."}],
  "704": [{"jp":"祖父は**戦争**の話をしてくれました。","vi":"Ông tôi đã kể cho tôi nghe chuyện chiến tranh."},{"jp":"**戦争**のない世界になってほしいです。","vi":"Tôi mong thế giới không còn chiến tranh."}],
  "705": [{"jp":"世界が**平和**になるように祈っています。","vi":"Tôi cầu mong thế giới được hòa bình."},{"jp":"この村は**平和**で静かです。","vi":"Ngôi làng này yên bình và tĩnh lặng."}],
  "706": [{"jp":"旅行の**目的**は何ですか。","vi":"Mục đích chuyến đi của bạn là gì?"},{"jp":"日本に来た**目的**は日本語を勉強することです。","vi":"Mục đích tôi đến Nhật là để học tiếng Nhật."}],
  "707": [{"jp":"子どもの**安全**を一番に考えています。","vi":"Chúng tôi đặt sự an toàn của trẻ em lên hàng đầu."},{"jp":"工場では**安全**のためにヘルメットをかぶります。","vi":"Ở nhà máy, người ta đội mũ bảo hộ để đảm bảo an toàn."}],
  "708": [{"jp":"田中さんとはどういう**関係**ですか。","vi":"Bạn có quan hệ thế nào với anh Tanaka?"},{"jp":"日本とベトナムの**関係**はとてもいいです。","vi":"Quan hệ giữa Nhật Bản và Việt Nam rất tốt."}],
  "709": [{"jp":"**薬缶**でお湯を沸かします。","vi":"Tôi đun nước nóng bằng ấm."},{"jp":"**薬缶**がピーッと鳴っていますよ。","vi":"Ấm nước đang kêu tu tu kìa."}],
  "710": [{"jp":"**栓抜き**でビールを開けます。","vi":"Tôi mở chai bia bằng cái mở nắp chai."},{"jp":"すみません、**栓抜き**はどこにありますか。","vi":"Xin lỗi, cái mở nắp chai ở đâu vậy?"}],
  "711": [{"jp":"**缶切り**で缶詰を開けました。","vi":"Tôi đã mở đồ hộp bằng cái mở hộp."},{"jp":"キャンプに**缶切り**を持って行くのを忘れました。","vi":"Tôi quên mang cái mở đồ hộp đi cắm trại."}],
  "712": [{"jp":"地震のときのために、**缶詰**を買っておきます。","vi":"Tôi mua sẵn đồ hộp để phòng khi động đất."},{"jp":"この**缶詰**には魚が入っています。","vi":"Trong hộp này có cá."}],
  "713": [{"jp":"子どものころ、**算盤**を習っていました。","vi":"Hồi nhỏ tôi đã học bàn tính."},{"jp":"祖母は**算盤**で計算するのが速いです。","vi":"Bà tôi tính bằng bàn tính rất nhanh."}],
  "714": [{"jp":"**体温計**で熱を測ってください。","vi":"Hãy đo nhiệt độ bằng nhiệt kế."},{"jp":"薬局で**体温計**を買いました。","vi":"Tôi đã mua nhiệt kế ở hiệu thuốc."}],
  "715": [{"jp":"カレーの**材料**を買いにスーパーへ行きます。","vi":"Tôi đi siêu thị mua nguyên liệu nấu cà ri."},{"jp":"この机は木を**材料**にして作られています。","vi":"Chiếc bàn này được làm từ nguyên liệu gỗ."}],
  "716": [{"jp":"道に大きな**石**が落ちています。","vi":"Trên đường có một hòn đá to."},{"jp":"子どもが川に**石**を投げて遊んでいます。","vi":"Bọn trẻ đang chơi ném đá xuống sông."}],
  "717": [{"jp":"**なぜ**遅れたんですか。","vi":"Tại sao bạn đến muộn?"},{"jp":"空は**なぜ**青いのでしょうか。","vi":"Tại sao bầu trời lại có màu xanh nhỉ?"}],
  "718": [{"jp":"**鍋**でスープを作ります。","vi":"Tôi nấu súp bằng nồi."},{"jp":"冬はみんなで**鍋**を食べるのが楽しいです。","vi":"Mùa đông cùng mọi người ăn lẩu thật vui."}],
  "719": [{"jp":"大きな**丼**にご飯を入れます。","vi":"Tôi cho cơm vào một cái bát tô lớn."},{"jp":"この店の**丼**は量が多くて安いです。","vi":"Cơm tô ở quán này nhiều mà lại rẻ."}],
  "720": [{"jp":"このスーパーは外国の**食品**が多いです。","vi":"Siêu thị này có nhiều thực phẩm nước ngoài."},{"jp":"**食品**の安全はとても大切です。","vi":"An toàn thực phẩm rất quan trọng."}],
  "721": [{"jp":"大学で若い人の生活について**調査**しました。","vi":"Ở trường đại học, chúng tôi đã điều tra về cuộc sống của giới trẻ."},{"jp":"**調査**の結果が発表されました。","vi":"Kết quả điều tra đã được công bố."}],
  "722": [{"jp":"部長**の代わりに**、わたしが会議に出ます。","vi":"Tôi sẽ dự cuộc họp thay trưởng phòng."},{"jp":"砂糖**の代わりに**蜂蜜を入れました。","vi":"Tôi đã cho mật ong thay cho đường."}],
  "723": [{"jp":"このカードは**どこででも**使えます。","vi":"Thẻ này dùng được ở bất cứ đâu."},{"jp":"スマホがあれば、**どこででも**仕事ができます。","vi":"Có điện thoại thông minh thì ở đâu cũng làm việc được."}],
  "724": [{"jp":"昔は小さな村でしたが、**今では**大きな町です。","vi":"Ngày xưa là một ngôi làng nhỏ, nhưng bây giờ thì là một thị trấn lớn."},{"jp":"最初は納豆が嫌いでしたが、**今では**毎日食べています。","vi":"Lúc đầu tôi ghét natto, nhưng bây giờ thì ngày nào cũng ăn."}],
  "725": [{"jp":"最近、外国人の観光客が**増えました**。","vi":"Gần đây khách du lịch nước ngoài đã tăng lên."},{"jp":"体重が3キロも**増えて**しまいました。","vi":"Cân nặng của tôi đã tăng tới 3 ký."}],
  "726": [{"jp":"運動を始めてから、体重が**減りました**。","vi":"Từ khi bắt đầu tập thể dục, cân nặng của tôi đã giảm."},{"jp":"この町では子どもの数が**減って**います。","vi":"Ở thị trấn này số trẻ em đang giảm."}],
  "727": [{"jp":"来月から電気代が**上がる**そうです。","vi":"Nghe nói từ tháng sau tiền điện sẽ tăng."},{"jp":"熱が39度まで**上がりました**。","vi":"Sốt đã lên tới 39 độ."}],
  "728": [{"jp":"夜になって、気温が**下がりました**。","vi":"Về đêm, nhiệt độ đã giảm xuống."},{"jp":"薬を飲んだら、熱が**下がりました**。","vi":"Uống thuốc xong thì đã hạ sốt."}],
  "729": [{"jp":"電話が急に**切れて**しまいました。","vi":"Điện thoại đột nhiên bị ngắt."},{"jp":"この牛乳は賞味期限が**切れて**います。","vi":"Hộp sữa này đã hết hạn sử dụng."}],
  "730": [{"jp":"シャツのボタンが**とれて**しまいました。","vi":"Cúc áo sơ mi bị tuột mất rồi."},{"jp":"鍋の取っ手が**とれて**、使えなくなりました。","vi":"Tay cầm của nồi bị rời ra nên không dùng được nữa."}],
  "731": [{"jp":"木から葉が**落ちて**きました。","vi":"Lá cây đã rơi xuống từ trên cây."},{"jp":"道に財布が**落ちて**いました。","vi":"Có một chiếc ví rơi trên đường."}],
  "732": [{"jp":"冷蔵庫の牛乳が**無くなりました**。","vi":"Sữa trong tủ lạnh đã hết."},{"jp":"大切な指輪が**無くなって**しまいました。","vi":"Chiếc nhẫn quý của tôi bị mất rồi."}],
  "733": [{"jp":"このかばんは**丈夫**で、長く使えます。","vi":"Chiếc cặp này bền nên dùng được lâu."},{"jp":"祖父は90歳ですが、とても**丈夫な**体をしています。","vi":"Ông tôi đã 90 tuổi nhưng cơ thể rất khỏe mạnh."}],
  "734": [{"jp":"この牛乳は**変な**においがします。","vi":"Hộp sữa này có mùi lạ."},{"jp":"彼の話はちょっと**変**だと思います。","vi":"Tôi nghĩ câu chuyện của anh ấy hơi kỳ lạ."}],
  "735": [{"jp":"家族といっしょにいるときが一番**幸せ**です。","vi":"Lúc ở bên gia đình là lúc tôi hạnh phúc nhất."},{"jp":"二人はいつまでも**幸せに**暮らしました。","vi":"Hai người đã sống hạnh phúc mãi mãi."}],
  "736": [{"jp":"この店のラーメンは**うまい**よ。","vi":"Ramen ở quán này ngon lắm đấy."},{"jp":"彼は歌がとても**うまい**です。","vi":"Anh ấy hát rất hay."}],
  "737": [{"jp":"この料理は**不味い**ですね。","vi":"Món này dở nhỉ."},{"jp":"薬は**不味く**ても飲まなければなりません。","vi":"Thuốc dù dở cũng phải uống."}],
  "738": [{"jp":"この映画は**詰まらなかった**です。","vi":"Bộ phim này chán quá."},{"jp":"雨で出かけられなくて、**詰まらない**一日でした。","vi":"Vì mưa không ra ngoài được nên đó là một ngày tẻ nhạt."}],
  "739": [{"jp":"寒いので、**暖房**をつけましょう。","vi":"Lạnh quá, bật máy sưởi lên nhé."},{"jp":"この部屋は**暖房**が効いていて暖かいです。","vi":"Phòng này có máy sưởi chạy tốt nên ấm áp."}],
  "740": [{"jp":"暑いので、**冷房**をつけてもいいですか。","vi":"Nóng quá, tôi bật máy lạnh được không?"},{"jp":"**冷房**が強すぎて、寒いです。","vi":"Máy lạnh mạnh quá nên tôi thấy lạnh."}],
  "741": [{"jp":"姉は**服のセンスがあって**、いつもおしゃれです。","vi":"Chị tôi có gu ăn mặc nên lúc nào cũng sành điệu."},{"jp":"山田さんは**服のセンスがある**ので、買い物についてきてもらいました。","vi":"Anh Yamada có gu ăn mặc nên tôi đã nhờ anh ấy đi mua sắm cùng."}],
  "742": [{"jp":"空が暗くて、**今にも**雨が降りそうです。","vi":"Trời tối sầm, mưa sắp rơi đến nơi rồi."},{"jp":"子どもは**今にも**泣きそうな顔をしていました。","vi":"Đứa bé có vẻ mặt như sắp khóc đến nơi."}],
  "743": [{"jp":"先月、このジムの**会員**になりました。","vi":"Tháng trước tôi đã trở thành thành viên của phòng gym này."},{"jp":"**会員**はチケットが安く買えます。","vi":"Thành viên có thể mua vé rẻ hơn."}],
  "744": [{"jp":"答えとして**適当な**ものを選んでください。","vi":"Hãy chọn đáp án thích hợp."},{"jp":"彼はいつも**適当に**返事をします。","vi":"Anh ấy lúc nào cũng trả lời qua loa."}],
  "745": [{"jp":"ここに名前と**年齢**を書いてください。","vi":"Hãy viết tên và tuổi vào đây."},{"jp":"この仕事は**年齢**に関係なく応募できます。","vi":"Công việc này có thể ứng tuyển không phân biệt tuổi tác."}],
  "746": [{"jp":"今月は**収入**が少なかったです。","vi":"Tháng này thu nhập ít."},{"jp":"新しい仕事は前より**収入**が多いです。","vi":"Công việc mới có thu nhập cao hơn trước."}],
  "747": [{"jp":"この靴はサイズが**ぴったり**です。","vi":"Đôi giày này vừa khít cỡ chân."},{"jp":"約束の時間に**ぴったり**着きました。","vi":"Tôi đã đến đúng giờ hẹn."}],
  "748": [{"jp":"このホテルは駅から近いです。**そのうえ**、安いです。","vi":"Khách sạn này gần ga. Thêm vào đó lại rẻ."},{"jp":"雨が降ってきた。**そのうえ**、風も強くなった。","vi":"Trời đổ mưa. Thêm vào đó gió cũng mạnh lên."}],
  "749": [{"jp":"「ドラえもん」**という**アニメを知っていますか。","vi":"Bạn có biết bộ phim hoạt hình tên là “Doraemon” không?"},{"jp":"田中**という**人から電話がありました。","vi":"Có điện thoại từ một người tên là Tanaka."}],
  "750": [{"jp":"誕生日に**ばら**の花をもらいました。","vi":"Tôi được tặng hoa hồng vào ngày sinh nhật."},{"jp":"庭に赤い**ばら**が咲いています。","vi":"Trong vườn hoa hồng đỏ đang nở."}],
  "751": [{"jp":"赤ちゃんが**泣いて**います。","vi":"Em bé đang khóc."},{"jp":"その映画を見て、思わず**泣いて**しまいました。","vi":"Xem bộ phim đó, tôi đã bất giác bật khóc."}],
  "752": [{"jp":"彼の冗談を聞いて、みんな**笑いました**。","vi":"Nghe câu đùa của anh ấy, mọi người đều cười."},{"jp":"写真を撮りますから、**笑って**ください。","vi":"Tôi chụp ảnh đây, hãy cười lên nào."}],
  "753": [{"jp":"天気がいいので、洗濯物がすぐ**乾きました**。","vi":"Trời đẹp nên đồ giặt khô ngay."},{"jp":"ペンキがまだ**乾いて**いないので、触らないでください。","vi":"Sơn vẫn chưa khô nên đừng chạm vào."}],
  "754": [{"jp":"傘がなくて、服が**濡れて**しまいました。","vi":"Không có ô nên quần áo bị ướt hết."},{"jp":"**濡れた**タオルで顔を拭きました。","vi":"Tôi lau mặt bằng khăn ướt."}],
  "755": [{"jp":"雪の道で**滑って**転びました。","vi":"Tôi bị trượt ngã trên đường tuyết."},{"jp":"床が**滑り**やすいので、気をつけてください。","vi":"Sàn nhà dễ trơn trượt nên hãy cẩn thận."}],
  "756": [{"jp":"昨日、駅の前で事故が**起きました**。","vi":"Hôm qua đã xảy ra tai nạn trước nhà ga."},{"jp":"地震が**起きたら**、机の下に入ってください。","vi":"Nếu xảy ra động đất, hãy chui xuống gầm bàn."}],
  "757": [{"jp":"エアコンの温度を**調節して**ください。","vi":"Hãy điều chỉnh nhiệt độ điều hòa."},{"jp":"この椅子は高さを**調節**できます。","vi":"Chiếc ghế này có thể điều chỉnh độ cao."}],
  "758": [{"jp":"この町は**安全**で住みやすいです。","vi":"Thị trấn này an toàn và dễ sống."},{"jp":"子どもが**安全に**遊べる公園です。","vi":"Đây là công viên trẻ em có thể chơi an toàn."}],
  "759": [{"jp":"店員さんが**丁寧に**説明してくれました。","vi":"Nhân viên cửa hàng đã giải thích cho tôi một cách lịch sự, chu đáo."},{"jp":"目上の人には**丁寧な**言葉を使います。","vi":"Với người bề trên thì dùng lời lẽ lịch sự."}],
  "760": [{"jp":"玉ねぎを**細かく**切ってください。","vi":"Hãy thái nhỏ hành tây."},{"jp":"彼は**細かい**ことによく気がつきます。","vi":"Anh ấy hay để ý đến những điều nhỏ nhặt."}],
  "761": [{"jp":"このコーヒーは**濃い**ですね。","vi":"Cà phê này đậm nhỉ."},{"jp":"彼は**濃い**青のシャツを着ています。","vi":"Anh ấy mặc chiếc áo sơ mi màu xanh đậm."}],
  "762": [{"jp":"このスープは味が**薄い**です。","vi":"Món súp này vị nhạt."},{"jp":"私は**薄い**お茶が好きです。","vi":"Tôi thích trà loãng."}],
  "763": [{"jp":"山の**空気**はきれいです。","vi":"Không khí trên núi trong lành."},{"jp":"窓を開けて、**空気**を入れ替えましょう。","vi":"Hãy mở cửa sổ để thay đổi không khí."}],
  "764": [{"jp":"彼女の目から**涙**が流れました。","vi":"Nước mắt chảy ra từ mắt cô ấy."},{"jp":"うれしくて**涙**が出ました。","vi":"Tôi vui đến mức trào nước mắt."}],
  "765": [{"jp":"私は**和食**が好きで、よくお寿司を食べます。","vi":"Tôi thích món Nhật nên hay ăn sushi."},{"jp":"**和食**は体にいいと言われています。","vi":"Người ta nói món ăn Nhật tốt cho sức khỏe."}],
  "766": [{"jp":"朝ご飯はいつも**洋食**で、パンとコーヒーです。","vi":"Bữa sáng của tôi luôn là đồ Âu, gồm bánh mì và cà phê."},{"jp":"この店はハンバーグやステーキなどの**洋食**が人気です。","vi":"Quán này nổi tiếng với các món Âu như hamburger, bít tết."}],
  "767": [{"jp":"今日の**おかず**は魚です。","vi":"Thức ăn hôm nay là cá."},{"jp":"母はお弁当の**おかず**を作っています。","vi":"Mẹ đang làm thức ăn cho hộp cơm."}],
  "768": [{"jp":"この店のカレーは**量**が多いです。","vi":"Cà ri ở quán này nhiều (lượng lớn)."},{"jp":"今年は雨の**量**が去年より少ないです。","vi":"Năm nay lượng mưa ít hơn năm ngoái."}],
  "769": [{"jp":"東京の家賃は私の町の**2倍**です。","vi":"Tiền thuê nhà ở Tokyo gấp 2 lần ở thị trấn của tôi."},{"jp":"練習の時間を**3倍**に増やしました。","vi":"Tôi đã tăng thời gian luyện tập lên gấp 3 lần."}],
  "770": [{"jp":"ケーキを**半分**に切りました。","vi":"Tôi đã cắt chiếc bánh làm đôi."},{"jp":"宿題はまだ**半分**しか終わっていません。","vi":"Bài tập mới chỉ xong được một nửa."}],
  "771": [{"jp":"冬の服を**箪笥**にしまいました。","vi":"Tôi đã cất quần áo mùa đông vào tủ."},{"jp":"この**箪笥**は祖母からもらったものです。","vi":"Chiếc tủ quần áo này là bà tôi cho."}],
  "772": [{"jp":"雨が降りそうだから、**洗濯物**を中に入れてね。","vi":"Trời sắp mưa rồi, mang đồ giặt vào trong nhé."},{"jp":"**洗濯物**がたくさんたまっています。","vi":"Đồ giặt đã dồn lại rất nhiều."}],
  "773": [{"jp":"会社を休んだ**理由**を説明してください。","vi":"Hãy giải thích lý do bạn nghỉ làm."},{"jp":"日本を選んだ**理由**は何ですか。","vi":"Lý do bạn chọn Nhật Bản là gì?"}],
  "774": [{"jp":"子どもは歯医者に行くのを**嫌がります**。","vi":"Trẻ con không thích đi nha sĩ."},{"jp":"猫はお風呂を**嫌がって**逃げました。","vi":"Con mèo ghét tắm nên đã chạy trốn."}],
  "775": [{"jp":"料理は**順序**を守って作りましょう。","vi":"Hãy nấu ăn theo đúng thứ tự các bước."},{"jp":"**順序**が違うと、うまくいきません。","vi":"Nếu sai thứ tự thì sẽ không suôn sẻ."}],
  "776": [{"jp":"この**表現**は日本語の会話でよく使います。","vi":"Cách diễn đạt này thường được dùng trong hội thoại tiếng Nhật."},{"jp":"気持ちを言葉で**表現**するのは難しいです。","vi":"Diễn đạt cảm xúc bằng lời thật khó."}],
  "777": [{"jp":"果物、**例えば**りんごやみかんが好きです。","vi":"Tôi thích hoa quả, ví dụ như táo và quýt."},{"jp":"日本には有名な山がたくさんあります。**例えば**、富士山です。","vi":"Nhật Bản có nhiều ngọn núi nổi tiếng. Ví dụ như núi Phú Sĩ."}],
  "778": [{"jp":"駅で友達と**別れて**、家に帰りました。","vi":"Tôi chia tay bạn ở ga rồi về nhà."},{"jp":"姉は恋人と**別れて**、元気がありません。","vi":"Chị tôi chia tay người yêu nên trông buồn bã."}],
  "779": [{"jp":"**これら**の本は全部図書館のものです。","vi":"Những cuốn sách này đều là của thư viện."},{"jp":"**これら**の問題について話し合いましょう。","vi":"Chúng ta hãy thảo luận về những vấn đề này."}],
  "780": [{"jp":"日本では4は**縁起が悪い**数字だと言われています。","vi":"Ở Nhật, số 4 được cho là con số không may."},{"jp":"黒い猫が前を通ると**縁起が悪い**と言う人がいます。","vi":"Có người nói mèo đen đi ngang qua trước mặt là điềm xui."}],
  "781": [{"jp":"約束を忘れて、友達に**謝りました**。","vi":"Tôi quên lời hẹn nên đã xin lỗi bạn."},{"jp":"悪いことをしたら、すぐ**謝った**ほうがいいです。","vi":"Nếu làm điều sai thì nên xin lỗi ngay."}],
  "782": [{"jp":"昨日、交通事故に**遭いました**。","vi":"Hôm qua tôi đã gặp tai nạn giao thông."},{"jp":"旅行の途中で大雨に**遭って**、大変でした。","vi":"Giữa chuyến đi tôi gặp mưa to, thật vất vả."}],
  "783": [{"jp":"私はあなたの言葉を**信じます**。","vi":"Tôi tin lời bạn."},{"jp":"子どものころ、サンタクロースを**信じて**いました。","vi":"Hồi nhỏ tôi đã tin có ông già Noel."}],
  "784": [{"jp":"旅行の荷物を**用意**しました。","vi":"Tôi đã chuẩn bị hành lý cho chuyến đi."},{"jp":"会議の資料を**用意して**おいてください。","vi":"Hãy chuẩn bị sẵn tài liệu cho cuộc họp."}],
  "785": [{"jp":"**保証書**があれば、無料で修理できます。","vi":"Nếu có giấy bảo hành thì được sửa miễn phí."},{"jp":"冷蔵庫を買ったとき、**保証書**をもらいました。","vi":"Khi mua tủ lạnh, tôi được nhận giấy bảo hành."}],
  "786": [{"jp":"すみません、**領収書**をください。","vi":"Xin lỗi, cho tôi xin hóa đơn."},{"jp":"タクシー代の**領収書**を会社に出しました。","vi":"Tôi đã nộp hóa đơn tiền taxi cho công ty."}],
  "787": [{"jp":"母の日に**贈り物**をしました。","vi":"Tôi đã tặng quà vào Ngày của Mẹ."},{"jp":"この時計は父からの**贈り物**です。","vi":"Chiếc đồng hồ này là quà của bố tôi."}],
  "788": [{"jp":"わからないことは受付の**係**に聞いてください。","vi":"Điều gì không hiểu hãy hỏi người phụ trách lễ tân."},{"jp":"私はパーティーで飲み物の**係**です。","vi":"Tôi là người phụ trách đồ uống trong bữa tiệc."}],
  "789": [{"jp":"雨で試合が**中止**になりました。","vi":"Trận đấu đã bị hủy vì mưa."},{"jp":"台風が来るので、旅行を**中止**しました。","vi":"Vì bão đến nên chúng tôi đã hủy chuyến du lịch."}],
  "790": [{"jp":"テストで100**点**を取りました。","vi":"Tôi đã được 100 điểm bài kiểm tra."},{"jp":"彼の意見には賛成できない**点**があります。","vi":"Trong ý kiến của anh ấy có điểm tôi không thể tán thành."}],
  "791": [{"jp":"1万円**札**で払いました。","vi":"Tôi đã trả bằng tờ 10.000 yên."},{"jp":"財布に**お札**が入っていません。","vi":"Trong ví không có tờ tiền giấy nào."}],
  "792": [{"jp":"毎日**ちゃんと**朝ご飯を食べています。","vi":"Ngày nào tôi cũng ăn sáng đầy đủ."},{"jp":"出かける前に、ドアのかぎを**ちゃんと**閉めてね。","vi":"Trước khi ra ngoài, nhớ khóa cửa cẩn thận nhé."}],
  "793": [{"jp":"**急に**雨が降ってきました。","vi":"Trời đột nhiên đổ mưa."},{"jp":"前の車が**急に**止まったので、びっくりしました。","vi":"Xe phía trước dừng đột ngột nên tôi giật mình."}],
  "794": [{"jp":"私の発表は**以上です**。ありがとうございました。","vi":"Bài thuyết trình của tôi xin hết. Xin cảm ơn."},{"jp":"連絡は**以上です**。何か質問はありますか。","vi":"Thông báo xin hết. Có ai có câu hỏi gì không?"}],
  "795": [{"jp":"わからないことは**係員**に聞いてください。","vi":"Điều gì không hiểu hãy hỏi nhân viên."},{"jp":"駅の**係員**が道を教えてくれました。","vi":"Nhân viên nhà ga đã chỉ đường cho tôi."}],
  "796": [{"jp":"マラソン大会で**3位**になりました。","vi":"Tôi đã về thứ 3 trong cuộc thi marathon."},{"jp":"この歌は今週のランキングで**1位**です。","vi":"Bài hát này đứng thứ nhất trên bảng xếp hạng tuần này."}],
  "797": [{"jp":"私たちのチームが**優勝しました**。","vi":"Đội chúng tôi đã vô địch."},{"jp":"彼はテニスの大会で**優勝して**、有名になりました。","vi":"Anh ấy vô địch giải quần vợt và trở nên nổi tiếng."}],
  "798": [{"jp":"何か**悩み**があったら、相談してください。","vi":"Nếu có điều gì phiền muộn thì hãy tâm sự với tôi."},{"jp":"最近の私の**悩み**は、よく眠れないことです。","vi":"Nỗi lo gần đây của tôi là không ngủ ngon được."}],
  "799": [{"jp":"**目覚まし**を6時にセットしました。","vi":"Tôi đã đặt đồng hồ báo thức lúc 6 giờ."},{"jp":"**目覚まし**が鳴っても起きられませんでした。","vi":"Đồng hồ báo thức reo mà tôi vẫn không dậy được."}],
  "800": [{"jp":"赤ちゃんがぐっすり**眠って**います。","vi":"Em bé đang ngủ say."},{"jp":"昨日は8時間**眠りました**。","vi":"Hôm qua tôi đã ngủ 8 tiếng."}],
  "801": [{"jp":"今朝は5時に**目が覚めました**。","vi":"Sáng nay tôi tỉnh giấc lúc 5 giờ."},{"jp":"外の大きな音で**目が覚めて**しまいました。","vi":"Tôi bị tỉnh giấc vì tiếng động lớn bên ngoài."}],
  "802": [{"jp":"兄は**大学生**で、東京に住んでいます。","vi":"Anh trai tôi là sinh viên đại học, sống ở Tokyo."},{"jp":"**大学生**になったら、アルバイトをしたいです。","vi":"Khi trở thành sinh viên đại học, tôi muốn đi làm thêm."}],
  "803": [{"jp":"アンケートへの**回答**、ありがとうございました。","vi":"Cảm ơn bạn đã trả lời phiếu khảo sát."},{"jp":"質問への**回答**は明日までにお願いします。","vi":"Vui lòng gửi câu trả lời cho câu hỏi trước ngày mai."}],
  "804": [{"jp":"授業の終わりのベルが**鳴りました**。","vi":"Chuông hết giờ học đã reo."},{"jp":"夜中に電話が**鳴って**、びっくりしました。","vi":"Nửa đêm điện thoại reo làm tôi giật mình."}],
  "805": [{"jp":"雨が降っています。**それでも**、試合は行われます。","vi":"Trời đang mưa. Tuy thế, trận đấu vẫn được tổ chức."},{"jp":"何度も失敗した。**それでも**、彼はあきらめなかった。","vi":"Thất bại bao nhiêu lần. Mặc dù thế, anh ấy vẫn không bỏ cuộc."}],
  "806": [{"jp":"毎朝パンを**焼いて**食べます。","vi":"Sáng nào tôi cũng nướng bánh mì để ăn."},{"jp":"庭で肉を**焼いて**、バーベキューをしました。","vi":"Chúng tôi nướng thịt trong vườn, tổ chức tiệc nướng."}],
  "807": [{"jp":"この書類を部長に**渡して**ください。","vi":"Hãy đưa tài liệu này cho trưởng phòng."},{"jp":"卒業式で先生に花を**渡しました**。","vi":"Tôi đã tặng hoa cho thầy trong lễ tốt nghiệp."}],
  "808": [{"jp":"父は毎晩7時ごろ**帰って来ます**。","vi":"Bố tôi tối nào cũng về nhà khoảng 7 giờ."},{"jp":"夏休みに娘が留学先から**帰って来ました**。","vi":"Kỳ nghỉ hè, con gái tôi đã từ nơi du học trở về."}],
  "809": [{"jp":"次の電車は10時に**出ます**。","vi":"Chuyến tàu tiếp theo khởi hành lúc 10 giờ."},{"jp":"急いだけど、バスはもう**出て**しまいました。","vi":"Tôi đã vội nhưng xe buýt đã chạy mất rồi."}],
  "810": [{"jp":"昨日友達の家に行きましたが、**留守**でした。","vi":"Hôm qua tôi đến nhà bạn nhưng bạn vắng nhà."},{"jp":"**留守**の間に荷物が届いていました。","vi":"Trong lúc tôi vắng nhà thì có hàng gửi đến."}],
  "811": [{"jp":"実家から**宅配便**で野菜が届きました。","vi":"Rau từ quê được gửi đến bằng dịch vụ giao hàng tận nhà."},{"jp":"この荷物を**宅配便**で送りたいんですが。","vi":"Tôi muốn gửi kiện hàng này bằng dịch vụ giao hàng tận nhà."}],
  "812": [{"jp":"火事の**原因**はたばこでした。","vi":"Nguyên nhân vụ cháy là thuốc lá."},{"jp":"警察が事故の**原因**を調べています。","vi":"Cảnh sát đang điều tra nguyên nhân vụ tai nạn."}],
  "813": [{"jp":"病院で**注射**をしてもらいました。","vi":"Tôi đã được tiêm ở bệnh viện."},{"jp":"弟は**注射**が大嫌いです。","vi":"Em trai tôi rất ghét tiêm."}],
  "814": [{"jp":"風邪で**食欲**がありません。","vi":"Bị cảm nên tôi không thấy thèm ăn."},{"jp":"秋は**食欲**の季節だと言われます。","vi":"Người ta nói mùa thu là mùa ăn ngon miệng."}],
  "815": [{"jp":"先生**の所**へ質問に行きました。","vi":"Tôi đã đến chỗ thầy để hỏi bài."},{"jp":"週末は友達**の所**に泊まります。","vi":"Cuối tuần tôi ngủ lại chỗ bạn."}],
  "816": [{"jp":"**丁度**12時に着きました。","vi":"Tôi đến đúng 12 giờ."},{"jp":"このシャツはサイズが**丁度**いいです。","vi":"Chiếc áo này vừa đúng cỡ."}],
  "817": [{"jp":"**たった今**、家に着いたところです。","vi":"Tôi vừa mới về đến nhà."},{"jp":"田中さんなら、**たった今**帰りましたよ。","vi":"Anh Tanaka thì vừa mới về rồi đấy."}],
  "818": [{"jp":"すみません、**今いいでしょうか**。ちょっと相談したいことがあるんですが。","vi":"Xin lỗi, bây giờ có tiện không ạ? Tôi có chuyện muốn bàn một chút."},{"jp":"部長、**今いいでしょうか**。会議の資料について聞きたいんですが。","vi":"Thưa trưởng phòng, bây giờ có tiện không ạ? Tôi muốn hỏi về tài liệu cuộc họp."}],
  "819": [{"jp":"体の**具合**はどうですか。","vi":"Sức khỏe của bạn thế nào rồi?"},{"jp":"パソコンの**具合**が悪くて、動きません。","vi":"Máy tính có vấn đề nên không chạy được."}],
  "820": [{"jp":"今、駅に**向かって**います。","vi":"Bây giờ tôi đang đi về phía nhà ga."},{"jp":"飛行機は東京へ**向かいました**。","vi":"Máy bay đã bay về hướng Tokyo."}],
  "821": [{"jp":"**お待たせしました**。コーヒーです。","vi":"Xin lỗi đã để quý khách đợi. Cà phê của quý khách đây."},{"jp":"遅くなってすみません。**お待たせしました**。","vi":"Xin lỗi tôi đến muộn. Để bạn phải đợi rồi."}],
  "822": [{"jp":"彼はコンピューターの**知識**が豊富です。","vi":"Anh ấy có kiến thức phong phú về máy tính."},{"jp":"本をたくさん読んで、**知識**を増やしたいです。","vi":"Tôi muốn đọc nhiều sách để tăng thêm tri thức."}],
  "823": [{"jp":"図書館は知識の**宝庫**です。","vi":"Thư viện là kho báu tri thức."},{"jp":"この海は魚の**宝庫**と言われています。","vi":"Vùng biển này được gọi là kho báu của các loài cá."}],
  "824": [{"jp":"インターネットで何でも**手に入ります**。","vi":"Trên mạng cái gì cũng có thể có được."},{"jp":"欲しかったチケットがやっと**手に入りました**。","vi":"Cuối cùng tôi cũng có được tấm vé mình mong muốn."}],
  "825": [{"jp":"壁の**一部分**が汚れています。","vi":"Một phần bức tường bị bẩn."},{"jp":"この映画は**一部分**しか見ていません。","vi":"Bộ phim này tôi mới chỉ xem một phần."}],
  "826": [{"jp":"ここにパスワードを**入力して**ください。","vi":"Hãy nhập mật khẩu vào đây."},{"jp":"名前と住所をパソコンに**入力しました**。","vi":"Tôi đã nhập tên và địa chỉ vào máy tính."}],
  "827": [{"jp":"1分は60**秒**です。","vi":"1 phút là 60 giây."},{"jp":"彼は100メートルを11**秒**で走ります。","vi":"Anh ấy chạy 100 mét trong 11 giây."}],
  "828": [{"jp":"好きな作家の新しい本が**出ました**。","vi":"Cuốn sách mới của tác giả tôi yêu thích đã được xuất bản."},{"jp":"今月、この雑誌の特別号が**出る**そうです。","vi":"Nghe nói tháng này số đặc biệt của tạp chí này sẽ được phát hành."}],
  "829": [{"jp":"駅の前に人がたくさん**集まって**います。","vi":"Trước nhà ga có rất nhiều người đang tụ tập."},{"jp":"お正月には家族みんなが祖父の家に**集まります**。","vi":"Vào dịp Tết, cả gia đình tụ họp ở nhà ông."}],
  "830": [{"jp":"学生たちは3つのグループに**別れて**話し合いました。","vi":"Các sinh viên chia thành 3 nhóm để thảo luận."},{"jp":"ここから二つのチームに**別れましょう**。","vi":"Từ đây chúng ta hãy tách thành hai đội."}],
  "831": [{"jp":"祖母は100歳まで**長生きしました**。","vi":"Bà tôi đã sống thọ đến 100 tuổi."},{"jp":"毎日運動している人は**長生きします**。","vi":"Người tập thể dục mỗi ngày thì sống lâu."}],
  "832": [{"jp":"雨が降ってきたので、傘を**差しました**。","vi":"Trời đổ mưa nên tôi đã che ô."},{"jp":"日差しが強いので、日傘を**差して**歩きます。","vi":"Nắng gắt nên tôi che ô che nắng khi đi bộ."}],
  "833": [{"jp":"昨日は**酷い**雨でした。","vi":"Hôm qua mưa rất to (thời tiết tồi tệ)."},{"jp":"友達に**酷い**ことを言って、後悔しています。","vi":"Tôi đã nói lời tệ hại với bạn và đang hối hận."}],
  "834": [{"jp":"夜の山道は**怖い**です。","vi":"Đường núi ban đêm thật đáng sợ."},{"jp":"子どものころ、犬が**怖かった**です。","vi":"Hồi nhỏ tôi sợ chó."}],
  "835": [{"jp":"明日の**天気予報**を見ましたか。","vi":"Bạn đã xem dự báo thời tiết ngày mai chưa?"},{"jp":"**天気予報**によると、午後から雨が降るそうです。","vi":"Theo dự báo thời tiết thì từ chiều trời sẽ mưa."}],
  "836": [{"jp":"明日、授業で**発表**をします。","vi":"Ngày mai tôi sẽ thuyết trình trong giờ học."},{"jp":"試験の結果は来週**発表**されます。","vi":"Kết quả thi sẽ được công bố vào tuần sau."}],
  "837": [{"jp":"理科の時間に**実験**をしました。","vi":"Trong giờ khoa học, chúng tôi đã làm thí nghiệm."},{"jp":"この新しい薬は動物で**実験**しました。","vi":"Loại thuốc mới này đã được thí nghiệm trên động vật."}],
  "838": [{"jp":"東京の**人口**は何人ぐらいですか。","vi":"Dân số Tokyo khoảng bao nhiêu người?"},{"jp":"この町は**人口**がだんだん減っています。","vi":"Dân số thị trấn này đang giảm dần."}],
  "839": [{"jp":"台所からいい**におい**がします。","vi":"Có mùi thơm từ bếp bay ra."},{"jp":"この花は甘い**におい**がします。","vi":"Bông hoa này có mùi ngọt ngào."}],
  "840": [{"jp":"**科学**が進歩して、生活が便利になりました。","vi":"Khoa học tiến bộ nên cuộc sống trở nên tiện lợi."},{"jp":"弟は**科学**の本を読むのが好きです。","vi":"Em trai tôi thích đọc sách khoa học."}],
  "841": [{"jp":"兄は大学で**医学**を勉強しています。","vi":"Anh trai tôi đang học y ở đại học."},{"jp":"**医学**の進歩で、多くの病気が治るようになりました。","vi":"Nhờ tiến bộ y học, nhiều bệnh đã có thể chữa khỏi."}],
  "842": [{"jp":"私は日本の**文学**に興味があります。","vi":"Tôi quan tâm đến văn học Nhật Bản."},{"jp":"姉は大学で**文学**を教えています。","vi":"Chị tôi dạy văn học ở đại học."}],
  "843": [{"jp":"道で人が倒れたので、**救急車**を呼びました。","vi":"Có người ngã quỵ trên đường nên tôi đã gọi xe cấp cứu."},{"jp":"遠くから**救急車**の音が聞こえます。","vi":"Nghe thấy tiếng xe cấp cứu từ xa."}],
  "844": [{"jp":"私はその意見に**賛成**です。","vi":"Tôi tán thành ý kiến đó."},{"jp":"クラスの全員が旅行の計画に**賛成**しました。","vi":"Cả lớp đều tán thành kế hoạch du lịch."}],
  "845": [{"jp":"父は私の留学に**反対**しています。","vi":"Bố tôi phản đối việc tôi đi du học."},{"jp":"町の人たちは新しい工場に**反対**しました。","vi":"Người dân thị trấn đã phản đối nhà máy mới."}],
  "846": [{"jp":"受付に背の高い**男性**がいます。","vi":"Ở quầy lễ tân có một người đàn ông cao."},{"jp":"この会社は**男性**の社員が多いです。","vi":"Công ty này có nhiều nhân viên nam."}],
  "847": [{"jp":"あの髪の長い**女性**は私の先生です。","vi":"Người phụ nữ tóc dài kia là cô giáo của tôi."},{"jp":"ここは**女性**に人気がある店です。","vi":"Đây là cửa hàng được phụ nữ ưa chuộng."}],
  "848": [{"jp":"天気予報**によると**、明日は雪が降るそうです。","vi":"Theo dự báo thời tiết thì ngày mai tuyết sẽ rơi."},{"jp":"新聞**によると**、駅前に新しいデパートができるそうです。","vi":"Theo báo thì trước ga sắp có một trung tâm thương mại mới."}],
  "849": [{"jp":"兄は**恋人**と映画を見に行きました。","vi":"Anh tôi đã đi xem phim với người yêu."},{"jp":"彼女には優しい**恋人**がいます。","vi":"Cô ấy có một người yêu dịu dàng."}],
  "850": [{"jp":"姉は去年**婚約しました**。","vi":"Chị tôi đã đính hôn vào năm ngoái."},{"jp":"二人は**婚約して**、来年結婚する予定です。","vi":"Hai người đã đính hôn và dự định kết hôn vào năm sau."}],
  "851": [{"jp":"テニスの**相手**がいなくて、困っています。","vi":"Không có người chơi tennis cùng nên tôi đang khó xử."},{"jp":"結婚の**相手**は優しい人がいいです。","vi":"Tôi muốn đối tượng kết hôn là người dịu dàng."}],
  "852": [{"jp":"妻とは大学で**知り合いました**。","vi":"Tôi quen vợ tôi ở trường đại học."},{"jp":"旅行で多くの人と**知り合う**ことができました。","vi":"Trong chuyến du lịch tôi đã được làm quen với nhiều người."}],
  "853": [{"jp":"日本人の**平均寿命**は長いです。","vi":"Tuổi thọ trung bình của người Nhật cao."},{"jp":"**平均寿命**は女性のほうが男性より長いです。","vi":"Tuổi thọ trung bình của nữ cao hơn nam."}],
  "854": [{"jp":"今年は去年と**比べて**暑いです。","vi":"Năm nay nóng hơn so với năm ngoái."},{"jp":"2つのパソコンの値段を**比べました**。","vi":"Tôi đã so sánh giá của hai chiếc máy tính."}],
  "855": [{"jp":"祖父は物理学の**博士**です。","vi":"Ông tôi là tiến sĩ vật lý."},{"jp":"子供のころ、虫が大好きで「虫**博士**」と呼ばれていました。","vi":"Hồi nhỏ tôi rất thích côn trùng nên được gọi là \"tiến sĩ côn trùng\"."}],
  "856": [{"jp":"**脳**は体の中でとても大切なところです。","vi":"Não là bộ phận rất quan trọng trong cơ thể."},{"jp":"寝ないと、**脳**がよく働きません。","vi":"Không ngủ thì não không hoạt động tốt."}],
  "857": [{"jp":"デパートの1階で**化粧品**を売っています。","vi":"Tầng 1 của trung tâm thương mại bán mỹ phẩm."},{"jp":"母の誕生日に**化粧品**をプレゼントしました。","vi":"Tôi đã tặng mỹ phẩm cho mẹ vào ngày sinh nhật."}],
  "858": [{"jp":"わからない言葉を辞書で**調べます**。","vi":"Tôi tra những từ không hiểu bằng từ điển."},{"jp":"警察が事故の原因を**調べて**います。","vi":"Cảnh sát đang điều tra nguyên nhân vụ tai nạn."}],
  "859": [{"jp":"姉は毎朝30分かけて**化粧**をします。","vi":"Chị tôi mỗi sáng mất 30 phút để trang điểm."},{"jp":"今日は**化粧**をしないで出かけました。","vi":"Hôm nay tôi ra ngoài mà không trang điểm."}],
  "860": [{"jp":"棚から荷物を**下ろして**ください。","vi":"Hãy hạ hành lý từ trên giá xuống."},{"jp":"タクシーの運転手さんに「駅の前で**降ろして**ください」と言いました。","vi":"Tôi nói với tài xế taxi: \"Cho tôi xuống ở trước ga.\""}],
  "861": [{"jp":"忘れ物を交番に**届けました**。","vi":"Tôi đã mang đồ bị bỏ quên đến đồn cảnh sát."},{"jp":"この荷物を明日までに**届けて**ください。","vi":"Hãy chuyển kiện hàng này đến trước ngày mai."}],
  "862": [{"jp":"毎日、犬の**世話をします**。","vi":"Hằng ngày tôi chăm sóc con chó."},{"jp":"入院したとき、看護師さんがよく**世話をして**くれました。","vi":"Khi tôi nằm viện, các y tá đã chăm sóc tôi rất chu đáo."}],
  "863": [{"jp":"雨の日は**嫌**です。","vi":"Tôi ghét những ngày mưa."},{"jp":"仕事を頼むと、彼は**嫌な**顔をしました。","vi":"Khi tôi nhờ việc, anh ấy tỏ vẻ mặt khó chịu."}],
  "864": [{"jp":"私の父はとても**厳しい**です。","vi":"Bố tôi rất nghiêm khắc."},{"jp":"この学校は規則が**厳しくて**、髪を染めてはいけません。","vi":"Trường này có quy định nghiêm ngặt, không được nhuộm tóc."}],
  "865": [{"jp":"息子は週に3回**塾**に通っています。","vi":"Con trai tôi đi học thêm 3 buổi một tuần."},{"jp":"高校の入試のために、**塾**で勉強しています。","vi":"Tôi đang học ở lớp luyện thi để thi vào cấp 3."}],
  "866": [{"jp":"この学校には**生徒**が500人います。","vi":"Trường này có 500 học sinh."},{"jp":"先生は**生徒**たちに作文を書かせました。","vi":"Giáo viên bắt các học sinh viết bài văn."}],
  "867": [{"jp":"担当の**者**が参りますので、少々お待ちください。","vi":"Người phụ trách của chúng tôi sẽ đến, xin vui lòng đợi một chút."},{"jp":"受付の**者**にお名前をお伝えください。","vi":"Xin quý khách vui lòng cho nhân viên lễ tân của chúng tôi biết tên."}],
  "868": [{"jp":"**入管**でビザの手続きをしました。","vi":"Tôi đã làm thủ tục visa ở Cục quản lý nhập cảnh."},{"jp":"在留カードを更新するために、**入管**へ行きます。","vi":"Tôi đến Cục quản lý nhập cảnh để gia hạn thẻ cư trú."}],
  "869": [{"jp":"国へ帰る前に、**再入国ビザ**を取りました。","vi":"Trước khi về nước, tôi đã xin thị thực tái nhập cảnh."},{"jp":"**再入国ビザ**がないと、日本に戻れませんよ。","vi":"Không có thị thực tái nhập cảnh thì không quay lại Nhật được đâu."}],
  "870": [{"jp":"ここにある本は**自由に**読んでもいいです。","vi":"Sách ở đây có thể đọc thoải mái."},{"jp":"日曜日は時間を**自由に**使えます。","vi":"Chủ nhật tôi có thể sử dụng thời gian tự do."}],
  "871": [{"jp":"1週**間**、日本を旅行しました。","vi":"Tôi đã du lịch Nhật Bản trong 1 tuần."},{"jp":"3日**間**、熱が下がりませんでした。","vi":"Suốt 3 ngày, cơn sốt không hạ."}],
  "872": [{"jp":"先生、今**お忙しいですか**。","vi":"Thưa thầy, bây giờ thầy có bận không ạ?"},{"jp":"「部長、今週は**お忙しいですか**。」「ええ、ちょっと。」","vi":"\"Thưa trưởng phòng, tuần này anh có bận không ạ?\" \"Ừ, hơi bận.\""}],
  "873": [{"jp":"**久しぶり**に国の友達に会いました。","vi":"Lâu lắm rồi tôi mới gặp lại bạn ở quê."},{"jp":"「お**久しぶり**です。お元気でしたか。」","vi":"\"Lâu quá không gặp. Anh vẫn khỏe chứ?\""}],
  "874": [{"jp":"この店は夜10時まで**営業**しています。","vi":"Cửa hàng này mở cửa kinh doanh đến 10 giờ tối."},{"jp":"兄は会社で**営業**の仕事をしています。","vi":"Anh tôi làm công việc kinh doanh (bán hàng) ở công ty."}],
  "875": [{"jp":"会議は3時からです。**それまでに**資料を準備してください。","vi":"Cuộc họp bắt đầu từ 3 giờ. Trước lúc đó hãy chuẩn bị tài liệu."},{"jp":"来月引っ越します。**それまでに**部屋を片付けなければなりません。","vi":"Tháng sau tôi chuyển nhà. Trước thời điểm đó phải dọn phòng."}],
  "876": [{"jp":"ここでたばこを吸っても**構いません**。","vi":"Hút thuốc ở đây cũng không sao."},{"jp":"「窓を開けてもいいですか。」「ええ、**構いません**よ。」","vi":"\"Tôi mở cửa sổ được không?\" \"Vâng, không sao đâu.\""}],
  "877": [{"jp":"週末は家族とキャンプを**楽しみました**。","vi":"Cuối tuần tôi đã vui vẻ cắm trại cùng gia đình."},{"jp":"日本で温泉を**楽しみたい**です。","vi":"Tôi muốn tận hưởng suối nước nóng ở Nhật."}],
  "878": [{"jp":"この建物は**元々**学校でした。","vi":"Tòa nhà này vốn là trường học."},{"jp":"彼は**元々**体が弱かったです。","vi":"Anh ấy vốn dĩ có thể trạng yếu."}],
  "879": [{"jp":"この寺は8**世紀**に建てられました。","vi":"Ngôi chùa này được xây vào thế kỷ 8."},{"jp":"21**世紀**は科学の時代だと言われています。","vi":"Người ta nói thế kỷ 21 là thời đại của khoa học."}],
  "880": [{"jp":"母が病気なので、私が母の**代わりをします**。","vi":"Mẹ bị ốm nên tôi làm thay mẹ."},{"jp":"先生が休みの日は、別の先生が**代わりをして**くれます。","vi":"Hôm thầy nghỉ thì có thầy khác dạy thay."}],
  "881": [{"jp":"公園で弟と**競走しました**。","vi":"Tôi đã chạy đua với em trai ở công viên."},{"jp":"運動会で、みんなで**競走して**遊びました。","vi":"Ở hội thao, mọi người đã thi chạy với nhau cho vui."}],
  "882": [{"jp":"この犬はいろいろな**芸**ができます。","vi":"Con chó này biết làm nhiều trò."},{"jp":"パーティーで兄が面白い**芸**を見せてくれました。","vi":"Ở bữa tiệc, anh tôi đã biểu diễn một tiết mục thú vị."}],
  "883": [{"jp":"富士山はとても**美しい**山です。","vi":"Núi Phú Sĩ là ngọn núi rất đẹp."},{"jp":"彼女は**美しい**声で歌いました。","vi":"Cô ấy đã hát bằng giọng hát rất hay."}],
  "884": [{"jp":"鏡で自分の**姿**を見ました。","vi":"Tôi nhìn dáng mình trong gương."},{"jp":"駅で彼の**姿**が見えなくなるまで手を振りました。","vi":"Ở ga, tôi vẫy tay cho đến khi không còn thấy bóng dáng anh ấy."}],
  "885": [{"jp":"彼は**心**の優しい人です。","vi":"Anh ấy là người có tấm lòng nhân hậu."},{"jp":"その映画は私の**心**に残りました。","vi":"Bộ phim đó đọng lại trong lòng tôi."}],
  "886": [{"jp":"私**にとって**、家族はいちばん大切です。","vi":"Đối với tôi, gia đình là quan trọng nhất."},{"jp":"この問題は子供**にとって**難しすぎます。","vi":"Bài này quá khó đối với trẻ em."}],
  "887": [{"jp":"父は銀行に**勤めて**います。","vi":"Bố tôi làm việc ở ngân hàng."},{"jp":"姉は東京の会社に10年**勤めました**。","vi":"Chị tôi đã làm việc ở một công ty tại Tokyo 10 năm."}],
  "888": [{"jp":"風邪をひいたので、会社を**休みました**。","vi":"Bị cảm nên tôi đã nghỉ làm."},{"jp":"疲れたでしょう。今日は早く**休んで**ください。","vi":"Chắc mệt rồi. Hôm nay hãy đi ngủ sớm nhé."}],
  "889": [{"jp":"どうぞ、こちらに**お掛け**ください。","vi":"Xin mời ngồi đây ạ."},{"jp":"疲れたので、いすに**掛けて**休みました。","vi":"Mệt nên tôi ngồi xuống ghế nghỉ."}],
  "890": [{"jp":"夏休みは海の近くで**過ごしました**。","vi":"Kỳ nghỉ hè tôi đã sống ở gần biển."},{"jp":"週末は家族とゆっくり**過ごしたい**です。","vi":"Cuối tuần tôi muốn thong thả ở bên gia đình."}],
  "891": [{"jp":"帰りにスーパーに**寄って**、牛乳を買いました。","vi":"Trên đường về tôi ghé siêu thị mua sữa."},{"jp":"近くに来たら、ぜひうちに**寄って**ください。","vi":"Nếu đến gần đây thì nhất định ghé nhà tôi nhé."}],
  "892": [{"jp":"社長は今会議室に**いらっしゃいます**。","vi":"Giám đốc hiện đang ở phòng họp."},{"jp":"先生は明日京都へ**いらっしゃいます**。","vi":"Ngày mai thầy sẽ đi Kyoto."}],
  "893": [{"jp":"先生は毎朝パンを**召し上がります**。","vi":"Sáng nào thầy cũng dùng bánh mì."},{"jp":"どうぞ、冷めないうちに**召し上がって**ください。","vi":"Xin mời dùng khi còn nóng ạ."}],
  "894": [{"jp":"先生が「明日は休みです」と**おっしゃいました**。","vi":"Thầy đã nói: \"Ngày mai được nghỉ.\""},{"jp":"すみません、もう一度**おっしゃって**ください。","vi":"Xin lỗi, xin ngài nói lại một lần nữa."}],
  "895": [{"jp":"週末は何を**なさいます**か。","vi":"Cuối tuần ngài sẽ làm gì ạ?"},{"jp":"社長は毎朝ゴルフの練習を**なさいます**。","vi":"Sáng nào giám đốc cũng tập golf."}],
  "896": [{"jp":"先生はもうこの映画を**ご覧になりました**か。","vi":"Thầy đã xem bộ phim này chưa ạ?"},{"jp":"社長は毎晩ニュースを**ご覧になります**。","vi":"Tối nào giám đốc cũng xem tin tức."}],
  "897": [{"jp":"先生はこの言葉の意味を**ご存じです**か。","vi":"Thầy có biết nghĩa của từ này không ạ?"},{"jp":"部長はその話をもう**ご存じです**。","vi":"Trưởng phòng đã biết chuyện đó rồi."}],
  "898": [{"jp":"朝、近所の人に**挨拶**をしました。","vi":"Buổi sáng tôi chào hỏi hàng xóm."},{"jp":"結婚式で社長が**挨拶**をしました。","vi":"Giám đốc đã phát biểu chào mừng ở lễ cưới."}],
  "899": [{"jp":"すみません、**灰皿**をください。","vi":"Xin lỗi, cho tôi cái gạt tàn."},{"jp":"ここは禁煙なので、テーブルに**灰皿**がありません。","vi":"Ở đây cấm hút thuốc nên trên bàn không có gạt tàn."}],
  "900": [{"jp":"京都で古い**旅館**に泊まりました。","vi":"Tôi đã nghỉ tại một lữ quán cổ ở Kyoto."},{"jp":"この**旅館**には大きいお風呂があります。","vi":"Lữ quán này có bồn tắm lớn."}],
  "901": [{"jp":"コンサートの**会場**はたくさんの人でいっぱいでした。","vi":"Hội trường buổi hòa nhạc chật kín người."},{"jp":"試験の**会場**まで電車で30分かかります。","vi":"Đi tàu đến địa điểm thi mất 30 phút."}],
  "902": [{"jp":"**バス停**でバスを待っています。","vi":"Tôi đang đợi xe buýt ở bến."},{"jp":"うちから**バス停**まで歩いて5分です。","vi":"Từ nhà tôi đến bến xe buýt đi bộ mất 5 phút."}],
  "903": [{"jp":"父は**貿易**会社で働いています。","vi":"Bố tôi làm việc ở một công ty thương mại (xuất nhập khẩu)."},{"jp":"日本とベトナムの**貿易**は年々増えています。","vi":"Thương mại giữa Nhật Bản và Việt Nam tăng lên hàng năm."}],
  "904": [{"jp":"田中**様**、受付までお越しください。","vi":"Ông/bà Tanaka, xin mời đến quầy lễ tân."},{"jp":"封筒に「山田花子**様**」と書きました。","vi":"Tôi viết \"Kính gửi bà Yamada Hanako\" lên phong bì."}],
  "905": [{"jp":"**帰りに**本屋に寄りました。","vi":"Trên đường về tôi đã ghé hiệu sách."},{"jp":"学校の**帰りに**友達とアイスを食べました。","vi":"Trên đường đi học về, tôi ăn kem với bạn."}],
  "906": [{"jp":"**偶に**家族で外食します。","vi":"Thỉnh thoảng gia đình tôi đi ăn ngoài."},{"jp":"普段は電車ですが、**偶に**自転車で会社へ行きます。","vi":"Bình thường tôi đi tàu nhưng thỉnh thoảng đạp xe đi làm."}],
  "907": [{"jp":"この本は**ちっとも**面白くありません。","vi":"Cuốn sách này chẳng thú vị chút nào."},{"jp":"勉強しているのに、**ちっとも**上手になりません。","vi":"Học mãi mà chẳng giỏi lên tí nào."}],
  "908": [{"jp":"わからないことがあったら、**遠慮なく**聞いてください。","vi":"Có gì không hiểu thì cứ hỏi, đừng ngại."},{"jp":"「どうぞ召し上がってください。」「では、**遠慮なく**いただきます。」","vi":"\"Xin mời dùng.\" \"Vậy tôi xin phép không khách sáo.\""}],
  "909": [{"jp":"私は**3年2組**です。","vi":"Tôi học lớp 2 năm thứ 3 (lớp 3-2)."},{"jp":"**1年5組**の担任は山田先生です。","vi":"Giáo viên chủ nhiệm lớp 1-5 là thầy Yamada."}],
  "910": [{"jp":"**では**、会議を始めます。","vi":"Thế thì, chúng ta bắt đầu cuộc họp."},{"jp":"「明日は雨だそうです。」「**では**、旅行はやめましょう。」","vi":"\"Nghe nói ngày mai mưa.\" \"Thế thì thôi không đi du lịch nữa.\""}],
  "911": [{"jp":"子供が熱を**出して**、学校を休みました。","vi":"Con tôi bị sốt nên đã nghỉ học."},{"jp":"昨日39度の熱を**出しました**。","vi":"Hôm qua tôi bị sốt 39 độ."}],
  "912": [{"jp":"お母さんに**よろしくお伝えください**。","vi":"Cho tôi gửi lời hỏi thăm mẹ bạn."},{"jp":"「では、また来週。」「ええ、皆さんに**よろしくお伝えください**。」","vi":"\"Vậy hẹn tuần sau nhé.\" \"Vâng, cho tôi gửi lời hỏi thăm mọi người.\""}],
  "913": [{"jp":"会議がありますので、お先に**失礼いたします**。","vi":"Vì có cuộc họp nên tôi xin phép về trước."},{"jp":"「どうぞお入りください。」「**失礼いたします**。」","vi":"\"Mời vào.\" \"Tôi xin phép.\""}],
  "914": [{"jp":"兄は大学で**講師**をしています。","vi":"Anh tôi làm giảng viên ở đại học."},{"jp":"今日の**講師**は有名な作家です。","vi":"Giảng viên hôm nay là một nhà văn nổi tiếng."}],
  "915": [{"jp":"この祭りには**多くの**人が来ます。","vi":"Lễ hội này có rất nhiều người đến."},{"jp":"彼は**多くの**国を旅行しました。","vi":"Anh ấy đã du lịch nhiều nước."}],
  "916": [{"jp":"これは有名な画家の**作品**です。","vi":"Đây là tác phẩm của một họa sĩ nổi tiếng."},{"jp":"美術館で子供たちの**作品**が見られます。","vi":"Ở bảo tàng mỹ thuật có thể xem tác phẩm của các em nhỏ."}],
  "917": [{"jp":"彼の映画は大きな賞を**受賞しました**。","vi":"Bộ phim của anh ấy đã đoạt một giải thưởng lớn."},{"jp":"ノーベル賞を**受賞した**人の話を聞きました。","vi":"Tôi đã nghe bài nói chuyện của người đoạt giải Nobel."}],
  "918": [{"jp":"彼は**世界的に**有名な歌手です。","vi":"Anh ấy là ca sĩ nổi tiếng tầm cỡ thế giới."},{"jp":"この会社の車は**世界的に**人気があります。","vi":"Xe của công ty này được ưa chuộng trên toàn thế giới."}],
  "919": [{"jp":"将来、小説を書く**作家**になりたいです。","vi":"Sau này tôi muốn trở thành nhà văn viết tiểu thuyết."},{"jp":"この本を書いた**作家**は若い女性です。","vi":"Nhà văn viết cuốn sách này là một phụ nữ trẻ."}],
  "920": [{"jp":"こちらは山田先生の奥様**でいらっしゃいます**。","vi":"Đây là phu nhân của thầy Yamada."},{"jp":"失礼ですが、田中様**でいらっしゃいます**か。","vi":"Xin lỗi, có phải ông Tanaka không ạ?"}],
  "921": [{"jp":"私は家族の**長男**です。","vi":"Tôi là con trai trưởng trong gia đình."},{"jp":"田中さんの**長男**は今年大学に入りました。","vi":"Con trai cả của anh Tanaka năm nay đã vào đại học."}],
  "922": [{"jp":"彼は目に**障害**がありますが、ピアノがとても上手です。","vi":"Anh ấy bị khuyết tật ở mắt nhưng chơi piano rất giỏi."},{"jp":"言葉の違いが大きな**障害**になりました。","vi":"Sự khác biệt ngôn ngữ đã trở thành trở ngại lớn."}],
  "923": [{"jp":"先生は車を**お持ちです**か。","vi":"Thầy có xe hơi không ạ?"},{"jp":"社長は別荘を2つ**お持ちです**。","vi":"Giám đốc có 2 căn biệt thự."}],
  "924": [{"jp":"この歌は有名な音楽家が**作曲**しました。","vi":"Bài hát này do một nhạc sĩ nổi tiếng sáng tác."},{"jp":"趣味はギターを弾きながら**作曲**することです。","vi":"Sở thích của tôi là vừa chơi guitar vừa sáng tác nhạc."}],
  "925": [{"jp":"大学でボランティア**活動**をしています。","vi":"Tôi đang tham gia hoạt động tình nguyện ở đại học."},{"jp":"放課後のクラブ**活動**は楽しいです。","vi":"Hoạt động câu lạc bộ sau giờ học rất vui."}],
  "926": [{"jp":"**それでは**、今日の授業を始めましょう。","vi":"Vậy thì, chúng ta bắt đầu bài học hôm nay."},{"jp":"**それでは**、次のニュースです。","vi":"Sau đây là bản tin tiếp theo."}],
  "927": [{"jp":"明日、私が空港までお迎えに**参ります**。","vi":"Ngày mai tôi sẽ ra sân bay đón ngài."},{"jp":"来月、大阪へ出張に**参ります**。","vi":"Tháng sau tôi sẽ đi công tác Osaka."}],
  "928": [{"jp":"私は今東京に住んで**おります**。","vi":"Tôi hiện đang sống ở Tokyo."},{"jp":"明日は一日中事務所に**おります**。","vi":"Ngày mai tôi ở văn phòng cả ngày."}],
  "929": [{"jp":"先生にお土産を**頂きました**。","vi":"Tôi đã nhận được quà từ thầy."},{"jp":"では、お茶を**頂きます**。","vi":"Vậy tôi xin phép dùng trà."}],
  "930": [{"jp":"はじめまして。グエンと**申します**。","vi":"Rất hân hạnh được gặp. Tôi tên là Nguyễn."},{"jp":"父が「よろしく」と**申して**おりました。","vi":"Bố tôi có nói gửi lời hỏi thăm ạ."}],
  "931": [{"jp":"会議の資料は私がコピー**いたします**。","vi":"Tài liệu họp để tôi photo ạ."},{"jp":"お荷物は明日お届け**いたします**。","vi":"Hành lý của quý khách sẽ được giao vào ngày mai."}],
  "932": [{"jp":"お手紙を**拝見しました**。","vi":"Tôi đã đọc thư của ngài."},{"jp":"お客様、チケットを**拝見します**。","vi":"Thưa quý khách, cho phép tôi xem vé."}],
  "933": [{"jp":"その件はよく**存じて**おります。","vi":"Tôi biết rõ việc đó."},{"jp":"申し訳ありませんが、その方のお名前は**存じません**。","vi":"Rất xin lỗi, tôi không biết tên của vị đó."}],
  "934": [{"jp":"明日の午後、お宅に**伺います**。","vi":"Chiều mai tôi sẽ đến thăm nhà ngài."},{"jp":"ちょっと**伺いたい**ことがあるのですが。","vi":"Tôi có chút việc muốn hỏi ạ."}],
  "935": [{"jp":"明日、社長に**お目にかかります**。","vi":"Ngày mai tôi sẽ gặp giám đốc."},{"jp":"また**お目にかかれる**のを楽しみにしております。","vi":"Tôi rất mong được gặp lại ngài."}],
  "936": [{"jp":"トイレはあちらに**ございます**。","vi":"Nhà vệ sinh ở đằng kia ạ."},{"jp":"何かご質問は**ございます**か。","vi":"Quý vị có câu hỏi gì không ạ?"}],
  "937": [{"jp":"お電話ありがとうございます。さくらホテル**でございます**。","vi":"Cảm ơn quý khách đã gọi điện. Đây là khách sạn Sakura."},{"jp":"こちらが会議室**でございます**。","vi":"Đây là phòng họp ạ."}],
  "938": [{"jp":"**私**、ABC会社のグエンと申します。","vi":"Tôi là Nguyễn của công ty ABC."},{"jp":"その件は**私**が担当いたします。","vi":"Việc đó tôi xin phụ trách."}],
  "939": [{"jp":"旅行の**ガイド**が町を案内してくれました。","vi":"Hướng dẫn viên du lịch đã dẫn chúng tôi đi tham quan thị trấn."},{"jp":"将来、日本語の**ガイド**になりたいです。","vi":"Sau này tôi muốn làm hướng dẫn viên tiếng Nhật."}],
  "940": [{"jp":"先生の**お宅**はどちらですか。","vi":"Nhà của thầy ở đâu ạ?"},{"jp":"昨日、田中さんの**お宅**に伺いました。","vi":"Hôm qua tôi đã đến thăm nhà anh Tanaka."}],
  "941": [{"jp":"私の家は東京の**郊外**にあります。","vi":"Nhà tôi ở ngoại ô Tokyo."},{"jp":"**郊外**は空気がきれいで静かです。","vi":"Vùng ngoại ô không khí trong lành và yên tĩnh."}],
  "942": [{"jp":"家族の写真を**アルバム**に入れました。","vi":"Tôi đã cho ảnh gia đình vào album."},{"jp":"好きな歌手の新しい**アルバム**を買いました。","vi":"Tôi đã mua album mới của ca sĩ mình yêu thích."}],
  "943": [{"jp":"**再来週**の月曜日に試験があります。","vi":"Thứ Hai tuần sau nữa có kỳ thi."},{"jp":"国から両親が**再来週**来ます。","vi":"Tuần sau nữa bố mẹ tôi sẽ từ quê sang."}],
  "944": [{"jp":"**再来月**、引っ越します。","vi":"Tháng sau nữa tôi sẽ chuyển nhà."},{"jp":"姉の結婚式は**再来月**の10日です。","vi":"Đám cưới của chị tôi vào ngày 10 tháng sau nữa."}],
  "945": [{"jp":"**再来年**、大学を卒業します。","vi":"Năm sau nữa tôi sẽ tốt nghiệp đại học."},{"jp":"駅の近くの新しいビルは**再来年**できるそうです。","vi":"Nghe nói tòa nhà mới gần ga sẽ hoàn thành vào năm sau nữa."}],
  "946": [{"jp":"日本に来て**半年**になりました。","vi":"Tôi đến Nhật đã được nửa năm."},{"jp":"この工事は**半年**かかります。","vi":"Công trình này mất nửa năm."}],
  "947": [{"jp":"**最初に**名前を書いてください。","vi":"Trước hết hãy viết tên."},{"jp":"日本に来て、**最初に**覚えた言葉は「すみません」です。","vi":"Từ đầu tiên tôi học được khi đến Nhật là \"sumimasen\"."}],
  "948": [{"jp":"**最後に**、電気を消して出てください。","vi":"Cuối cùng, hãy tắt điện rồi ra ngoài."},{"jp":"スピーチの**最後に**、「ありがとうございました」と言いました。","vi":"Cuối bài phát biểu, tôi nói \"Xin cảm ơn\"."}],
  "949": [{"jp":"社長は**ただ今**外出しております。","vi":"Giám đốc hiện đang ra ngoài ạ."},{"jp":"「**ただ今**。」「お帰りなさい。」","vi":"\"Con về rồi ạ.\" \"Con đã về đấy à.\""}],
  "950": [{"jp":"面接の前は、とても**緊張します**。","vi":"Trước buổi phỏng vấn tôi rất căng thẳng."},{"jp":"初めてのスピーチで**緊張して**、声が震えました。","vi":"Lần đầu phát biểu tôi căng thẳng đến run cả giọng."}],
  "951": [{"jp":"その番組は毎週土曜日に**放送されます**。","vi":"Chương trình đó được phát sóng vào thứ Bảy hằng tuần."},{"jp":"駅で、電車が遅れているという**放送**がありました。","vi":"Ở ga có thông báo phát thanh rằng tàu bị trễ."}],
  "952": [{"jp":"子供の運動会をビデオに**撮りました**。","vi":"Tôi đã quay video hội thao của con."},{"jp":"美しい景色をスマホで**撮って**、友達に送りました。","vi":"Tôi quay phong cảnh đẹp bằng điện thoại rồi gửi cho bạn."}],
  "953": [{"jp":"大会で優勝して、**賞金**をもらいました。","vi":"Tôi vô địch giải đấu và nhận được tiền thưởng."},{"jp":"その**賞金**で両親に旅行をプレゼントしました。","vi":"Tôi dùng số tiền thưởng đó tặng bố mẹ một chuyến du lịch."}],
  "954": [{"jp":"この町は**自然**が豊かです。","vi":"Thị trấn này có thiên nhiên phong phú."},{"jp":"この写真の笑顔はとても**自然**です。","vi":"Nụ cười trong bức ảnh này rất tự nhiên."}],
  "955": [{"jp":"動物園で**象**を見ました。","vi":"Tôi đã xem voi ở sở thú."},{"jp":"**象**は鼻が長いです。","vi":"Con voi có vòi dài."}],
  "956": [{"jp":"子供の**頃**、よく川で泳ぎました。","vi":"Hồi nhỏ tôi hay bơi ở sông."},{"jp":"桜が咲く**頃**に日本へ行きたいです。","vi":"Tôi muốn đi Nhật vào khoảng lúc hoa anh đào nở."}],
  "957": [{"jp":"長い間の夢が**かないました**。","vi":"Giấc mơ bấy lâu nay đã thành hiện thực."},{"jp":"努力すれば、願いはきっと**かなう**と思います。","vi":"Tôi nghĩ nếu nỗ lực thì mong ước nhất định sẽ thành hiện thực."}],
  "958": [{"jp":"部長、その件について**一言よろしいでしょうか**。","vi":"Thưa trưởng phòng, về việc đó cho tôi nói vài lời được không ạ?"},{"jp":"「**一言よろしいでしょうか**。」「はい、どうぞ。」","vi":"\"Cho tôi nói vài lời được không ạ?\" \"Vâng, xin mời.\""}],
  "959": [{"jp":"みんなで**協力して**教室を掃除しました。","vi":"Mọi người cùng hợp tác dọn dẹp lớp học."},{"jp":"アンケートにご**協力**ください。","vi":"Xin quý vị vui lòng hợp tác trả lời bảng khảo sát."}],
  "960": [{"jp":"**心から**お礼を申し上げます。","vi":"Tôi xin chân thành cảm ơn."},{"jp":"お二人の幸せを**心から**祈っています。","vi":"Tôi chân thành cầu chúc hạnh phúc cho hai bạn."}],
  "961": [{"jp":"両親にはいつも**感謝して**います。","vi":"Tôi luôn biết ơn bố mẹ."},{"jp":"皆様のご協力に**感謝いたします**。","vi":"Xin cảm tạ sự hợp tác của quý vị."}],
  "962": [{"jp":"手伝ってくれた友達に**お礼**を言いました。","vi":"Tôi đã nói lời cảm ơn người bạn đã giúp mình."},{"jp":"お世話になった先生に**お礼**の手紙を書きました。","vi":"Tôi đã viết thư cảm ơn thầy giáo đã giúp đỡ mình."}],
  "963": [{"jp":"**拝啓**　春の暖かい季節になりました。","vi":"Kính gửi... Mùa xuân ấm áp đã đến."},{"jp":"手紙の初めに「**拝啓**」と書いたら、終わりには「敬具」と書きます。","vi":"Nếu đầu thư viết \"Haikei\" (Kính gửi) thì cuối thư viết \"Keigu\" (Kính thư)."}],
  "964": [{"jp":"秋の**美しい**紅葉を見に行きました。","vi":"Tôi đã đi ngắm lá đỏ mùa thu tuyệt đẹp."},{"jp":"この町は夜景が**美しい**ことで有名です。","vi":"Thị trấn này nổi tiếng với cảnh đêm đẹp."}],
  "965": [{"jp":"先生、**お元気でいらっしゃいますか**。","vi":"Thưa thầy, thầy có khỏe không ạ?"},{"jp":"皆様、**お元気でいらっしゃいますか**。私は元気に過ごしております。","vi":"Quý vị có khỏe không ạ? Tôi vẫn sống khỏe mạnh."}],
  "966": [{"jp":"遅刻して、みんなに**迷惑をかけて**しまいました。","vi":"Tôi đến muộn và đã làm phiền mọi người."},{"jp":"夜遅く大きな音を出して、近所に**迷惑をかけない**でください。","vi":"Đừng gây tiếng ồn lớn vào đêm khuya làm phiền hàng xóm."}],
  "967": [{"jp":"日本語を**生かして**、通訳の仕事をしたいです。","vi":"Tôi muốn tận dụng tiếng Nhật để làm công việc phiên dịch."},{"jp":"留学の経験を仕事に**生かす**つもりです。","vi":"Tôi định phát huy kinh nghiệm du học vào công việc."}],
  "968": [{"jp":"大阪で有名な**お城**を見ました。","vi":"Tôi đã ngắm tòa lâu đài nổi tiếng ở Osaka."},{"jp":"この**お城**は400年前に建てられました。","vi":"Lâu đài này được xây dựng 400 năm trước."}],
  "969": [{"jp":"手紙の最後に「**敬具**」と書きました。","vi":"Tôi đã viết \"Keigu\" ở cuối thư."},{"jp":"拝啓で始めた手紙は、**敬具**で終わります。","vi":"Thư bắt đầu bằng \"Haikei\" thì kết thúc bằng \"Keigu\"."}]
});
